INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-001', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-001", "kpi_name": "Total Active Headcount", "kpi_module": "HR", "sub_area": "Workforce", "is_active": true, "definition": "Number of active employees at the end of the period", "formula": "COUNT(Employee WHERE status=''Active'')", "unit": "Persons", "direction": "Range", "target": "Aligned with headcount plan", "frequency": "Monthly", "owner_role": "HR Manager", "source_doctypes": "Employee", "key_fields": "status, company, organization_unit", "platform_equivalent": "Workday: Headcount; SAP SF: Headcount (Employee Central); NetSuite: Employee saved search; M365: Power BI", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_001", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT COUNT(*) AS value FROM reporting.employee WHERE status = ''Active''"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-002', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-002", "kpi_name": "Headcount vs Filled Positions", "kpi_module": "HR", "sub_area": "Workforce", "is_active": true, "definition": "Ratio of filled positions to total active positions (Vacant + Filled)", "formula": "COUNT(Position status=''Filled'') / COUNT(Position status IN (''Filled'',''Vacant'')) x100", "unit": "%", "direction": "Up", "target": "≥ 95%", "frequency": "Monthly", "owner_role": "HR Manager", "source_doctypes": "Position", "key_fields": "status", "platform_equivalent": "Workday: Position Fill Rate; SAP SF: Position Management", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_002", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE status = ''Filled'')) / NULLIF(COUNT(*) FILTER (WHERE status IN (''Filled'',''Vacant'')), 0), 2) AS value FROM reporting.position"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-003', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-003", "kpi_name": "Vacancy Rate", "kpi_module": "HR", "sub_area": "Workforce", "is_active": true, "definition": "Percentage of vacant positions", "formula": "COUNT(Position status=''Vacant'') / COUNT(Position status IN (''Filled'',''Vacant'')) x100", "unit": "%", "direction": "Down", "target": "≤ 5%", "frequency": "Monthly", "owner_role": "HR Manager", "source_doctypes": "Position", "key_fields": "status", "platform_equivalent": "Workday: Open Positions", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_003", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE status = ''Vacant'')) / NULLIF(COUNT(*) FILTER (WHERE status IN (''Filled'',''Vacant'')), 0), 2) AS value FROM reporting.position"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-004', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-004", "kpi_name": "Frozen Position Count", "kpi_module": "HR", "sub_area": "Workforce", "is_active": true, "definition": "Number of frozen positions", "formula": "COUNT(Position status=''Frozen'')", "unit": "Positions", "direction": "Range", "target": "Per efficiency policy", "frequency": "Monthly", "owner_role": "HR Manager", "source_doctypes": "Position", "key_fields": "status", "platform_equivalent": "Workday / SAP SF Position Management", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_004", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT COUNT(*) AS value FROM reporting.position WHERE status = ''Frozen''"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-005', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-005", "kpi_name": "Span of Control", "kpi_module": "HR", "sub_area": "Workforce", "is_active": true, "definition": "Average number of direct reports per supervisor", "formula": "COUNT(Active employees) / COUNT(DISTINCT reports_to)", "unit": "Ratio", "direction": "Range", "target": "5–10 subordinates", "frequency": "Quarterly", "owner_role": "HRBP", "source_doctypes": "Employee", "key_fields": "reports_to, status", "platform_equivalent": "Workday: Span of Control; SAP SF Workforce Analytics", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_005", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT ROUND(COUNT(*)::numeric / NULLIF(COUNT(DISTINCT reports_to), 0), 2) AS value FROM reporting.employee WHERE status = ''Active'' AND reports_to IS NOT NULL"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-006', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-006", "kpi_name": "Manager Ratio", "kpi_module": "HR", "sub_area": "Workforce", "is_active": true, "definition": "Percentage of managerial positions out of total positions", "formula": "COUNT(Position is_manager_position=1) / COUNT(Position) x100", "unit": "%", "direction": "Range", "target": "10–15%", "frequency": "Quarterly", "owner_role": "HRBP", "source_doctypes": "Position", "key_fields": "is_manager_position", "platform_equivalent": "Workday: Management Ratio", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_006", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE is_manager_position)) / NULLIF(COUNT(*) FILTER (WHERE status <> ''Closed''), 0), 2) AS value FROM reporting.position WHERE status <> ''Closed''"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-007', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-007", "kpi_name": "Gender Composition", "kpi_module": "HR", "sub_area": "Workforce", "is_active": true, "definition": "Percentage of female employees in active headcount", "formula": "COUNT(Employee gender=''Female'' AND status=''Active'') / COUNT(Active employees) x100", "unit": "%", "direction": "Range", "target": "Per D&I target", "frequency": "Quarterly", "owner_role": "HR Manager", "source_doctypes": "Employee", "key_fields": "gender, status", "platform_equivalent": "Workday: Diversity dashboard; SAP SF People Analytics", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_007", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT COALESCE(gender, ''(blank)'') AS label, COUNT(*) AS value FROM reporting.employee WHERE status = ''Active'' GROUP BY 1 ORDER BY 2 DESC"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-008', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-008", "kpi_name": "Average Employee Age", "kpi_module": "HR", "sub_area": "Workforce", "is_active": true, "definition": "Average age of active employees", "formula": "AVG(DATEDIFF(year, date_of_birth, CURRENT_DATE)) WHERE status=''Active''", "unit": "Years", "direction": "Range", "target": "Per talent strategy", "frequency": "Quarterly", "owner_role": "HR Manager", "source_doctypes": "Employee", "key_fields": "date_of_birth, status", "platform_equivalent": "Workday / SAP SF demographic report", "implementation": "Not available", "implementation_note": "Source fields are restricted in reporting schema (permLevel 1 or attachment), so it cannot be computed by a widget."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-009', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-009", "kpi_name": "Average Tenure", "kpi_module": "HR", "sub_area": "Workforce", "is_active": true, "definition": "Average length of service of active employees", "formula": "AVG(DATEDIFF(month, original_hire_date OR hire_date, CURRENT_DATE))/12", "unit": "Years", "direction": "Up", "target": "≥ 3 years", "frequency": "Quarterly", "owner_role": "HR Manager", "source_doctypes": "Employee", "key_fields": "hire_date, original_hire_date", "platform_equivalent": "Workday: Average Tenure", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_009", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT ROUND(AVG((CURRENT_DATE - COALESCE(original_hire_date, hire_date)) / 365.25), 1) AS value FROM reporting.employee WHERE status = ''Active''"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-010', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-010", "kpi_name": "Employment Status Composition", "kpi_module": "HR", "sub_area": "Workforce", "is_active": true, "definition": "Percentage of employees by employment type (Permanent/Fixed-term Contract/etc.)", "formula": "COUNT(Employee per employment_type) / COUNT(Active employees) x100", "unit": "%", "direction": "Range", "target": "Per contract employment policy", "frequency": "Monthly", "owner_role": "HR Manager", "source_doctypes": "Employee", "key_fields": "employment_type, status", "platform_equivalent": "SAP SF Employee Central; Workday Worker Type", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_010", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT COALESCE(employment_type, ''(blank)'') AS label, COUNT(*) AS value FROM reporting.employee WHERE status = ''Active'' GROUP BY 1 ORDER BY 2 DESC"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-011', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-011", "kpi_name": "Employees on Probation", "kpi_module": "HR", "sub_area": "Workforce", "is_active": true, "definition": "Number of active employees whose probation end date has not passed", "formula": "COUNT(Employee WHERE probation_end_date >= CURRENT_DATE AND status=''Active'')", "unit": "Persons", "direction": "Range", "target": "—", "frequency": "Monthly", "owner_role": "HRBP", "source_doctypes": "Employee", "key_fields": "probation_end_date, status", "platform_equivalent": "Workday: Probation tracking", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_011", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT COUNT(*) AS value FROM reporting.employee WHERE status = ''Active'' AND probation_end_date >= CURRENT_DATE"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-012', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-012", "kpi_name": "Probation Overdue", "kpi_module": "HR", "sub_area": "Workforce", "is_active": true, "definition": "Employees whose probation end date passed without a completed probation job change", "formula": "COUNT(Employee probation_end_date < CURRENT_DATE AND no JobChange change_reason=''Probation completed'')", "unit": "Persons", "direction": "Down", "target": "0", "frequency": "Monthly", "owner_role": "HRBP", "source_doctypes": "Employee, JobChange", "key_fields": "probation_end_date, change_reason", "platform_equivalent": "SAP SF Onboarding/Probation", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_012", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT COUNT(*) AS value FROM reporting.employee e WHERE e.status = ''Active'' AND e.probation_end_date < CURRENT_DATE AND NOT EXISTS (SELECT 1 FROM reporting.job_change j WHERE j.employee = e.name AND j.docstatus = 1 AND j.change_reason = ''Probation completed'') AND e.probation_end_date >= CURRENT_DATE - 365"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-013', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-013", "kpi_name": "Employees Approaching Retirement", "kpi_module": "HR", "sub_area": "Workforce", "is_active": true, "definition": "Active employees aged >= (retirement_age − 1)", "formula": "COUNT(Employee age >= HRSettings.retirement_age − 1)", "unit": "Persons", "direction": "Range", "target": "Successor identified for each person", "frequency": "Quarterly", "owner_role": "HR Manager", "source_doctypes": "Employee, HRSettings", "key_fields": "date_of_birth, retirement_age", "platform_equivalent": "Workday Succession; SAP SF Succession", "implementation": "Not available", "implementation_note": "Source fields are restricted in reporting schema (permLevel 1 or attachment), so it cannot be computed by a widget."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-014', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-014", "kpi_name": "Employee Data Completeness", "kpi_module": "HR", "sub_area": "Workforce", "is_active": true, "definition": "Percentage of active employees with national ID, tax ID, social security, and bank account filled", "formula": "COUNT(Employee nik,npwp,bpjs_health_no,bpjs_employment_no filled AND bank_accounts >= 1) / COUNT(Active) x100", "unit": "%", "direction": "Up", "target": "100%", "frequency": "Monthly", "owner_role": "HR Administrator", "source_doctypes": "Employee", "key_fields": "nik, npwp, bpjs_health_no, bpjs_employment_no, bank_accounts", "platform_equivalent": "Workday: Data Audit; SAP SF Data Quality", "implementation": "Not available", "implementation_note": "Source fields are restricted in reporting schema (permLevel 1 or attachment), so it cannot be computed by a widget."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-015', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-015", "kpi_name": "Expired Identity Documents", "kpi_module": "HR", "sub_area": "Workforce", "is_active": true, "definition": "Employee identity documents expired or expiring within 30 days", "formula": "COUNT(EmployeeIdentityDocument expiry_date <= CURRENT_DATE + 30)", "unit": "Documents", "direction": "Down", "target": "0 expired", "frequency": "Monthly", "owner_role": "HR Administrator", "source_doctypes": "EmployeeIdentityDocument", "key_fields": "expiry_date, document_type", "platform_equivalent": "SAP SF Document Management; Workday Worker Documents", "implementation": "Not available", "implementation_note": "Source fields are restricted in reporting schema (permLevel 1 or attachment), so it cannot be computed by a widget."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-016', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-016", "kpi_name": "Emergency Contact Completeness", "kpi_module": "HR", "sub_area": "Workforce", "is_active": true, "definition": "Percentage of active employees with at least 1 emergency contact", "formula": "COUNT(Employee with emergency_contacts >= 1) / COUNT(Active) x100", "unit": "%", "direction": "Up", "target": "100%", "frequency": "Quarterly", "owner_role": "HR Administrator", "source_doctypes": "Employee, EmployeeEmergencyContact", "key_fields": "emergency_contacts", "platform_equivalent": "Workday / SAP SF", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_016", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE EXISTS (SELECT 1 FROM reporting.employee_emergency_contacts c WHERE c.parent = e.name))) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.employee e WHERE e.status = ''Active''"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-017', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-017", "kpi_name": "Dependents per Employee", "kpi_module": "HR", "sub_area": "Workforce", "is_active": true, "definition": "Average number of dependents per employee (for insurance and benefit planning)", "formula": "COUNT(EmployeeDependent) / COUNT(Active employees)", "unit": "Persons", "direction": "Range", "target": "—", "frequency": "Annual", "owner_role": "Benefits Administrator", "source_doctypes": "EmployeeDependent", "key_fields": "relationship, is_bpjs_dependent", "platform_equivalent": "Workday Benefits; SAP SF Benefits", "implementation": "Not available", "implementation_note": "Source fields are restricted in reporting schema (permLevel 1 or attachment), so it cannot be computed by a widget."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-018', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-018", "kpi_name": "Education Profile", "kpi_module": "HR", "sub_area": "Workforce", "is_active": true, "definition": "Percentage of employees with Bachelor''s degree or higher", "formula": "COUNT(Employee with EmployeeEducation level IN (''Bachelor'',''Master'',''Doctorate'')) / COUNT(Active) x100", "unit": "%", "direction": "Range", "target": "Per job profile", "frequency": "Annual", "owner_role": "HR Manager", "source_doctypes": "EmployeeEducation", "key_fields": "level", "platform_equivalent": "Workday Talent Profile", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_018", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE EXISTS (SELECT 1 FROM reporting.employee_education x WHERE x.parent = e.name AND x.level IN (''Bachelor'',''Master'',''Doctorate'')))) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.employee e WHERE e.status = ''Active''"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-019', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-019", "kpi_name": "Revenue per Employee", "kpi_module": "HR", "sub_area": "Workforce", "is_active": true, "definition": "Revenue per active employee", "formula": "SUM(SalesInvoice.base_grand_total − vat_amount, docstatus=1) / AVG headcount", "unit": "IDR/person", "direction": "Up", "target": "Increase YoY", "frequency": "Quarterly", "owner_role": "CFO / CHRO", "source_doctypes": "SalesInvoice, Employee", "key_fields": "base_grand_total, status", "platform_equivalent": "Workday; NetSuite; SAP; M365 Power BI", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_019", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(COALESCE((SELECT SUM(si.total * si.exchange_rate) FROM reporting.sales_invoice si WHERE si.docstatus = 1 AND si.posting_date BETWEEN @Start AND @End), 0) / NULLIF((((SELECT COUNT(*) FROM reporting.employee e WHERE e.hire_date <= @Start::date AND (e.separation_date IS NULL OR e.separation_date > @Start::date)) + (SELECT COUNT(*) FROM reporting.employee e WHERE e.hire_date <= @End::date AND (e.separation_date IS NULL OR e.separation_date > @End::date))) / 2.0), 0), 0) AS value"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-020', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-020", "kpi_name": "Labour Cost to Revenue", "kpi_module": "HR", "sub_area": "Workforce", "is_active": true, "definition": "Labor costs compared to total revenue", "formula": "SUM(Payslip.gross_earnings + employer_contributions) / Revenue x100", "unit": "%", "direction": "Down", "target": "Industry standard", "frequency": "Monthly", "owner_role": "CFO / CHRO", "source_doctypes": "Payslip, SalesInvoice", "key_fields": "gross_earnings, employer_contributions", "platform_equivalent": "Workday / SAP / NetSuite", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_020", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (SELECT SUM(r.total_gross + r.total_employer_contributions) FROM reporting.payroll_run r WHERE r.docstatus = 1 AND r.posting_date BETWEEN @Start AND @End) / NULLIF((SELECT SUM(si.total * si.exchange_rate) FROM reporting.sales_invoice si WHERE si.docstatus = 1 AND si.posting_date BETWEEN @Start AND @End), 0), 2) AS value"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-021', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-021", "kpi_name": "Organization Units Without Manager", "kpi_module": "HR", "sub_area": "Organization", "is_active": true, "definition": "Active organization units with an empty manager field", "formula": "COUNT(OrganizationUnit is_active=1 AND manager IS NULL)", "unit": "Units", "direction": "Down", "target": "0", "frequency": "Monthly", "owner_role": "HR Organization Design", "source_doctypes": "OrganizationUnit", "key_fields": "manager, is_active", "platform_equivalent": "Workday Supervisory Org; SAP SF Org Chart", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_021", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT COUNT(*) AS value FROM reporting.organization_unit WHERE is_active AND manager IS NULL"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-022', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-022", "kpi_name": "Organization Units Without Cost Center", "kpi_module": "HR", "sub_area": "Organization", "is_active": true, "definition": "Active organization units not yet mapped to a cost center", "formula": "COUNT(OrganizationUnit is_active=1 AND cost_center IS NULL)", "unit": "Units", "direction": "Down", "target": "0", "frequency": "Monthly", "owner_role": "HR + Controller", "source_doctypes": "OrganizationUnit", "key_fields": "cost_center", "platform_equivalent": "Workday Cost Center Hierarchy", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_022", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT COUNT(*) AS value FROM reporting.organization_unit WHERE is_active AND cost_center IS NULL"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-023', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-023", "kpi_name": "Organization Structure Depth", "kpi_module": "HR", "sub_area": "Organization", "is_active": true, "definition": "Number of hierarchy levels from top to bottom organization unit", "formula": "MAX depth(parent_org_unit)", "unit": "Levels", "direction": "Down", "target": "≤ 6 levels", "frequency": "Annual", "owner_role": "HR Organization Design", "source_doctypes": "OrganizationUnit", "key_fields": "parent_org_unit", "platform_equivalent": "Workday Org Studio", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_023", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "WITH RECURSIVE t AS (SELECT name, 1 AS lvl FROM reporting.organization_unit WHERE is_active AND parent_org_unit IS NULL UNION ALL SELECT o.name, t.lvl + 1 FROM reporting.organization_unit o JOIN t ON o.parent_org_unit = t.name WHERE o.is_active AND t.lvl < 50) SELECT MAX(lvl) AS value FROM t"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-024', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-024", "kpi_name": "Positions With Dotted Line", "kpi_module": "HR", "sub_area": "Organization", "is_active": true, "definition": "Percentage of positions with matrix reporting lines", "formula": "COUNT(Position with dotted_lines >= 1) / COUNT(Position) x100", "unit": "%", "direction": "Range", "target": "—", "frequency": "Annual", "owner_role": "HR Organization Design", "source_doctypes": "Position, PositionDottedLine", "key_fields": "dotted_lines", "platform_equivalent": "Workday Matrix Org", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_024", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE EXISTS (SELECT 1 FROM reporting.position_dotted_lines d WHERE d.parent = p.name))) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.position p WHERE p.status <> ''Closed''"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-025', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-025", "kpi_name": "Employees Outside Grade Pay Range", "kpi_module": "HR", "sub_area": "Organization", "is_active": true, "definition": "Employees with basic salary below minimum or above maximum of GradePayRange", "formula": "COUNT(SalaryAssignment base < min_salary OR > max_salary)", "unit": "Persons", "direction": "Down", "target": "0", "frequency": "Quarterly", "owner_role": "Compensation & Benefits", "source_doctypes": "SalaryAssignment, Grade, GradePayRange", "key_fields": "total_earnings, min_salary, max_salary", "platform_equivalent": "Workday Compensation; SAP SF Compensation", "implementation": "Not available", "implementation_note": "Source fields are restricted in reporting schema (permLevel 1 or attachment), so it cannot be computed by a widget."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-026', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-026", "kpi_name": "Compa-Ratio", "kpi_module": "HR", "sub_area": "Organization", "is_active": true, "definition": "Employee salary compared to grade midpoint", "formula": "AVG(basic_salary / GradePayRange.mid_salary)", "unit": "Ratio", "direction": "Range", "target": "0,90–1,10", "frequency": "Annual", "owner_role": "Compensation & Benefits", "source_doctypes": "SalaryAssignment, GradePayRange", "key_fields": "mid_salary", "platform_equivalent": "Workday Compa-Ratio; SAP SF Compensation", "implementation": "Not available", "implementation_note": "Source fields are restricted in reporting schema (permLevel 1 or attachment), so it cannot be computed by a widget."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-027', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-027", "kpi_name": "Job Profiles Without Default Grade", "kpi_module": "HR", "sub_area": "Organization", "is_active": true, "definition": "Active job profiles without a default grade configured", "formula": "COUNT(JobProfile is_active=1 AND default_grade IS NULL)", "unit": "Profiles", "direction": "Down", "target": "0", "frequency": "Quarterly", "owner_role": "Compensation & Benefits", "source_doctypes": "JobProfile", "key_fields": "default_grade", "platform_equivalent": "Workday Job Architecture", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_027", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT COUNT(*) AS value FROM reporting.job_profile WHERE is_active AND default_grade IS NULL"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-028', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-028", "kpi_name": "Promotion Rate", "kpi_module": "HR", "sub_area": "Job Changes & Career", "is_active": true, "definition": "Percentage of employees promoted within the period", "formula": "COUNT(JobChange change_reason=''Promotion'', docstatus=1) / AVG headcount x100", "unit": "%", "direction": "Range", "target": "5–10% per year", "frequency": "Annual", "owner_role": "HR Manager", "source_doctypes": "JobChange", "key_fields": "change_reason, effective_date", "platform_equivalent": "Workday Promotion Rate; SAP SF", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_028", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (SELECT COUNT(*) FROM reporting.job_change WHERE docstatus = 1 AND change_reason = ''Promotion'' AND effective_date BETWEEN @Start AND @End) / NULLIF((((SELECT COUNT(*) FROM reporting.employee e WHERE e.hire_date <= @Start::date AND (e.separation_date IS NULL OR e.separation_date > @Start::date)) + (SELECT COUNT(*) FROM reporting.employee e WHERE e.hire_date <= @End::date AND (e.separation_date IS NULL OR e.separation_date > @End::date))) / 2.0), 0), 2) AS value"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-029', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-029", "kpi_name": "Internal Mobility Rate", "kpi_module": "HR", "sub_area": "Job Changes & Career", "is_active": true, "definition": "Transfers and rotations compared to headcount", "formula": "COUNT(JobChange change_reason IN (''Transfer'',''Rotation'')) / AVG headcount x100", "unit": "%", "direction": "Up", "target": "≥ 8% per year", "frequency": "Annual", "owner_role": "HR Manager", "source_doctypes": "JobChange", "key_fields": "change_reason", "platform_equivalent": "Workday Internal Mobility", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_029", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (SELECT COUNT(*) FROM reporting.job_change WHERE docstatus = 1 AND change_reason IN (''Transfer'',''Rotation'') AND effective_date BETWEEN @Start AND @End) / NULLIF((((SELECT COUNT(*) FROM reporting.employee e WHERE e.hire_date <= @Start::date AND (e.separation_date IS NULL OR e.separation_date > @Start::date)) + (SELECT COUNT(*) FROM reporting.employee e WHERE e.hire_date <= @End::date AND (e.separation_date IS NULL OR e.separation_date > @End::date))) / 2.0), 0), 2) AS value"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-030', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-030", "kpi_name": "Demotion Count", "kpi_module": "HR", "sub_area": "Job Changes & Career", "is_active": true, "definition": "Number of demotions", "formula": "COUNT(JobChange change_reason=''Demotion'')", "unit": "Cases", "direction": "Down", "target": "Minimal", "frequency": "Quarterly", "owner_role": "HR Manager", "source_doctypes": "JobChange", "key_fields": "change_reason", "platform_equivalent": "Workday / SAP SF", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_030", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT COUNT(*) AS value FROM reporting.job_change WHERE docstatus = 1 AND change_reason = ''Demotion'' AND effective_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-031', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-031", "kpi_name": "Employment Status Conversion", "kpi_module": "HR", "sub_area": "Job Changes & Career", "is_active": true, "definition": "Contract employees converted to permanent status", "formula": "COUNT(JobChange change_reason=''Employment status change'' AND new_employment_type=''Permanent (PKWTT)'')", "unit": "Persons", "direction": "Range", "target": "—", "frequency": "Quarterly", "owner_role": "HR Manager", "source_doctypes": "JobChange", "key_fields": "change_reason, new_employment_type", "platform_equivalent": "SAP SF Employee Central", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_031", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT COUNT(*) AS value FROM reporting.job_change WHERE docstatus = 1 AND change_reason = ''Employment status change'' AND new_employment_type = ''Permanent (PKWTT)'' AND effective_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-032', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-032", "kpi_name": "Average Time Since Last Job Change", "kpi_module": "HR", "sub_area": "Job Changes & Career", "is_active": true, "definition": "Average months since last job change date", "formula": "AVG(DATEDIFF(month, last_job_change_date, CURRENT_DATE))", "unit": "Months", "direction": "Range", "target": "≤ 36 months", "frequency": "Annual", "owner_role": "HRBP", "source_doctypes": "Employee", "key_fields": "last_job_change_date", "platform_equivalent": "Workday Time in Position", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_032", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT ROUND(AVG((CURRENT_DATE - COALESCE(last_job_change_date, hire_date)) / 30.44), 1) AS value FROM reporting.employee WHERE status = ''Active''"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-033', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-033", "kpi_name": "Employees Affected by Reorganization", "kpi_module": "HR", "sub_area": "Job Changes & Career", "is_active": true, "definition": "Number of employees affected by reorganization", "formula": "COUNT(JobChange change_reason=''Reorganization'')", "unit": "Persons", "direction": "Range", "target": "—", "frequency": "Quarterly", "owner_role": "HR Organization Design", "source_doctypes": "JobChange", "key_fields": "change_reason", "platform_equivalent": "Workday Reorg", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_033", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT COUNT(*) AS value FROM reporting.job_change WHERE docstatus = 1 AND change_reason = ''Reorganization'' AND effective_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-034', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-034", "kpi_name": "Expiring Contracts", "kpi_module": "HR", "sub_area": "Employment Contracts", "is_active": true, "definition": "Active contracts ending within X days (X = HRSettings.contract_expiry_reminder_days)", "formula": "COUNT(EmploymentContract status=''Active'' AND end_date <= CURRENT_DATE + X)", "unit": "Contracts", "direction": "Range", "target": "All followed up", "frequency": "Weekly", "owner_role": "HR Administrator", "source_doctypes": "EmploymentContract, HRSettings", "key_fields": "end_date, status, contract_expiry_reminder_days", "platform_equivalent": "SAP SF Contract Mgmt; Workday Contract", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_034", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT COUNT(*) AS value FROM reporting.employment_contract c WHERE c.docstatus = 1 AND c.status = ''Active'' AND c.end_date BETWEEN CURRENT_DATE AND CURRENT_DATE + COALESCE((SELECT MAX(contract_expiry_reminder_days) FROM reporting.hrsettings), 30)::int"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-035', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-035", "kpi_name": "Expired Contracts Without Follow-up", "kpi_module": "HR", "sub_area": "Employment Contracts", "is_active": true, "definition": "Expired contracts where the employee remains active without a successor contract", "formula": "COUNT(EmploymentContract status=''Expired'' AND Employee.status=''Active'' AND no renewal_of)", "unit": "Contracts", "direction": "Down", "target": "0", "frequency": "Weekly", "owner_role": "HR Administrator", "source_doctypes": "EmploymentContract, Employee", "key_fields": "status, renewal_of", "platform_equivalent": "SAP SF / Workday", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_035", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT COUNT(*) AS value FROM reporting.employment_contract c JOIN reporting.employee e ON e.name = c.employee WHERE c.docstatus = 1 AND (c.status = ''Expired'' OR (c.status = ''Active'' AND c.end_date < CURRENT_DATE)) AND e.status = ''Active'' AND NOT EXISTS (SELECT 1 FROM reporting.employment_contract n WHERE n.employee = c.employee AND n.docstatus = 1 AND n.status = ''Active'' AND COALESCE(n.end_date, DATE ''9999-12-31'') >= CURRENT_DATE)"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-036', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-036", "kpi_name": "Contract Renewal Rate", "kpi_module": "HR", "sub_area": "Employment Contracts", "is_active": true, "definition": "Contracts renewed compared to contracts ending", "formula": "COUNT(status=''Renewed'') / COUNT(status IN (''Renewed'',''Expired'',''Terminated'')) x100", "unit": "%", "direction": "Range", "target": "—", "frequency": "Quarterly", "owner_role": "HR Manager", "source_doctypes": "EmploymentContract", "key_fields": "status", "platform_equivalent": "Workday", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_036", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE status = ''Renewed'')) / NULLIF(COUNT(*) FILTER (WHERE status IN (''Renewed'',''Expired'',''Terminated'')), 0), 2) AS value FROM reporting.employment_contract WHERE docstatus = 1 AND end_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-037', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-037", "kpi_name": "Contracts Without Document Attachment", "kpi_module": "HR", "sub_area": "Employment Contracts", "is_active": true, "definition": "Active employment contracts missing an attached contract document", "formula": "COUNT(EmploymentContract status=''Active'' AND document IS NULL)", "unit": "Contracts", "direction": "Down", "target": "0", "frequency": "Monthly", "owner_role": "HR Administrator", "source_doctypes": "EmploymentContract", "key_fields": "document", "platform_equivalent": "SAP SF Document", "implementation": "Not available", "implementation_note": "Source fields are restricted in reporting schema (permLevel 1 or attachment), so it cannot be computed by a widget."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-038', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-038", "kpi_name": "Open Requisitions", "kpi_module": "HR", "sub_area": "Recruitment", "is_active": true, "definition": "Number of job requisitions with Open status", "formula": "COUNT(JobRequisition requisition_status=''Open'')", "unit": "Requisitions", "direction": "Range", "target": "—", "frequency": "Weekly", "owner_role": "Recruitment Lead", "source_doctypes": "JobRequisition", "key_fields": "requisition_status", "platform_equivalent": "Workday Recruiting; SAP SF Recruiting", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_038", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT COUNT(*) AS value FROM reporting.job_requisition WHERE docstatus = 1 AND requisition_status = ''Open''"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-039', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-039", "kpi_name": "Open Openings", "kpi_module": "HR", "sub_area": "Recruitment", "is_active": true, "definition": "Total unfilled job openings", "formula": "SUM(openings − hired_count) WHERE requisition_status=''Open''", "unit": "Persons", "direction": "Down", "target": "—", "frequency": "Weekly", "owner_role": "Recruitment Lead", "source_doctypes": "JobRequisition", "key_fields": "openings, hired_count", "platform_equivalent": "Workday Recruiting", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_039", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT COALESCE(SUM(GREATEST(openings - COALESCE(hired_count, 0), 0)), 0) AS value FROM reporting.job_requisition WHERE docstatus = 1 AND requisition_status = ''Open''"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-040', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-040", "kpi_name": "Requisition Fill Rate", "kpi_module": "HR", "sub_area": "Recruitment", "is_active": true, "definition": "Filled openings compared to total openings", "formula": "SUM(hired_count) / SUM(openings) x100", "unit": "%", "direction": "Up", "target": "≥ 90%", "frequency": "Quarterly", "owner_role": "Recruitment Lead", "source_doctypes": "JobRequisition", "key_fields": "openings, hired_count", "platform_equivalent": "Workday / SAP SF", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_040", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (SUM(COALESCE(hired_count, 0))) / NULLIF(SUM(openings), 0), 2) AS value FROM reporting.job_requisition WHERE docstatus = 1 AND requisition_status <> ''Cancelled'' AND created::date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-041', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-041", "kpi_name": "Time to Fill", "kpi_module": "HR", "sub_area": "Recruitment", "is_active": true, "definition": "Days from job requisition creation to Filled status", "formula": "AVG(Filled date − creation) per JobRequisition", "unit": "Days", "direction": "Down", "target": "≤ 45 days", "frequency": "Monthly", "owner_role": "Recruitment Lead", "source_doctypes": "JobRequisition", "key_fields": "requisition_status, creation, modified", "platform_equivalent": "Workday Time to Fill; SAP SF", "implementation": "Not available", "implementation_note": "Requires workflow transition timestamps per document (version/audit trail), which are not yet exposed to the reporting schema."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-042', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-042", "kpi_name": "Time to Hire", "kpi_module": "HR", "sub_area": "Recruitment", "is_active": true, "definition": "Days from applicant creation to Hired status", "formula": "AVG(Hired date − JobApplicant.creation)", "unit": "Days", "direction": "Down", "target": "≤ 30 days", "frequency": "Monthly", "owner_role": "Recruitment Lead", "source_doctypes": "JobApplicant", "key_fields": "status, creation", "platform_equivalent": "Workday / SAP SF", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_042", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(AVG(e.hire_date - a.created::date), 1) AS value FROM reporting.job_applicant a JOIN reporting.employee e ON e.name = a.employee WHERE a.status = ''Hired'' AND e.hire_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-043', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-043", "kpi_name": "Time to Start", "kpi_module": "HR", "sub_area": "Recruitment", "is_active": true, "definition": "Days from offer date to proposed start date", "formula": "AVG(proposed_start_date − offer_date)", "unit": "Days", "direction": "Down", "target": "≤ 30 days", "frequency": "Monthly", "owner_role": "Recruitment Lead", "source_doctypes": "JobOffer", "key_fields": "offer_date, proposed_start_date", "platform_equivalent": "Workday", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_043", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(AVG(proposed_start_date - offer_date), 1) AS value FROM reporting.job_offer WHERE workflow_state = ''Accepted'' AND offer_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-044', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-044", "kpi_name": "Applicants per Opening", "kpi_module": "HR", "sub_area": "Recruitment", "is_active": true, "definition": "Average number of applicants per opening", "formula": "SUM(applicant_count) / SUM(openings)", "unit": "Applicants", "direction": "Up", "target": "≥ 20", "frequency": "Monthly", "owner_role": "Recruitment Lead", "source_doctypes": "JobRequisition", "key_fields": "applicant_count, openings", "platform_equivalent": "Workday / SAP SF", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_044", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(SUM(COALESCE(applicant_count, 0))::numeric / NULLIF(SUM(openings), 0), 1) AS value FROM reporting.job_requisition WHERE docstatus = 1 AND requisition_status <> ''Cancelled'' AND created::date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-045', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-045", "kpi_name": "Screening Pass Rate", "kpi_module": "HR", "sub_area": "Recruitment", "is_active": true, "definition": "Applicants advancing to interview or later stages", "formula": "COUNT(JobApplicant status IN (''Interview'',''Offer'',''Hired'')) / COUNT(JobApplicant) x100", "unit": "%", "direction": "Range", "target": "20–30%", "frequency": "Monthly", "owner_role": "Recruitment Lead", "source_doctypes": "JobApplicant", "key_fields": "status", "platform_equivalent": "Workday Funnel", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_045", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE status IN (''Interview'',''Offer'',''Hired''))) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.job_applicant WHERE created::date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-046', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-046", "kpi_name": "Interview Pass Rate", "kpi_module": "HR", "sub_area": "Recruitment", "is_active": true, "definition": "Interviews resulting in Pass", "formula": "COUNT(Interview result=''Pass'') / COUNT(Interview result IN (''Pass'',''Fail'')) x100", "unit": "%", "direction": "Range", "target": "30–50%", "frequency": "Monthly", "owner_role": "Recruitment Lead", "source_doctypes": "Interview", "key_fields": "result", "platform_equivalent": "SAP SF Interview Central", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_046", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE result = ''Pass'')) / NULLIF(COUNT(*) FILTER (WHERE result IN (''Pass'',''Fail'')), 0), 2) AS value FROM reporting.interview WHERE scheduled_at::date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-047', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-047", "kpi_name": "Average Interview Rating", "kpi_module": "HR", "sub_area": "Recruitment", "is_active": true, "definition": "Average interviewer evaluation rating", "formula": "AVG(CAST(rating AS INT))", "unit": "Score 1–5", "direction": "Up", "target": "≥ 3,5", "frequency": "Monthly", "owner_role": "Recruitment Lead", "source_doctypes": "Interview", "key_fields": "rating", "platform_equivalent": "SAP SF Interview Central", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_047", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(AVG(rating::numeric), 2) AS value FROM reporting.interview WHERE rating IS NOT NULL AND scheduled_at::date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-048', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-048", "kpi_name": "Interview per Hire", "kpi_module": "HR", "sub_area": "Recruitment", "is_active": true, "definition": "Number of interviews conducted per hired employee", "formula": "COUNT(Interview) / COUNT(JobApplicant status=''Hired'')", "unit": "Ratio", "direction": "Down", "target": "≤ 6", "frequency": "Quarterly", "owner_role": "Recruitment Lead", "source_doctypes": "Interview, JobApplicant", "key_fields": "result, status", "platform_equivalent": "Workday", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_048", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND((SELECT COUNT(*) FROM reporting.interview WHERE scheduled_at::date BETWEEN @Start AND @End)::numeric / NULLIF((SELECT COUNT(*) FROM reporting.job_applicant a JOIN reporting.employee e ON e.name = a.employee WHERE a.status = ''Hired'' AND e.hire_date BETWEEN @Start AND @End), 0), 1) AS value"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-049', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-049", "kpi_name": "Interviews Pending Feedback", "kpi_module": "HR", "sub_area": "Recruitment", "is_active": true, "definition": "Completed interviews past schedule where result is still Pending", "formula": "COUNT(Interview result=''Pending'' AND scheduled_at < now − 2 days)", "unit": "Interviews", "direction": "Down", "target": "0", "frequency": "Weekly", "owner_role": "Hiring Manager", "source_doctypes": "Interview", "key_fields": "result, scheduled_at", "platform_equivalent": "SAP SF Interview Central", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_049", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT COUNT(*) AS value FROM reporting.interview WHERE result = ''Pending'' AND scheduled_at < now() - interval ''2 days''"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-050', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-050", "kpi_name": "Offer Acceptance Rate", "kpi_module": "HR", "sub_area": "Recruitment", "is_active": true, "definition": "Accepted offers compared to total offers extended", "formula": "COUNT(JobOffer state=''Accepted'') / COUNT(JobOffer state IN (''Accepted'',''Declined'')) x100", "unit": "%", "direction": "Up", "target": "≥ 85%", "frequency": "Monthly", "owner_role": "Recruitment Lead", "source_doctypes": "JobOffer", "key_fields": "workflow_state", "platform_equivalent": "Workday Offer Acceptance; SAP SF", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_050", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE workflow_state = ''Accepted'')) / NULLIF(COUNT(*) FILTER (WHERE workflow_state IN (''Accepted'',''Declined'')), 0), 2) AS value FROM reporting.job_offer WHERE offer_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-051', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-051", "kpi_name": "Offer Expired", "kpi_module": "HR", "sub_area": "Recruitment", "is_active": true, "definition": "Offers past expiration date without candidate decision", "formula": "COUNT(JobOffer workflow_state=''Expired'' OR (workflow_state=''Sent'' AND valid_until < CURRENT_DATE))", "unit": "Offers", "direction": "Down", "target": "0", "frequency": "Weekly", "owner_role": "Recruitment Lead", "source_doctypes": "JobOffer", "key_fields": "valid_until, workflow_state", "platform_equivalent": "Workday", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_051", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT COUNT(*) AS value FROM reporting.job_offer WHERE workflow_state = ''Expired'' OR (workflow_state = ''Sent'' AND valid_until < CURRENT_DATE)"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-052', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-052", "kpi_name": "Offers Above Requisition Budget", "kpi_module": "HR", "sub_area": "Recruitment", "is_active": true, "definition": "Job offers with basic salary exceeding requisition budget maximum", "formula": "COUNT(JobOffer base_salary > salary_max)", "unit": "Offers", "direction": "Down", "target": "0 (or with approval)", "frequency": "Monthly", "owner_role": "Compensation & Benefits", "source_doctypes": "JobOffer, JobRequisition", "key_fields": "base_salary, salary_max", "platform_equivalent": "Workday Compensation Guidelines", "implementation": "Not available", "implementation_note": "Source fields are restricted in reporting schema (permLevel 1 or attachment), so it cannot be computed by a widget."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-053', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-053", "kpi_name": "Source of Hire Mix", "kpi_module": "HR", "sub_area": "Recruitment", "is_active": true, "definition": "Percentage of hires by source channel (Referral, Job portal, Agency, etc.)", "formula": "COUNT(JobApplicant status=''Hired'' per source) / COUNT(Hired) x100", "unit": "%", "direction": "Range", "target": "Referral ≥ 25%", "frequency": "Quarterly", "owner_role": "Recruitment Lead", "source_doctypes": "JobApplicant", "key_fields": "source, status", "platform_equivalent": "Workday Source Effectiveness", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_053", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT COALESCE(a.source, ''(blank)'') AS label, COUNT(*) AS value FROM reporting.job_applicant a LEFT JOIN reporting.employee e ON e.name = a.employee WHERE a.status = ''Hired'' AND COALESCE(e.hire_date, a.modified::date) BETWEEN @Start AND @End GROUP BY 1 ORDER BY 2 DESC"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-054', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-054", "kpi_name": "Referral Conversion", "kpi_module": "HR", "sub_area": "Recruitment", "is_active": true, "definition": "Referral applicants successfully hired", "formula": "COUNT(source=''Referral'' AND status=''Hired'') / COUNT(source=''Referral'') x100", "unit": "%", "direction": "Up", "target": "≥ 15%", "frequency": "Quarterly", "owner_role": "Recruitment Lead", "source_doctypes": "JobApplicant", "key_fields": "source, status", "platform_equivalent": "Workday", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_054", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE status = ''Hired'')) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.job_applicant WHERE source = ''Referral'' AND created::date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-055', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-055", "kpi_name": "Candidate Withdrawal Rate", "kpi_module": "HR", "sub_area": "Recruitment", "is_active": true, "definition": "Applicants withdrawing voluntarily from the hiring pipeline", "formula": "COUNT(status=''Withdrawn'') / COUNT(JobApplicant) x100", "unit": "%", "direction": "Down", "target": "≤ 10%", "frequency": "Monthly", "owner_role": "Recruitment Lead", "source_doctypes": "JobApplicant", "key_fields": "status", "platform_equivalent": "Workday", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_055", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE status = ''Withdrawn'')) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.job_applicant WHERE created::date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-056', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-056", "kpi_name": "Replacement vs New Headcount", "kpi_module": "HR", "sub_area": "Recruitment", "is_active": true, "definition": "Proportion of replacement requisitions vs new headcount", "formula": "COUNT(reason=''Replacement'') / COUNT(JobRequisition) x100", "unit": "%", "direction": "Range", "target": "—", "frequency": "Quarterly", "owner_role": "HR Manager", "source_doctypes": "JobRequisition", "key_fields": "reason", "platform_equivalent": "Workday", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_056", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE reason = ''Replacement'')) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.job_requisition WHERE docstatus = 1 AND created::date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-057', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-057", "kpi_name": "Requisition Overdue", "kpi_module": "HR", "sub_area": "Recruitment", "is_active": true, "definition": "Open requisitions where target start date has passed", "formula": "COUNT(requisition_status=''Open'' AND target_start_date < CURRENT_DATE)", "unit": "Requisitions", "direction": "Down", "target": "0", "frequency": "Weekly", "owner_role": "Recruitment Lead", "source_doctypes": "JobRequisition", "key_fields": "target_start_date", "platform_equivalent": "Workday", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_057", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT COUNT(*) AS value FROM reporting.job_requisition WHERE docstatus = 1 AND requisition_status = ''Open'' AND target_start_date < CURRENT_DATE"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-058', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-058", "kpi_name": "Salary Expectations vs Range", "kpi_module": "HR", "sub_area": "Recruitment", "is_active": true, "definition": "Average expected salary compared to budget midpoint", "formula": "AVG(expected_salary / ((salary_min+salary_max)/2))", "unit": "Ratio", "direction": "Range", "target": "≤ 1,05", "frequency": "Quarterly", "owner_role": "Compensation & Benefits", "source_doctypes": "JobApplicant, JobRequisition", "key_fields": "expected_salary, salary_min, salary_max", "platform_equivalent": "Workday", "implementation": "Not available", "implementation_note": "Source fields are restricted in reporting schema (permLevel 1 or attachment), so it cannot be computed by a widget."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-059', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-059", "kpi_name": "Hiring Quality (Probation Pass Rate)", "kpi_module": "HR", "sub_area": "Recruitment", "is_active": true, "definition": "Percentage of new hires passing probation", "formula": "COUNT(Hired employees with JobChange ''Probation completed'') / COUNT(Hires) x100", "unit": "%", "direction": "Up", "target": "≥ 90%", "frequency": "Quarterly", "owner_role": "Recruitment Lead", "source_doctypes": "Employee, JobChange", "key_fields": "change_reason, hire_date", "platform_equivalent": "Workday Quality of Hire", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_059", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE EXISTS (SELECT 1 FROM reporting.job_change j WHERE j.employee = e.name AND j.docstatus = 1 AND j.change_reason = ''Probation completed''))) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.employee e WHERE e.hire_date BETWEEN @Start AND @End AND e.probation_end_date < CURRENT_DATE"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-060', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-060", "kpi_name": "Attendance Rate", "kpi_module": "HR", "sub_area": "Attendance", "is_active": true, "definition": "Days present (Present, WFH, Half day) compared to scheduled working days", "formula": "COUNT(Attendance status IN (''Present'',''Work from home'')) + 0.5×Half day / COUNT(Attendance) x100", "unit": "%", "direction": "Up", "target": "≥ 97%", "frequency": "Monthly", "owner_role": "HR Operations", "source_doctypes": "Attendance", "key_fields": "status", "platform_equivalent": "Workday Time Tracking; SAP SF Time", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_060", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE status IN (''Present'',''Work from home'')) + 0.5 * COUNT(*) FILTER (WHERE status = ''Half day'')) / NULLIF(COUNT(*) FILTER (WHERE status <> ''On leave''), 0), 2) AS value FROM reporting.attendance WHERE attendance_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-061', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-061", "kpi_name": "Absenteeism Rate", "kpi_module": "HR", "sub_area": "Attendance", "is_active": true, "definition": "Unplanned absence days compared to scheduled working days", "formula": "COUNT(status=''Absent'') / COUNT(Attendance) x100", "unit": "%", "direction": "Down", "target": "≤ 2%", "frequency": "Monthly", "owner_role": "HR Operations", "source_doctypes": "Attendance", "key_fields": "status", "platform_equivalent": "Workday / SAP SF", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_061", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE status = ''Absent'')) / NULLIF(COUNT(*) FILTER (WHERE status <> ''On leave''), 0), 2) AS value FROM reporting.attendance WHERE attendance_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-062', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-062", "kpi_name": "Tardiness Rate", "kpi_module": "HR", "sub_area": "Attendance", "is_active": true, "definition": "Percentage of present days with late arrival exceeding grace period", "formula": "COUNT(late_minutes > ShiftType.late_grace_minutes) / COUNT(Present) x100", "unit": "%", "direction": "Down", "target": "≤ 5%", "frequency": "Monthly", "owner_role": "HR Operations", "source_doctypes": "Attendance, ShiftType", "key_fields": "late_minutes, late_grace_minutes", "platform_equivalent": "SAP SF Time; Workday", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_062", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE a.late_minutes > COALESCE(s.late_grace_minutes, 0))) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.attendance a LEFT JOIN reporting.shift_type s ON s.name = a.shift_type WHERE a.status IN (''Present'',''Work from home'',''Half day'') AND a.attendance_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-063', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-063", "kpi_name": "Average Late Minutes", "kpi_module": "HR", "sub_area": "Attendance", "is_active": true, "definition": "Average minutes late per tardiness occurrence", "formula": "AVG(late_minutes) WHERE late_minutes > 0", "unit": "Minutes", "direction": "Down", "target": "≤ 15", "frequency": "Monthly", "owner_role": "HR Operations", "source_doctypes": "Attendance", "key_fields": "late_minutes", "platform_equivalent": "SAP SF Time", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_063", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(AVG(late_minutes), 1) AS value FROM reporting.attendance WHERE late_minutes > 0 AND attendance_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-064', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-064", "kpi_name": "Average Daily Working Hours", "kpi_module": "HR", "sub_area": "Attendance", "is_active": true, "definition": "Average working hours per present attendance record", "formula": "AVG(working_hours) WHERE status=''Present''", "unit": "Hours", "direction": "Range", "target": "≈ ShiftType.working_hours_per_day", "frequency": "Monthly", "owner_role": "HR Operations", "source_doctypes": "Attendance", "key_fields": "working_hours", "platform_equivalent": "Workday Time", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_064", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(AVG(working_hours), 2) AS value FROM reporting.attendance WHERE status IN (''Present'',''Work from home'') AND working_hours > 0 AND attendance_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-065', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-065", "kpi_name": "WFH Ratio", "kpi_module": "HR", "sub_area": "Attendance", "is_active": true, "definition": "Work from home days compared to total present days", "formula": "COUNT(status=''Work from home'') / COUNT(Present) x100", "unit": "%", "direction": "Range", "target": "Per hybrid work policy", "frequency": "Monthly", "owner_role": "HR Operations", "source_doctypes": "Attendance", "key_fields": "status", "platform_equivalent": "M365 Viva Insights; Workday", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_065", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE status = ''Work from home'')) / NULLIF(COUNT(*) FILTER (WHERE status IN (''Present'',''Work from home'',''Half day'')), 0), 2) AS value FROM reporting.attendance WHERE attendance_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-066', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-066", "kpi_name": "Missing Check-out", "kpi_module": "HR", "sub_area": "Attendance", "is_active": true, "definition": "Attendance records with check-in but missing check-out", "formula": "COUNT(status=''Present'' AND check_out IS NULL)", "unit": "Occurrences", "direction": "Down", "target": "0", "frequency": "Weekly", "owner_role": "HR Operations", "source_doctypes": "Attendance", "key_fields": "check_in, check_out", "platform_equivalent": "SAP SF Time", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_066", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT COUNT(*) AS value FROM reporting.attendance WHERE status IN (''Present'',''Work from home'',''Half day'') AND check_in IS NOT NULL AND check_out IS NULL AND attendance_date BETWEEN @Start AND LEAST(@End, CURRENT_DATE - 1)"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-067', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-067", "kpi_name": "Geolocation Compliance", "kpi_module": "HR", "sub_area": "Attendance", "is_active": true, "definition": "Check-in logs containing valid geolocation coordinates", "formula": "COUNT(check_in_location filled) / COUNT(check_in) x100", "unit": "%", "direction": "Up", "target": "≥ 98%", "frequency": "Monthly", "owner_role": "HR Operations", "source_doctypes": "Attendance", "key_fields": "check_in_location", "platform_equivalent": "Workday Mobile Time", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_067", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE COALESCE(check_in_location, '''') <> '''')) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.attendance WHERE check_in IS NOT NULL AND attendance_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-068', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-068", "kpi_name": "Night Shift Employees", "kpi_module": "HR", "sub_area": "Attendance", "is_active": true, "definition": "Percentage of active employees assigned to night shifts", "formula": "COUNT(Employee shift_type.is_night_shift=1) / COUNT(Active) x100", "unit": "%", "direction": "Range", "target": "—", "frequency": "Quarterly", "owner_role": "HR Operations", "source_doctypes": "Employee, ShiftType", "key_fields": "shift_type, is_night_shift", "platform_equivalent": "SAP SF Time", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_068", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE s.is_night_shift)) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.employee e LEFT JOIN reporting.shift_type s ON s.name = e.shift_type WHERE e.status = ''Active''"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-069', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-069", "kpi_name": "Leave Utilization Rate", "kpi_module": "HR", "sub_area": "Leave", "is_active": true, "definition": "Approved leave days used compared to total leave allocation", "formula": "SUM(LeaveApplication.total_days approved) / SUM(LeaveAllocation.total_leaves) x100", "unit": "%", "direction": "Range", "target": "60–90%", "frequency": "Quarterly", "owner_role": "HR Operations", "source_doctypes": "LeaveApplication, LeaveAllocation", "key_fields": "total_days, total_leaves", "platform_equivalent": "Workday Absence; SAP SF Time Off", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_069", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (SELECT SUM(total_days) FROM reporting.leave_application WHERE workflow_state = ''Approved'' AND from_date BETWEEN @Start AND @End) / NULLIF((SELECT SUM(total_leaves) FROM reporting.leave_allocation WHERE docstatus = 1 AND from_date <= @End AND to_date >= @Start), 0), 2) AS value"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-070', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-070", "kpi_name": "Average Leave Balance", "kpi_module": "HR", "sub_area": "Leave", "is_active": true, "definition": "Average remaining leave balance per employee", "formula": "AVG(total_leaves − approved leave) per employee", "unit": "Days", "direction": "Range", "target": "≤ 6 days at year end", "frequency": "Monthly", "owner_role": "HR Operations", "source_doctypes": "LeaveAllocation, LeaveApplication", "key_fields": "total_leaves, total_days", "platform_equivalent": "Workday Absence Balance", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_070", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "WITH al AS (SELECT employee, leave_type, from_date, to_date, total_leaves FROM reporting.leave_allocation WHERE docstatus = 1 AND CURRENT_DATE BETWEEN from_date AND to_date), bal AS (SELECT al.employee, al.total_leaves - COALESCE((SELECT SUM(l.total_days) FROM reporting.leave_application l WHERE l.employee = al.employee AND l.leave_type = al.leave_type AND l.workflow_state = ''Approved'' AND l.from_date BETWEEN al.from_date AND al.to_date), 0) AS remaining FROM al) SELECT ROUND(AVG(remaining), 1) AS value FROM bal"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-071', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-071", "kpi_name": "Leave Liability (IDR)", "kpi_module": "HR", "sub_area": "Leave", "is_active": true, "definition": "Estimated monetary liability of untaken leave balances", "formula": "SUM(leave balance × (basic salary / working days))", "unit": "IDR", "direction": "Down", "target": "Decrease YoY", "frequency": "Quarterly", "owner_role": "Payroll + Controller", "source_doctypes": "LeaveAllocation, SalaryAssignment", "key_fields": "total_leaves, total_earnings", "platform_equivalent": "Workday; SAP SF; NetSuite accrual", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_071", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "WITH al AS (SELECT a.employee, a.leave_type, a.from_date, a.to_date, a.total_leaves FROM reporting.leave_allocation a JOIN reporting.leave_type t ON t.name = a.leave_type WHERE a.docstatus = 1 AND t.is_paid AND CURRENT_DATE BETWEEN a.from_date AND a.to_date), bal AS (SELECT al.employee, GREATEST(al.total_leaves - COALESCE((SELECT SUM(l.total_days) FROM reporting.leave_application l WHERE l.employee = al.employee AND l.leave_type = al.leave_type AND l.workflow_state = ''Approved'' AND l.from_date BETWEEN al.from_date AND al.to_date), 0), 0) AS remaining FROM al) SELECT ROUND(SUM(b.remaining * s.total_earnings / 21.0), 0) AS value FROM bal b JOIN reporting.salary_assignment s ON s.employee = b.employee AND s.is_active"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-072', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-072", "kpi_name": "Leave Approval Turnaround", "kpi_module": "HR", "sub_area": "Leave", "is_active": true, "definition": "Average hours from Pending Approval to decision", "formula": "AVG(LeaveApproval workflow transition hours)", "unit": "Hours", "direction": "Down", "target": "≤ 24 hours", "frequency": "Monthly", "owner_role": "HR Operations", "source_doctypes": "LeaveApplication (workflow LeaveApproval)", "key_fields": "workflow_state, modified", "platform_equivalent": "Workday Business Process; SAP SF Workflow", "implementation": "Not available", "implementation_note": "Requires workflow transition timestamps per document (version/audit trail), which are not yet exposed to the reporting schema."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-073', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-073", "kpi_name": "Leave Rejection Rate", "kpi_module": "HR", "sub_area": "Leave", "is_active": true, "definition": "Percentage of leave requests rejected", "formula": "COUNT(state=''Rejected'') / COUNT(Submitted) x100", "unit": "%", "direction": "Down", "target": "≤ 5%", "frequency": "Monthly", "owner_role": "HR Operations", "source_doctypes": "LeaveApplication", "key_fields": "workflow_state", "platform_equivalent": "Workday", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_073", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE workflow_state = ''Rejected'')) / NULLIF(COUNT(*) FILTER (WHERE workflow_state IN (''Approved'',''Rejected'')), 0), 2) AS value FROM reporting.leave_application WHERE from_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-074', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-074", "kpi_name": "Pending Leave Requests", "kpi_module": "HR", "sub_area": "Leave", "is_active": true, "definition": "Leave requests pending approval > 2 days", "formula": "COUNT(workflow_state=''Pending Approval'' AND modified < now − 2 days)", "unit": "Requests", "direction": "Down", "target": "0", "frequency": "Daily", "owner_role": "Leave Approver", "source_doctypes": "LeaveApplication", "key_fields": "workflow_state", "platform_equivalent": "Workday Inbox; M365 Teams Approvals", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_074", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT COUNT(*) AS value FROM reporting.leave_application WHERE workflow_state = ''Pending Approval'' AND modified < now() - interval ''2 days''"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-075', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-075", "kpi_name": "Sick Leave Rate", "kpi_module": "HR", "sub_area": "Leave", "is_active": true, "definition": "Sick leave days taken compared to working days", "formula": "SUM(total_days WHERE leave_type=''Sakit'') / working days x100", "unit": "%", "direction": "Down", "target": "≤ 2%", "frequency": "Monthly", "owner_role": "HR Operations", "source_doctypes": "LeaveApplication", "key_fields": "leave_type, total_days", "platform_equivalent": "Workday / SAP SF", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_075", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (SELECT COALESCE(SUM(total_days), 0) FROM reporting.leave_application WHERE workflow_state = ''Approved'' AND (leave_type ILIKE ''%sick%'' OR leave_type ILIKE ''%sakit%'') AND from_date BETWEEN @Start AND @End) / NULLIF((SELECT COUNT(*) FROM reporting.employee WHERE status = ''Active'') * (SELECT COUNT(*) FROM generate_series(@Start::date, @End::date, interval ''1 day'') g WHERE EXTRACT(ISODOW FROM g) < 6), 0), 2) AS value"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-076', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-076", "kpi_name": "Unpaid Leave Days", "kpi_module": "HR", "sub_area": "Leave", "is_active": true, "definition": "Total unpaid leave days taken", "formula": "SUM(Payslip.unpaid_leave_days)", "unit": "Days", "direction": "Down", "target": "—", "frequency": "Monthly", "owner_role": "Payroll", "source_doctypes": "Payslip, LeaveType", "key_fields": "unpaid_leave_days, is_paid", "platform_equivalent": "SAP SF / Workday", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_076", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT COALESCE(SUM(p.unpaid_leave_days), 0) AS value FROM reporting.payslip p JOIN reporting.payroll_run r ON r.name = p.payroll_run WHERE p.docstatus = 1 AND r.posting_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-077', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-077", "kpi_name": "Leave Attachment Compliance", "kpi_module": "HR", "sub_area": "Leave", "is_active": true, "definition": "Percentage of leaves requiring attachment that included proof", "formula": "COUNT(requires_attachment=1 AND attachment filled) / COUNT(requires_attachment=1) x100", "unit": "%", "direction": "Up", "target": "100%", "frequency": "Monthly", "owner_role": "HR Operations", "source_doctypes": "LeaveApplication", "key_fields": "requires_attachment, attachment", "platform_equivalent": "SAP SF Time Off", "implementation": "Not available", "implementation_note": "Source fields are restricted in reporting schema (permLevel 1 or attachment), so it cannot be computed by a widget."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-078', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-078", "kpi_name": "Carry-forward Ratio", "kpi_module": "HR", "sub_area": "Leave", "is_active": true, "definition": "Unused leave carried forward to next fiscal year", "formula": "SUM(carry_forwarded) / SUM(total_leaves) x100", "unit": "%", "direction": "Down", "target": "≤ 20%", "frequency": "Annual", "owner_role": "HR Operations", "source_doctypes": "LeaveAllocation", "key_fields": "carry_forwarded, total_leaves", "platform_equivalent": "Workday Carryover", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_078", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (SUM(COALESCE(carry_forwarded, 0))) / NULLIF(SUM(total_leaves), 0), 2) AS value FROM reporting.leave_allocation WHERE docstatus = 1 AND from_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-079', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-079", "kpi_name": "Bradford Factor (Average)", "kpi_module": "HR", "sub_area": "Leave", "is_active": true, "definition": "Absence disruption metric (frequency squared x total duration)", "formula": "AVG(S² × D) where S=absence instances, D=total days absent", "unit": "Score", "direction": "Down", "target": "≤ 50", "frequency": "Quarterly", "owner_role": "HRBP", "source_doctypes": "LeaveApplication", "key_fields": "employee, total_days, leave_type", "platform_equivalent": "Workday custom report", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_079", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(AVG(s * s * d), 1) AS value FROM (SELECT employee, COUNT(*) AS s, SUM(total_days) AS d FROM reporting.leave_application WHERE workflow_state = ''Approved'' AND (leave_type ILIKE ''%sick%'' OR leave_type ILIKE ''%sakit%'') AND from_date BETWEEN @Start AND @End GROUP BY employee) x"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-080', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-080", "kpi_name": "Total Overtime Hours", "kpi_module": "HR", "sub_area": "Overtime", "is_active": true, "definition": "Total approved overtime hours across organization", "formula": "SUM(OvertimeRequest.hours, state=''Approved'')", "unit": "Hours", "direction": "Down", "target": "Within budget", "frequency": "Monthly", "owner_role": "HR Operations", "source_doctypes": "OvertimeRequest", "key_fields": "hours, workflow_state", "platform_equivalent": "SAP SF Time; Workday Time", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_080", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT COALESCE(SUM(hours), 0) AS value FROM reporting.overtime_request WHERE workflow_state = ''Approved'' AND overtime_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-081', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-081", "kpi_name": "Overtime Hours per Employee", "kpi_module": "HR", "sub_area": "Overtime", "is_active": true, "definition": "Average overtime hours per active employee", "formula": "SUM(hours) / COUNT(DISTINCT active employees)", "unit": "Hours", "direction": "Down", "target": "≤ 14 hours/week (regulatory limit)", "frequency": "Monthly", "owner_role": "HR Operations", "source_doctypes": "OvertimeRequest", "key_fields": "hours, employee", "platform_equivalent": "SAP SF", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_081", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(SUM(hours) / NULLIF(COUNT(DISTINCT employee), 0), 1) AS value FROM reporting.overtime_request WHERE workflow_state = ''Approved'' AND overtime_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-082', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-082", "kpi_name": "Overtime Cost % Salary", "kpi_module": "HR", "sub_area": "Overtime", "is_active": true, "definition": "Overtime premium expense compared to total gross salary", "formula": "SUM(overtime component amount) / SUM(gross_earnings) x100", "unit": "%", "direction": "Down", "target": "≤ 5%", "frequency": "Monthly", "owner_role": "Payroll + Controller", "source_doctypes": "PayslipDetail, PayrollSettings", "key_fields": "salary_component, overtime_component", "platform_equivalent": "Workday; SAP", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_082", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (SELECT SUM(e.amount) FROM reporting.payslip_earnings e JOIN reporting.payslip p ON p.name = e.parent JOIN reporting.payroll_run r ON r.name = p.payroll_run WHERE p.docstatus = 1 AND r.posting_date BETWEEN @Start AND @End AND e.salary_component IN (SELECT overtime_component FROM reporting.payroll_settings)) / NULLIF((SELECT SUM(p.gross_earnings) FROM reporting.payslip p JOIN reporting.payroll_run r ON r.name = p.payroll_run WHERE p.docstatus = 1 AND r.posting_date BETWEEN @Start AND @End), 0), 2) AS value"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-083', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-083", "kpi_name": "Employees Exceeding Overtime Limit", "kpi_module": "HR", "sub_area": "Overtime", "is_active": true, "definition": "Employees exceeding statutory weekly or monthly overtime hours", "formula": "COUNT(DISTINCT employee with SUM(hours) > statutory limit)", "unit": "Persons", "direction": "Down", "target": "0", "frequency": "Weekly", "owner_role": "HR Operations", "source_doctypes": "OvertimeRequest", "key_fields": "hours, overtime_date", "platform_equivalent": "SAP SF Time", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_083", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT COUNT(DISTINCT employee) AS value FROM (SELECT employee, date_trunc(''week'', overtime_date) AS wk, SUM(hours) AS h FROM reporting.overtime_request WHERE workflow_state = ''Approved'' AND overtime_date BETWEEN @Start AND @End GROUP BY 1, 2) x WHERE h > 18"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-084', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-084", "kpi_name": "Holiday Overtime", "kpi_module": "HR", "sub_area": "Overtime", "is_active": true, "definition": "Proportion of overtime worked on rest days or public holidays", "formula": "SUM(hours WHERE day_type != ''Working day'') / SUM(hours) x100", "unit": "%", "direction": "Down", "target": "—", "frequency": "Monthly", "owner_role": "HR Operations", "source_doctypes": "OvertimeRequest", "key_fields": "day_type, hours", "platform_equivalent": "SAP SF", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_084", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (SUM(hours) FILTER (WHERE day_type <> ''Working day'')) / NULLIF(SUM(hours), 0), 2) AS value FROM reporting.overtime_request WHERE workflow_state = ''Approved'' AND overtime_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-085', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-085", "kpi_name": "Weighted Hours Ratio", "kpi_module": "HR", "sub_area": "Overtime", "is_active": true, "definition": "Statutory weighted overtime hours multiplier compared to actual hours", "formula": "SUM(weighted_hours) / SUM(hours)", "unit": "Ratio", "direction": "Range", "target": "—", "frequency": "Monthly", "owner_role": "Payroll", "source_doctypes": "OvertimeRequest", "key_fields": "weighted_hours, hours", "platform_equivalent": "—", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_085", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(SUM(weighted_hours) / NULLIF(SUM(hours), 0), 2) AS value FROM reporting.overtime_request WHERE workflow_state = ''Approved'' AND overtime_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-086', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-086", "kpi_name": "Overtime Approval Turnaround", "kpi_module": "HR", "sub_area": "Overtime", "is_active": true, "definition": "Average turnaround time for overtime request approvals", "formula": "AVG(OvertimeApproval workflow transition duration)", "unit": "Hours", "direction": "Down", "target": "≤ 24 hours", "frequency": "Monthly", "owner_role": "HR Operations", "source_doctypes": "OvertimeRequest", "key_fields": "workflow_state", "platform_equivalent": "Workday BP", "implementation": "Not available", "implementation_note": "Requires workflow transition timestamps per document (version/audit trail), which are not yet exposed to the reporting schema."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-087', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-087", "kpi_name": "Total Payroll Cost (Gross)", "kpi_module": "HR", "sub_area": "Payroll", "is_active": true, "definition": "Total gross salary paid across organization per period", "formula": "SUM(PayrollRun.total_gross)", "unit": "IDR", "direction": "Range", "target": "Within budget", "frequency": "Monthly", "owner_role": "Payroll Manager", "source_doctypes": "PayrollRun", "key_fields": "total_gross, period", "platform_equivalent": "Workday Payroll; SAP SF EC Payroll; NetSuite SuitePeople", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_087", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT COALESCE(SUM(total_gross), 0) AS value FROM reporting.payroll_run WHERE docstatus = 1 AND posting_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-088', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-088", "kpi_name": "Total Employer Cost", "kpi_module": "HR", "sub_area": "Payroll", "is_active": true, "definition": "Total employee cost including gross salary and employer contributions", "formula": "SUM(total_gross + total_employer_contributions)", "unit": "IDR", "direction": "Range", "target": "Within budget", "frequency": "Monthly", "owner_role": "Payroll Manager", "source_doctypes": "PayrollRun", "key_fields": "total_gross, total_employer_contributions", "platform_equivalent": "Workday / SAP", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_088", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT COALESCE(SUM(total_gross + total_employer_contributions), 0) AS value FROM reporting.payroll_run WHERE docstatus = 1 AND posting_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-089', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-089", "kpi_name": "Average Gross Salary per Employee", "kpi_module": "HR", "sub_area": "Payroll", "is_active": true, "definition": "Average gross earnings per employee", "formula": "SUM(total_gross) / SUM(employee_count)", "unit": "IDR", "direction": "Range", "target": "—", "frequency": "Monthly", "owner_role": "Compensation & Benefits", "source_doctypes": "PayrollRun", "key_fields": "total_gross, employee_count", "platform_equivalent": "Workday", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_089", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(SUM(total_gross) / NULLIF(SUM(employee_count), 0), 0) AS value FROM reporting.payroll_run WHERE docstatus = 1 AND posting_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-090', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-090", "kpi_name": "Net-to-Gross Ratio", "kpi_module": "HR", "sub_area": "Payroll", "is_active": true, "definition": "Take-home pay compared to gross salary", "formula": "SUM(total_net_pay) / SUM(total_gross) x100", "unit": "%", "direction": "Range", "target": "—", "frequency": "Monthly", "owner_role": "Payroll Manager", "source_doctypes": "PayrollRun", "key_fields": "total_net_pay, total_gross", "platform_equivalent": "Workday / SAP", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_090", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (SUM(total_net_pay)) / NULLIF(SUM(total_gross), 0), 2) AS value FROM reporting.payroll_run WHERE docstatus = 1 AND posting_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-091', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-091", "kpi_name": "Payroll Variance MoM", "kpi_module": "HR", "sub_area": "Payroll", "is_active": true, "definition": "Month-over-month percentage change in gross payroll", "formula": "(current month gross − last month gross) / last month gross x100", "unit": "%", "direction": "Range", "target": "± 3% (excluding holiday allowance/bonus)", "frequency": "Monthly", "owner_role": "Payroll Manager", "source_doctypes": "PayrollRun", "key_fields": "total_gross, period", "platform_equivalent": "Workday Payroll Audit", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_091", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "WITH m AS (SELECT period, SUM(total_gross) AS g, MAX(posting_date) AS d FROM reporting.payroll_run WHERE docstatus = 1 AND posting_date <= @End GROUP BY period), r AS (SELECT g, LAG(g) OVER (ORDER BY d) AS prev, ROW_NUMBER() OVER (ORDER BY d DESC) AS rn FROM m) SELECT (SELECT ROUND(100.0 * (g - prev) / NULLIF(prev, 0), 2) FROM r WHERE rn = 1) AS value"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-092', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-092", "kpi_name": "Payroll On-time Rate", "kpi_module": "HR", "sub_area": "Payroll", "is_active": true, "definition": "Payroll disbursement completed on or before scheduled pay date", "formula": "COUNT(PaymentEntry posting_date <= PayrollRun.payment_date) / COUNT(PayrollRun) x100", "unit": "%", "direction": "Up", "target": "100%", "frequency": "Monthly", "owner_role": "Payroll Manager", "source_doctypes": "PayrollRun, PaymentRun, PaymentEntry", "key_fields": "payment_date, payroll_run", "platform_equivalent": "Workday / SAP", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_092", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE EXISTS (SELECT 1 FROM reporting.payment_entry pe JOIN reporting.payment_run pr ON pr.name = pe.payment_run WHERE pr.payroll_run = r.name AND pe.docstatus = 1 AND pe.posting_date <= r.payment_date))) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.payroll_run r WHERE r.docstatus = 1 AND r.payment_date BETWEEN @Start AND LEAST(@End, CURRENT_DATE)"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-093', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-093", "kpi_name": "Payroll Accuracy", "kpi_module": "HR", "sub_area": "Payroll", "is_active": true, "definition": "Percentage of payslips generated without corrections or amendments", "formula": "1 − COUNT(Payslip amended/cancelled) / COUNT(Payslip) x100", "unit": "%", "direction": "Up", "target": "≥ 99,5%", "frequency": "Monthly", "owner_role": "Payroll Manager", "source_doctypes": "Payslip", "key_fields": "docstatus, amended_from", "platform_equivalent": "Workday Payroll Audit", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_093", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100 - 100.0 * COUNT(*) FILTER (WHERE p.docstatus = 2) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.payslip p JOIN reporting.payroll_run r ON r.name = p.payroll_run WHERE p.docstatus IN (1, 2) AND r.posting_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-094', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-094", "kpi_name": "Active Employees Without Salary Assignment", "kpi_module": "HR", "sub_area": "Payroll", "is_active": true, "definition": "Active employees missing an active salary structure assignment", "formula": "COUNT(Active employee without SalaryAssignment is_active=1)", "unit": "Persons", "direction": "Down", "target": "0", "frequency": "Monthly", "owner_role": "Payroll", "source_doctypes": "Employee, SalaryAssignment", "key_fields": "is_active", "platform_equivalent": "SAP SF Compensation", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_094", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT COUNT(*) AS value FROM reporting.employee e WHERE e.status = ''Active'' AND NOT EXISTS (SELECT 1 FROM reporting.salary_assignment s WHERE s.employee = e.name AND s.is_active)"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-095', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-095", "kpi_name": "Employees Without Bank Account", "kpi_module": "HR", "sub_area": "Payroll", "is_active": true, "definition": "Active employees without a default bank account configured", "formula": "COUNT(Active employee without bank_accounts is_default=1)", "unit": "Persons", "direction": "Down", "target": "0", "frequency": "Monthly", "owner_role": "Payroll", "source_doctypes": "Employee, PartyBankAccount", "key_fields": "bank_accounts", "platform_equivalent": "Workday Payment Elections", "implementation": "Not available", "implementation_note": "Source fields are restricted in reporting schema (permLevel 1 or attachment), so it cannot be computed by a widget."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-096', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-096", "kpi_name": "Effective PPh 21 Rate", "kpi_module": "HR", "sub_area": "Payroll", "is_active": true, "definition": "Income tax withholding (PPh 21) compared to taxable gross pay", "formula": "SUM(Payslip.pph21) / SUM(taxable_gross) x100", "unit": "%", "direction": "Range", "target": "Per statutory withholding table (TER)", "frequency": "Monthly", "owner_role": "Tax", "source_doctypes": "Payslip", "key_fields": "pph21, taxable_gross", "platform_equivalent": "SAP SF Payroll ID; Workday ID localization", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_096", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (SUM(p.pph21)) / NULLIF(SUM(p.taxable_gross), 0), 2) AS value FROM reporting.payslip p JOIN reporting.payroll_run r ON r.name = p.payroll_run WHERE p.docstatus = 1 AND r.posting_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-097', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-097", "kpi_name": "Government-borne Tax (PPh 21 DTP) Utilized", "kpi_module": "HR", "sub_area": "Payroll", "is_active": true, "definition": "Value of government-borne income tax incentives utilized", "formula": "SUM(PayrollRun.total_pph21_dtp)", "unit": "IDR", "direction": "Up", "target": "100% eligible employees covered", "frequency": "Monthly", "owner_role": "Tax", "source_doctypes": "PayrollRun, Payslip", "key_fields": "total_pph21_dtp, dtp_eligible", "platform_equivalent": "—", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_097", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT COALESCE(SUM(total_pph21_dtp), 0) AS value FROM reporting.payroll_run WHERE docstatus = 1 AND posting_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-098', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-098", "kpi_name": "December Tax Withholding Variance", "kpi_module": "HR", "sub_area": "Payroll", "is_active": true, "definition": "Annualized PPh 21 tax variance adjusted in December final payroll", "formula": "SUM(pph21_annual − pph21_before) WHERE is_last_period=1", "unit": "IDR", "direction": "Range", "target": "Near 0", "frequency": "Annual", "owner_role": "Tax", "source_doctypes": "Payslip", "key_fields": "pph21_annual, pph21_before, is_last_period", "platform_equivalent": "—", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_098", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT COALESCE(SUM(p.pph21_annual - p.pph21_before), 0) AS value FROM reporting.payslip p JOIN reporting.payroll_run r ON r.name = p.payroll_run WHERE p.docstatus = 1 AND r.posting_date BETWEEN @Start AND @End AND p.is_last_period"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-099', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-099", "kpi_name": "Employer Social Security (BPJS TK) Cost", "kpi_module": "HR", "sub_area": "Payroll", "is_active": true, "definition": "Employer social security contributions (JHT + JP + JKK + JKM)", "formula": "SUM(jht_employer + jp_employer + jkk + jkm)", "unit": "IDR", "direction": "Range", "target": "Per PayrollSettings rate", "frequency": "Monthly", "owner_role": "Payroll", "source_doctypes": "Payslip", "key_fields": "jht_employer, jp_employer, jkk, jkm", "platform_equivalent": "SAP SF / Workday ID", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_099", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(COALESCE(SUM(p.jht_employer + p.jp_employer + p.jkk + p.jkm), 0), 0) AS value FROM reporting.payslip p JOIN reporting.payroll_run r ON r.name = p.payroll_run WHERE p.docstatus = 1 AND r.posting_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-100', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-100", "kpi_name": "Employer Health Insurance (BPJS Kes) Cost", "kpi_module": "HR", "sub_area": "Payroll", "is_active": true, "definition": "Employer healthcare insurance premium contributions", "formula": "SUM(kes_employer)", "unit": "IDR", "direction": "Range", "target": "—", "frequency": "Monthly", "owner_role": "Payroll", "source_doctypes": "Payslip", "key_fields": "kes_employer", "platform_equivalent": "—", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_100", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(COALESCE(SUM(p.kes_employer), 0), 0) AS value FROM reporting.payslip p JOIN reporting.payroll_run r ON r.name = p.payroll_run WHERE p.docstatus = 1 AND r.posting_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-101', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-101", "kpi_name": "Social Security (BPJS) Participation", "kpi_module": "HR", "sub_area": "Payroll", "is_active": true, "definition": "Active employees enrolled in statutory BPJS TK and Health schemes", "formula": "COUNT(SalaryAssignment bpjs_employment=1 AND bpjs_health=1) / COUNT(Active) x100", "unit": "%", "direction": "Up", "target": "100%", "frequency": "Monthly", "owner_role": "Payroll", "source_doctypes": "SalaryAssignment", "key_fields": "bpjs_employment, bpjs_health", "platform_equivalent": "—", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_101", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE EXISTS (SELECT 1 FROM reporting.salary_assignment s WHERE s.employee = e.name AND s.is_active AND s.bpjs_employment AND s.bpjs_health))) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.employee e WHERE e.status = ''Active''"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-102', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-102", "kpi_name": "Non-regular Components % Gross", "kpi_module": "HR", "sub_area": "Payroll", "is_active": true, "definition": "Bonus, THR, and variable payments compared to gross payroll", "formula": "SUM(PayslipDetail amount is_regular=0) / SUM(gross_earnings) x100", "unit": "%", "direction": "Range", "target": "—", "frequency": "Monthly", "owner_role": "Compensation & Benefits", "source_doctypes": "PayslipDetail", "key_fields": "is_regular, amount", "platform_equivalent": "Workday Compensation", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_102", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (SELECT SUM(x.amount) FROM reporting.payslip_earnings x JOIN reporting.payslip p ON p.name = x.parent JOIN reporting.payroll_run r ON r.name = p.payroll_run WHERE p.docstatus = 1 AND r.posting_date BETWEEN @Start AND @End AND NOT COALESCE(x.is_regular, true)) / NULLIF((SELECT SUM(p.gross_earnings) FROM reporting.payslip p JOIN reporting.payroll_run r ON r.name = p.payroll_run WHERE p.docstatus = 1 AND r.posting_date BETWEEN @Start AND @End), 0), 2) AS value"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-103', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-103", "kpi_name": "Attendance Deductions", "kpi_module": "HR", "sub_area": "Payroll", "is_active": true, "definition": "Salary deductions incurred from absences and unpaid leave", "formula": "SUM(absent_days + unpaid_leave_days deduction value)", "unit": "Days / IDR", "direction": "Down", "target": "—", "frequency": "Monthly", "owner_role": "Payroll", "source_doctypes": "Payslip", "key_fields": "absent_days, unpaid_leave_days", "platform_equivalent": "SAP SF", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_103", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT COALESCE(SUM(p.absent_days + p.unpaid_leave_days), 0) AS value FROM reporting.payslip p JOIN reporting.payroll_run r ON r.name = p.payroll_run WHERE p.docstatus = 1 AND r.posting_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-104', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-104", "kpi_name": "Payroll Cost per Cost Center", "kpi_module": "HR", "sub_area": "Payroll", "is_active": true, "definition": "Gross payroll and employer taxes distributed by cost center", "formula": "SUM(gross_earnings + employer_contributions) GROUP BY cost_center", "unit": "IDR", "direction": "Range", "target": "Within budget", "frequency": "Monthly", "owner_role": "Controller", "source_doctypes": "Payslip", "key_fields": "cost_center", "platform_equivalent": "Workday Cost Allocation; SAP CO", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_104", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT COALESCE(p.cost_center, ''(blank)'') AS label, SUM(p.gross_earnings + p.employer_contributions) AS value FROM reporting.payslip p JOIN reporting.payroll_run r ON r.name = p.payroll_run WHERE p.docstatus = 1 AND r.posting_date BETWEEN @Start AND @End GROUP BY 1 ORDER BY 2 DESC"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-105', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-105", "kpi_name": "Appraisal Completion Rate", "kpi_module": "HR", "sub_area": "Performance", "is_active": true, "definition": "Performance appraisals completed within evaluation cycle", "formula": "COUNT(Appraisal state=''Completed'') / COUNT(Eligible active employees) x100", "unit": "%", "direction": "Up", "target": "100%", "frequency": "Per cycle", "owner_role": "HR Manager", "source_doctypes": "Appraisal, AppraisalCycle", "key_fields": "workflow_state, appraisal_cycle", "platform_equivalent": "Workday Performance; SAP SF PMGM", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_105", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (SELECT COUNT(*) FROM reporting.appraisal WHERE workflow_state = ''Completed'' AND appraisal_cycle IN (SELECT name FROM reporting.appraisal_cycle WHERE start_date <= @End AND end_date >= @Start)) / NULLIF((SELECT COUNT(*) FROM reporting.employee WHERE status = ''Active'') * (SELECT COUNT(*) FROM (SELECT name FROM reporting.appraisal_cycle WHERE start_date <= @End AND end_date >= @Start) c), 0), 2) AS value"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-106', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-106", "kpi_name": "Average Final Score", "kpi_module": "HR", "sub_area": "Performance", "is_active": true, "definition": "Average final performance evaluation appraisal score", "formula": "AVG(final_score)", "unit": "Score", "direction": "Up", "target": "—", "frequency": "Per cycle", "owner_role": "HR Manager", "source_doctypes": "Appraisal", "key_fields": "final_score", "platform_equivalent": "Workday / SAP SF", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_106", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(AVG(final_score), 2) AS value FROM reporting.appraisal WHERE workflow_state = ''Completed'' AND appraisal_cycle IN (SELECT name FROM reporting.appraisal_cycle WHERE start_date <= @End AND end_date >= @Start)"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-107', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-107", "kpi_name": "Rating Distribution", "kpi_module": "HR", "sub_area": "Performance", "is_active": true, "definition": "Percentage distribution of employees across performance rating tiers", "formula": "COUNT(Appraisal per rating) / COUNT(Appraisal) x100", "unit": "%", "direction": "Range", "target": "Outstanding ≤ 10%, Unsatisfactory ≤ 5%", "frequency": "Per cycle", "owner_role": "HR Manager", "source_doctypes": "Appraisal", "key_fields": "rating", "platform_equivalent": "SAP SF Calibration; Workday Calibration", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_107", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT COALESCE(rating, ''(unrated)'') AS label, COUNT(*) AS value FROM reporting.appraisal WHERE workflow_state = ''Completed'' AND appraisal_cycle IN (SELECT name FROM reporting.appraisal_cycle WHERE start_date <= @End AND end_date >= @Start) GROUP BY 1 ORDER BY 2 DESC"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-108', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-108", "kpi_name": "High Performer Ratio", "kpi_module": "HR", "sub_area": "Performance", "is_active": true, "definition": "Percentage of employees rated Outstanding or Exceeds Expectations", "formula": "COUNT(rating IN (''Outstanding'',''Exceeds expectations'')) / COUNT x100", "unit": "%", "direction": "Range", "target": "15–25%", "frequency": "Per cycle", "owner_role": "HR Manager", "source_doctypes": "Appraisal", "key_fields": "rating", "platform_equivalent": "Workday 9-box", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_108", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE rating IN (''Outstanding'',''Exceeds expectations''))) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.appraisal WHERE workflow_state = ''Completed'' AND appraisal_cycle IN (SELECT name FROM reporting.appraisal_cycle WHERE start_date <= @End AND end_date >= @Start)"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-109', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-109", "kpi_name": "Low Performer Ratio", "kpi_module": "HR", "sub_area": "Performance", "is_active": true, "definition": "Percentage of employees rated Needs Improvement or Unsatisfactory", "formula": "COUNT(rating IN (''Needs improvement'',''Unsatisfactory'')) / COUNT x100", "unit": "%", "direction": "Down", "target": "≤ 10%", "frequency": "Per cycle", "owner_role": "HR Manager", "source_doctypes": "Appraisal", "key_fields": "rating", "platform_equivalent": "Workday / SAP SF", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_109", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE rating IN (''Needs improvement'',''Unsatisfactory''))) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.appraisal WHERE workflow_state = ''Completed'' AND appraisal_cycle IN (SELECT name FROM reporting.appraisal_cycle WHERE start_date <= @End AND end_date >= @Start)"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-110', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-110", "kpi_name": "Goal Weight Compliance", "kpi_module": "HR", "sub_area": "Performance", "is_active": true, "definition": "Percentage of appraisals where goal weights total exactly 100%", "formula": "COUNT(total_weight=100) / COUNT(Appraisal) x100", "unit": "%", "direction": "Up", "target": "100%", "frequency": "Per cycle", "owner_role": "HR Manager", "source_doctypes": "Appraisal", "key_fields": "total_weight", "platform_equivalent": "SAP SF Goal Mgmt", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_110", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE total_weight = 100)) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.appraisal WHERE workflow_state <> ''Cancelled'' AND appraisal_cycle IN (SELECT name FROM reporting.appraisal_cycle WHERE start_date <= @End AND end_date >= @Start)"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-111', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-111", "kpi_name": "Self vs Manager Score Gap", "kpi_module": "HR", "sub_area": "Performance", "is_active": true, "definition": "Average variance between employee self-score and manager rating", "formula": "AVG(self_score − manager_score)", "unit": "Points", "direction": "Range", "target": "Near 0", "frequency": "Per cycle", "owner_role": "HRBP", "source_doctypes": "AppraisalGoal", "key_fields": "self_score, manager_score", "platform_equivalent": "SAP SF / Workday", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_111", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(AVG(g.self_score - g.manager_score), 2) AS value FROM reporting.appraisal_goals g JOIN reporting.appraisal a ON a.name = g.parent WHERE a.workflow_state = ''Completed'' AND a.appraisal_cycle IN (SELECT name FROM reporting.appraisal_cycle WHERE start_date <= @End AND end_date >= @Start) AND g.self_score IS NOT NULL AND g.manager_score IS NOT NULL"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-112', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-112", "kpi_name": "Development Plans Completed", "kpi_module": "HR", "sub_area": "Performance", "is_active": true, "definition": "Performance appraisals with defined individual development plans", "formula": "COUNT(development_plan filled) / COUNT(Appraisal) x100", "unit": "%", "direction": "Up", "target": "100%", "frequency": "Per cycle", "owner_role": "HRBP", "source_doctypes": "Appraisal", "key_fields": "development_plan", "platform_equivalent": "Workday Development Plan", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_112", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE COALESCE(development_plan, '''') <> '''')) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.appraisal WHERE workflow_state = ''Completed'' AND appraisal_cycle IN (SELECT name FROM reporting.appraisal_cycle WHERE start_date <= @End AND end_date >= @Start)"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-113', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-113", "kpi_name": "Appraisal Overdue", "kpi_module": "HR", "sub_area": "Performance", "is_active": true, "definition": "Incomplete appraisals after evaluation cycle closing date", "formula": "COUNT(Appraisal not Completed AND cycle.end_date < CURRENT_DATE)", "unit": "Appraisals", "direction": "Down", "target": "0", "frequency": "Weekly", "owner_role": "HR Manager", "source_doctypes": "Appraisal, AppraisalCycle", "key_fields": "workflow_state, end_date", "platform_equivalent": "Workday", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_113", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT COUNT(*) AS value FROM reporting.appraisal a JOIN reporting.appraisal_cycle c ON c.name = a.appraisal_cycle WHERE a.workflow_state NOT IN (''Completed'',''Cancelled'') AND c.end_date < CURRENT_DATE"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-114', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-114", "kpi_name": "Regretted Attrition High Performer", "kpi_module": "HR", "sub_area": "Performance", "is_active": true, "definition": "High-performing employees resigning voluntarily", "formula": "COUNT(EmployeeSeparation separation_type=''Resignation'' AND high performer) / COUNT(High performers) x100", "unit": "%", "direction": "Down", "target": "≤ 5%", "frequency": "Quarterly", "owner_role": "CHRO", "source_doctypes": "EmployeeSeparation, Appraisal", "key_fields": "separation_type, rating", "platform_equivalent": "Workday Regretted Turnover", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_114", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "WITH last_rating AS (SELECT DISTINCT ON (a.employee) a.employee, a.rating FROM reporting.appraisal a JOIN reporting.appraisal_cycle c ON c.name = a.appraisal_cycle WHERE a.workflow_state = ''Completed'' ORDER BY a.employee, c.end_date DESC), hp AS (SELECT employee FROM last_rating WHERE rating IN (''Outstanding'',''Exceeds expectations'')) SELECT ROUND(100.0 * (SELECT COUNT(*) FROM reporting.employee_separation s WHERE s.docstatus = 1 AND s.separation_type = ''Resignation'' AND s.last_working_date BETWEEN @Start AND @End AND s.employee IN (SELECT employee FROM hp)) / NULLIF((SELECT COUNT(*) FROM hp), 0), 2) AS value"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-115', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-115", "kpi_name": "Training Hours per Employee", "kpi_module": "HR", "sub_area": "Training", "is_active": true, "definition": "Total employee training hours delivered compared to headcount", "formula": "SUM(duration hours × attendees present) / AVG headcount", "unit": "Hours", "direction": "Up", "target": "≥ 20 hours/year", "frequency": "Quarterly", "owner_role": "Learning & Development", "source_doctypes": "TrainingEvent, TrainingAttendee", "key_fields": "start_at, end_at, attendance", "platform_equivalent": "Workday Learning; SAP SF Learning; M365 Viva Learning", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_115", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND((SELECT SUM(EXTRACT(EPOCH FROM (t.end_at - t.start_at)) / 3600.0) FROM reporting.training_event_attendees x JOIN reporting.training_event t ON t.name = x.parent WHERE x.attendance = ''Attended'' AND t.docstatus = 1 AND t.start_at::date BETWEEN @Start AND @End) / NULLIF((((SELECT COUNT(*) FROM reporting.employee e WHERE e.hire_date <= @Start::date AND (e.separation_date IS NULL OR e.separation_date > @Start::date)) + (SELECT COUNT(*) FROM reporting.employee e WHERE e.hire_date <= @End::date AND (e.separation_date IS NULL OR e.separation_date > @End::date))) / 2.0), 0), 1) AS value"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-116', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-116", "kpi_name": "Training Attendance Rate", "kpi_module": "HR", "sub_area": "Training", "is_active": true, "definition": "Actual training participants compared to registered attendees", "formula": "SUM(attended_count) / COUNT(TrainingAttendee) x100", "unit": "%", "direction": "Up", "target": "≥ 90%", "frequency": "Monthly", "owner_role": "Learning & Development", "source_doctypes": "TrainingEvent, TrainingAttendee", "key_fields": "attended_count, attendance", "platform_equivalent": "SAP SF Learning", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_116", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE x.attendance = ''Attended'')) / NULLIF(COUNT(*) FILTER (WHERE x.attendance IN (''Attended'',''Absent'')), 0), 2) AS value FROM reporting.training_event_attendees x JOIN reporting.training_event t ON t.name = x.parent WHERE t.docstatus = 1 AND t.start_at::date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-117', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-117", "kpi_name": "Training Cost per Participant", "kpi_module": "HR", "sub_area": "Training", "is_active": true, "definition": "Total training expense per actual attendee", "formula": "SUM(cost) / SUM(attended_count)", "unit": "IDR", "direction": "Down", "target": "Within L&D budget", "frequency": "Quarterly", "owner_role": "Learning & Development", "source_doctypes": "TrainingEvent", "key_fields": "cost, attended_count", "platform_equivalent": "Workday Learning", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_117", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(SUM(t.cost) / NULLIF(SUM(t.attended_count), 0), 0) AS value FROM reporting.training_event t WHERE t.docstatus = 1 AND t.start_at::date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-118', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-118", "kpi_name": "Training Spend % Payroll", "kpi_module": "HR", "sub_area": "Training", "is_active": true, "definition": "Training budget investment compared to gross payroll expense", "formula": "SUM(TrainingEvent.cost) / SUM(PayrollRun.total_gross) x100", "unit": "%", "direction": "Range", "target": "1–3%", "frequency": "Annual", "owner_role": "Learning & Development", "source_doctypes": "TrainingEvent, PayrollRun", "key_fields": "cost, total_gross", "platform_equivalent": "Workday", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_118", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (SELECT SUM(t.cost) FROM reporting.training_event t WHERE t.docstatus = 1 AND t.start_at::date BETWEEN @Start AND @End) / NULLIF((SELECT SUM(total_gross) FROM reporting.payroll_run WHERE docstatus = 1 AND posting_date BETWEEN @Start AND @End), 0), 2) AS value"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-119', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-119", "kpi_name": "Average Training Score", "kpi_module": "HR", "sub_area": "Training", "is_active": true, "definition": "Average participant test or evaluation score post-training", "formula": "AVG(score)", "unit": "Score", "direction": "Up", "target": "≥ 75", "frequency": "Per event", "owner_role": "Learning & Development", "source_doctypes": "TrainingAttendee", "key_fields": "score", "platform_equivalent": "SAP SF Learning", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_119", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(AVG(x.score), 1) AS value FROM reporting.training_event_attendees x JOIN reporting.training_event t ON t.name = x.parent WHERE x.attendance = ''Attended'' AND x.score IS NOT NULL AND t.docstatus = 1 AND t.start_at::date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-120', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-120", "kpi_name": "Training Coverage", "kpi_module": "HR", "sub_area": "Training", "is_active": true, "definition": "Percentage of active employees participating in at least 1 training event", "formula": "COUNT(DISTINCT employee attended) / COUNT(Active) x100", "unit": "%", "direction": "Up", "target": "≥ 80%/year", "frequency": "Annual", "owner_role": "Learning & Development", "source_doctypes": "TrainingAttendee", "key_fields": "employee, attendance", "platform_equivalent": "Workday Learning", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_120", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (SELECT COUNT(DISTINCT x.employee) FROM reporting.training_event_attendees x JOIN reporting.training_event t ON t.name = x.parent WHERE x.attendance = ''Attended'' AND t.docstatus = 1 AND t.start_at::date BETWEEN @Start AND @End) / NULLIF((SELECT COUNT(*) FROM reporting.employee WHERE status = ''Active''), 0), 2) AS value"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-121', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-121", "kpi_name": "Certificates Uploaded", "kpi_module": "HR", "sub_area": "Training", "is_active": true, "definition": "Trained participants who have uploaded certification proof", "formula": "COUNT(certificate filled) / COUNT(Attended) x100", "unit": "%", "direction": "Up", "target": "100%", "frequency": "Quarterly", "owner_role": "Learning & Development", "source_doctypes": "TrainingAttendee", "key_fields": "certificate", "platform_equivalent": "SAP SF Learning", "implementation": "Not available", "implementation_note": "Source fields are restricted in reporting schema (permLevel 1 or attachment), so it cannot be computed by a widget."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-122', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-122", "kpi_name": "Turnover Rate", "kpi_module": "HR", "sub_area": "Turnover", "is_active": true, "definition": "Total employee separations compared to average headcount", "formula": "COUNT(EmployeeSeparation docstatus=1 in period) / AVG headcount x100", "unit": "%", "direction": "Down", "target": "≤ 10%/year", "frequency": "Monthly", "owner_role": "CHRO", "source_doctypes": "EmployeeSeparation, Employee", "key_fields": "last_working_date", "platform_equivalent": "Workday Turnover; SAP SF; NetSuite SuitePeople", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_122", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (SELECT COUNT(*) FROM reporting.employee_separation s WHERE s.docstatus = 1 AND s.last_working_date BETWEEN @Start AND @End) / NULLIF((((SELECT COUNT(*) FROM reporting.employee e WHERE e.hire_date <= @Start::date AND (e.separation_date IS NULL OR e.separation_date > @Start::date)) + (SELECT COUNT(*) FROM reporting.employee e WHERE e.hire_date <= @End::date AND (e.separation_date IS NULL OR e.separation_date > @End::date))) / 2.0), 0), 2) AS value"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-123', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-123", "kpi_name": "Voluntary Turnover Rate", "kpi_module": "HR", "sub_area": "Turnover", "is_active": true, "definition": "Voluntary resignations compared to average headcount", "formula": "COUNT(separation_type=''Resignation'') / AVG headcount x100", "unit": "%", "direction": "Down", "target": "≤ 7%/year", "frequency": "Monthly", "owner_role": "CHRO", "source_doctypes": "EmployeeSeparation", "key_fields": "separation_type", "platform_equivalent": "Workday Voluntary Termination", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_123", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (SELECT COUNT(*) FROM reporting.employee_separation s WHERE s.docstatus = 1 AND s.last_working_date BETWEEN @Start AND @End AND s.separation_type = ''Resignation'') / NULLIF((((SELECT COUNT(*) FROM reporting.employee e WHERE e.hire_date <= @Start::date AND (e.separation_date IS NULL OR e.separation_date > @Start::date)) + (SELECT COUNT(*) FROM reporting.employee e WHERE e.hire_date <= @End::date AND (e.separation_date IS NULL OR e.separation_date > @End::date))) / 2.0), 0), 2) AS value"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-124', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-124", "kpi_name": "Involuntary Turnover Rate", "kpi_module": "HR", "sub_area": "Turnover", "is_active": true, "definition": "Employer-initiated terminations compared to average headcount", "formula": "COUNT(separation_type=''PHK'') / AVG headcount x100", "unit": "%", "direction": "Down", "target": "—", "frequency": "Monthly", "owner_role": "CHRO", "source_doctypes": "EmployeeSeparation", "key_fields": "separation_type", "platform_equivalent": "Workday", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_124", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (SELECT COUNT(*) FROM reporting.employee_separation s WHERE s.docstatus = 1 AND s.last_working_date BETWEEN @Start AND @End AND s.separation_type = ''PHK'') / NULLIF((((SELECT COUNT(*) FROM reporting.employee e WHERE e.hire_date <= @Start::date AND (e.separation_date IS NULL OR e.separation_date > @Start::date)) + (SELECT COUNT(*) FROM reporting.employee e WHERE e.hire_date <= @End::date AND (e.separation_date IS NULL OR e.separation_date > @End::date))) / 2.0), 0), 2) AS value"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-125', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-125", "kpi_name": "First-Year Attrition", "kpi_module": "HR", "sub_area": "Turnover", "is_active": true, "definition": "Employees leaving with less than 1 year of service", "formula": "COUNT(last_working_date − hire_date < 365) / COUNT(Hires in last 12 months) x100", "unit": "%", "direction": "Down", "target": "≤ 15%", "frequency": "Quarterly", "owner_role": "Recruitment Lead", "source_doctypes": "EmployeeSeparation, Employee", "key_fields": "last_working_date, hire_date", "platform_equivalent": "Workday Early Turnover", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_125", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (SELECT COUNT(*) FROM reporting.employee_separation s JOIN reporting.employee e ON e.name = s.employee WHERE s.docstatus = 1 AND s.last_working_date BETWEEN @Start AND @End AND s.last_working_date - e.hire_date < 365) / NULLIF((SELECT COUNT(*) FROM reporting.employee e WHERE e.hire_date BETWEEN @Start::date - 365 AND @End), 0), 2) AS value"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-126', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-126", "kpi_name": "Retention Rate", "kpi_module": "HR", "sub_area": "Turnover", "is_active": true, "definition": "Employees retained from beginning to end of period", "formula": "(Beginning headcount − departures from cohort) / Beginning headcount x100", "unit": "%", "direction": "Up", "target": "≥ 90%", "frequency": "Annual", "owner_role": "CHRO", "source_doctypes": "Employee, EmployeeSeparation", "key_fields": "status, separation_date", "platform_equivalent": "Workday Retention", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_126", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE separation_date IS NULL OR separation_date > @End)) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.employee WHERE hire_date < @Start AND (separation_date IS NULL OR separation_date >= @Start)"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-127', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-127", "kpi_name": "Exit Interview Completion", "kpi_module": "HR", "sub_area": "Turnover", "is_active": true, "definition": "Separations with completed exit interview documentation", "formula": "COUNT(exit_interview_done=1) / COUNT(EmployeeSeparation) x100", "unit": "%", "direction": "Up", "target": "100%", "frequency": "Monthly", "owner_role": "HRBP", "source_doctypes": "EmployeeSeparation", "key_fields": "exit_interview_done", "platform_equivalent": "Workday Exit Survey; M365 Forms", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_127", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE s.exit_interview_done)) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.employee_separation s WHERE s.docstatus = 1 AND s.last_working_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-128', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-128", "kpi_name": "Eligible for Rehire Ratio", "kpi_module": "HR", "sub_area": "Turnover", "is_active": true, "definition": "Departing employees designated as eligible for rehire", "formula": "COUNT(eligible_for_rehire=1) / COUNT(EmployeeSeparation) x100", "unit": "%", "direction": "Up", "target": "—", "frequency": "Quarterly", "owner_role": "HRBP", "source_doctypes": "EmployeeSeparation", "key_fields": "eligible_for_rehire", "platform_equivalent": "Workday", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_128", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE s.eligible_for_rehire)) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.employee_separation s WHERE s.docstatus = 1 AND s.last_working_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-129', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-129", "kpi_name": "Clearance Checklist Completion", "kpi_module": "HR", "sub_area": "Turnover", "is_active": true, "definition": "Offboarding asset and access clearance items completed", "formula": "COUNT(SeparationChecklistItem is_done=1) / COUNT(Items) x100", "unit": "%", "direction": "Up", "target": "100% before last working date", "frequency": "Weekly", "owner_role": "HR Administrator", "source_doctypes": "SeparationChecklistItem", "key_fields": "is_done, responsible", "platform_equivalent": "Workday Offboarding; SAP SF Offboarding", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_129", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE c.is_done)) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.employee_separation_checklist c JOIN reporting.employee_separation s ON s.name = c.parent WHERE s.docstatus IN (0, 1) AND s.last_working_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-130', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-130", "kpi_name": "Average Notice Period", "kpi_module": "HR", "sub_area": "Turnover", "is_active": true, "definition": "Average days between notice date and last working date", "formula": "AVG(last_working_date − notice_date)", "unit": "Days", "direction": "Range", "target": "≥ 30 days (resignation)", "frequency": "Quarterly", "owner_role": "HRBP", "source_doctypes": "EmployeeSeparation", "key_fields": "notice_date, last_working_date", "platform_equivalent": "Workday", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_130", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(AVG(s.last_working_date - s.notice_date), 1) AS value FROM reporting.employee_separation s WHERE s.docstatus = 1 AND s.last_working_date BETWEEN @Start AND @End AND s.notice_date IS NOT NULL"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-131', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-131", "kpi_name": "Total Severance Pay", "kpi_module": "HR", "sub_area": "Turnover", "is_active": true, "definition": "Total statutory severance entitlements paid (UP + UPMK + UPH + separation pay)", "formula": "SUM(total_entitlement)", "unit": "IDR", "direction": "Range", "target": "Per provisioning policy", "frequency": "Quarterly", "owner_role": "Controller + HR", "source_doctypes": "EmployeeSeparation", "key_fields": "severance_pay, service_pay, compensation_pay, separation_pay, total_entitlement", "platform_equivalent": "—", "implementation": "Not available", "implementation_note": "Source fields are restricted in reporting schema (permLevel 1 or attachment), so it cannot be computed by a widget."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-132', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-132", "kpi_name": "Departed Employees With Active Access", "kpi_module": "HR", "sub_area": "Turnover", "is_active": true, "definition": "Employees with Left status retaining active salary structure or system access", "formula": "COUNT(Employee status=''Left'' AND SalaryAssignment is_active=1)", "unit": "Persons", "direction": "Down", "target": "0", "frequency": "Monthly", "owner_role": "Payroll", "source_doctypes": "Employee, SalaryAssignment", "key_fields": "status, is_active", "platform_equivalent": "Workday Termination BP", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_132", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT COUNT(*) AS value FROM reporting.employee e WHERE e.status = ''Left'' AND EXISTS (SELECT 1 FROM reporting.salary_assignment s WHERE s.employee = e.name AND s.is_active)"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'HR-133', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "HR-133", "kpi_name": "Exit Reason Breakdown", "kpi_module": "HR", "sub_area": "Turnover", "is_active": true, "definition": "Percentage distribution of departures by separation reason", "formula": "COUNT per separation_type / COUNT total x100", "unit": "%", "direction": "Range", "target": "—", "frequency": "Quarterly", "owner_role": "CHRO", "source_doctypes": "EmployeeSeparation", "key_fields": "separation_type", "platform_equivalent": "Workday Termination Reasons", "implementation": "Dashboard widget", "widget_id": "w_kpi_hr_133", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT COALESCE(s.separation_type, ''(blank)'') AS label, COUNT(*) AS value FROM reporting.employee_separation s WHERE s.docstatus = 1 AND s.last_working_date BETWEEN @Start AND @End GROUP BY 1 ORDER BY 2 DESC"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-001', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-001", "kpi_name": "Total Outstanding Receivables", "kpi_module": "FINANCE", "sub_area": "Accounts Receivable (AR)", "is_active": true, "definition": "Outstanding balance of unpaid sales invoices", "formula": "SUM(SalesInvoice.outstanding_amount, docstatus=1) − SUM(SalesCreditNote.outstanding_amount)", "unit": "IDR", "direction": "Down", "target": "—", "frequency": "Daily", "owner_role": "AR Lead", "source_doctypes": "SalesInvoice, SalesCreditNote", "key_fields": "outstanding_amount", "platform_equivalent": "NetSuite A/R Aging; SAP FI-AR (FBL5N); Workday Customer Accounts", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_001", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT ROUND((SELECT COALESCE(SUM(outstanding_amount * exchange_rate), 0) FROM reporting.sales_invoice WHERE docstatus = 1) - (SELECT COALESCE(SUM(outstanding_amount * exchange_rate), 0) FROM reporting.sales_credit_note WHERE docstatus = 1), 0) AS value"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-002', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-002", "kpi_name": "DSO (Days Sales Outstanding)", "kpi_module": "FINANCE", "sub_area": "Accounts Receivable (AR)", "is_active": true, "definition": "Average collection period for receivables in days", "formula": "(Outstanding receivables / Credit sales in period) × days in period", "unit": "Days", "direction": "Down", "target": "≤ 45 days", "frequency": "Monthly", "owner_role": "CFO", "source_doctypes": "SalesInvoice", "key_fields": "outstanding_amount, base_grand_total, posting_date", "platform_equivalent": "NetSuite KPI DSO; SAP Fiori DSO; Workday", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_002", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND((SELECT COALESCE(SUM(outstanding_amount * exchange_rate), 0) FROM reporting.sales_invoice WHERE docstatus = 1) / NULLIF((SELECT SUM(base_grand_total) FROM reporting.sales_invoice WHERE docstatus = 1 AND posting_date BETWEEN @Start AND @End), 0) * (@End::date - @Start::date + 1), 1) AS value"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-003', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-003", "kpi_name": "Overdue Receivables", "kpi_module": "FINANCE", "sub_area": "Accounts Receivable (AR)", "is_active": true, "definition": "Receivables past due date", "formula": "SUM(outstanding_amount WHERE due_date < CURRENT_DATE)", "unit": "IDR", "direction": "Down", "target": "≤ 10% total AR", "frequency": "Daily", "owner_role": "AR Lead", "source_doctypes": "SalesInvoice", "key_fields": "outstanding_amount, due_date", "platform_equivalent": "NetSuite / SAP", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_003", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT ROUND(COALESCE(SUM(outstanding_amount * exchange_rate), 0), 0) AS value FROM reporting.sales_invoice WHERE docstatus = 1 AND outstanding_amount > 0 AND due_date < CURRENT_DATE"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-004', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-004", "kpi_name": "Overdue AR %", "kpi_module": "FINANCE", "sub_area": "Accounts Receivable (AR)", "is_active": true, "definition": "Proportion of receivables past due", "formula": "Overdue AR / Total AR x100", "unit": "%", "direction": "Down", "target": "≤ 10%", "frequency": "Weekly", "owner_role": "AR Lead", "source_doctypes": "SalesInvoice", "key_fields": "outstanding_amount, due_date", "platform_equivalent": "SAP Fiori Overdue Receivables", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_004", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT ROUND(100.0 * (SUM(outstanding_amount * exchange_rate) FILTER (WHERE due_date < CURRENT_DATE)) / NULLIF(SUM(outstanding_amount * exchange_rate), 0), 2) AS value FROM reporting.sales_invoice WHERE docstatus = 1 AND outstanding_amount > 0"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-005', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-005", "kpi_name": "AR Aging > 90 Days", "kpi_module": "FINANCE", "sub_area": "Accounts Receivable (AR)", "is_active": true, "definition": "Receivables overdue by more than 90 days", "formula": "SUM(outstanding WHERE CURRENT_DATE − due_date > 90) / Total AR x100", "unit": "%", "direction": "Down", "target": "≤ 5%", "frequency": "Weekly", "owner_role": "AR Lead", "source_doctypes": "SalesInvoice (Laporan ReceivableAgingReport)", "key_fields": "outstanding_amount, due_date", "platform_equivalent": "NetSuite A/R Aging; SAP S_ALR_87012178", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_005", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT ROUND(100.0 * (SUM(outstanding_amount * exchange_rate) FILTER (WHERE CURRENT_DATE - due_date > 90)) / NULLIF(SUM(outstanding_amount * exchange_rate), 0), 2) AS value FROM reporting.sales_invoice WHERE docstatus = 1 AND outstanding_amount > 0"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-006', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-006", "kpi_name": "Collection Effectiveness Index (CEI)", "kpi_module": "FINANCE", "sub_area": "Accounts Receivable (AR)", "is_active": true, "definition": "Collection effectiveness achieved during the period", "formula": "(Beginning AR + Sales − Ending AR) / (Beginning AR + Sales − Ending current AR) x100", "unit": "%", "direction": "Up", "target": "≥ 85%", "frequency": "Monthly", "owner_role": "AR Lead", "source_doctypes": "SalesInvoice, PaymentEntry", "key_fields": "outstanding_amount, paid_amount", "platform_equivalent": "NetSuite custom KPI; SAP", "implementation": "Built-in report", "builtin_report": "ReceivableAgingReport", "implementation_note": "Requires opening accounts receivable balances for the period (snapshot aging), not just current outstanding amounts. Use the built-in ReceivableAgingReport."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-007', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-007", "kpi_name": "Average Days to Pay", "kpi_module": "FINANCE", "sub_area": "Accounts Receivable (AR)", "is_active": true, "definition": "Average days elapsed from invoice date to customer payment", "formula": "AVG(PaymentEntry.posting_date − SalesInvoice.posting_date) via references", "unit": "Days", "direction": "Down", "target": "≤ payment terms", "frequency": "Monthly", "owner_role": "AR Lead", "source_doctypes": "PaymentEntry, PaymentEntryReference, SalesInvoice", "key_fields": "posting_date, reference_name", "platform_equivalent": "NetSuite", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_007", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(AVG(pe.posting_date - si.posting_date), 1) AS value FROM reporting.payment_entry_references r JOIN reporting.payment_entry pe ON pe.name = r.parent JOIN reporting.sales_invoice si ON si.name = r.reference_name WHERE r.reference_doctype = ''SalesInvoice'' AND pe.docstatus = 1 AND pe.payment_type = ''Receive'' AND pe.posting_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-008', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-008", "kpi_name": "Customers Over Credit Limit", "kpi_module": "FINANCE", "sub_area": "Accounts Receivable (AR)", "is_active": true, "definition": "Number of customers with outstanding balances exceeding credit limit", "formula": "COUNT(Customer WHERE SUM(outstanding) > credit_limit)", "unit": "Customers", "direction": "Down", "target": "0", "frequency": "Daily", "owner_role": "Credit Controller", "source_doctypes": "Customer, SalesInvoice", "key_fields": "credit_limit, outstanding_amount", "platform_equivalent": "NetSuite Credit Limit; SAP FSCM Credit Mgmt", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_008", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT COUNT(*) FILTER (WHERE ar > credit_limit) AS value FROM (SELECT c.name, c.credit_limit, COALESCE((SELECT SUM(si.outstanding_amount * si.exchange_rate) FROM reporting.sales_invoice si WHERE si.customer = c.name AND si.docstatus = 1), 0) AS ar FROM reporting.customer c WHERE c.is_active AND COALESCE(c.credit_limit, 0) > 0) x"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-009', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-009", "kpi_name": "Credit Limit Utilization", "kpi_module": "FINANCE", "sub_area": "Accounts Receivable (AR)", "is_active": true, "definition": "Overall customer credit limit exposure", "formula": "SUM(outstanding) / SUM(credit_limit) x100", "unit": "%", "direction": "Range", "target": "≤ 80%", "frequency": "Weekly", "owner_role": "Credit Controller", "source_doctypes": "Customer, SalesInvoice", "key_fields": "credit_limit", "platform_equivalent": "SAP FSCM", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_009", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT ROUND(100.0 * (SUM(ar)) / NULLIF(SUM(credit_limit), 0), 2) AS value FROM (SELECT c.name, c.credit_limit, COALESCE((SELECT SUM(si.outstanding_amount * si.exchange_rate) FROM reporting.sales_invoice si WHERE si.customer = c.name AND si.docstatus = 1), 0) AS ar FROM reporting.customer c WHERE c.is_active AND COALESCE(c.credit_limit, 0) > 0) x"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-010', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-010", "kpi_name": "Credit Note Ratio", "kpi_module": "FINANCE", "sub_area": "Accounts Receivable (AR)", "is_active": true, "definition": "Sales credit notes issued compared to gross revenue", "formula": "SUM(SalesCreditNote.grand_total) / SUM(SalesInvoice.grand_total) x100", "unit": "%", "direction": "Down", "target": "≤ 2%", "frequency": "Monthly", "owner_role": "Sales Operations + AR", "source_doctypes": "SalesCreditNote, SalesInvoice", "key_fields": "grand_total, reason", "platform_equivalent": "NetSuite Credit Memo; SAP", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_010", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (SELECT SUM(base_grand_total) FROM reporting.sales_credit_note WHERE docstatus = 1 AND posting_date BETWEEN @Start AND @End) / NULLIF((SELECT SUM(base_grand_total) FROM reporting.sales_invoice WHERE docstatus = 1 AND posting_date BETWEEN @Start AND @End), 0), 2) AS value"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-011', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-011", "kpi_name": "Credit Notes by Reason", "kpi_module": "FINANCE", "sub_area": "Accounts Receivable (AR)", "is_active": true, "definition": "Breakdown of credit notes by reason (returns, discounts, price adjustments, cancellations)", "formula": "SUM(grand_total) GROUP BY reason", "unit": "IDR", "direction": "Down", "target": "—", "frequency": "Monthly", "owner_role": "Sales Operations", "source_doctypes": "SalesCreditNote", "key_fields": "reason", "platform_equivalent": "SAP Returns", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_011", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT COALESCE(reason, ''(blank)'') AS label, SUM(base_grand_total) AS value FROM reporting.sales_credit_note WHERE docstatus = 1 AND posting_date BETWEEN @Start AND @End GROUP BY 1 ORDER BY 2 DESC"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-012', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-012", "kpi_name": "Unapplied Customer Payments", "kpi_module": "FINANCE", "sub_area": "Accounts Receivable (AR)", "is_active": true, "definition": "Customer receipts not yet allocated to specific invoices", "formula": "SUM(PaymentEntry.unallocated_amount WHERE payment_type=''Receive'')", "unit": "IDR", "direction": "Down", "target": "Near 0", "frequency": "Weekly", "owner_role": "AR Lead", "source_doctypes": "PaymentEntry", "key_fields": "unallocated_amount, payment_type", "platform_equivalent": "NetSuite Unapplied Payments; SAP F-32", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_012", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT ROUND(COALESCE(SUM(unallocated_amount * exchange_rate), 0), 0) AS value FROM reporting.payment_entry WHERE docstatus = 1 AND payment_type = ''Receive'' AND unallocated_amount > 0"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-013', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-013", "kpi_name": "Payment Reconciliation Backlog", "kpi_module": "FINANCE", "sub_area": "Accounts Receivable (AR)", "is_active": true, "definition": "Number of unapplied payment entries pending reconciliation", "formula": "COUNT(PaymentEntry unallocated_amount > 0)", "unit": "Documents", "direction": "Down", "target": "0 at month end", "frequency": "Weekly", "owner_role": "AR Lead", "source_doctypes": "PaymentEntry, PaymentReconciliation", "key_fields": "unallocated_amount", "platform_equivalent": "SAP F-32 / NetSuite", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_013", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT COUNT(*) AS value FROM reporting.payment_entry WHERE docstatus = 1 AND payment_type IN (''Receive'',''Pay'') AND unallocated_amount > 0"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-014', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-014", "kpi_name": "Invoices Without Tax Invoice", "kpi_module": "FINANCE", "sub_area": "Accounts Receivable (AR)", "is_active": true, "definition": "Taxable sales invoices missing official tax invoice numbers", "formula": "COUNT(SalesInvoice vat_amount > 0 AND tax_invoice_no IS NULL)", "unit": "Invoices", "direction": "Down", "target": "0", "frequency": "Weekly", "owner_role": "Tax", "source_doctypes": "SalesInvoice, TaxInvoice", "key_fields": "tax_invoice_no, vat_amount", "platform_equivalent": "—", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_014", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT COUNT(*) AS value FROM reporting.sales_invoice WHERE docstatus = 1 AND vat_amount > 0 AND COALESCE(tax_invoice_no, '''') = '''' AND posting_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-015', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-015", "kpi_name": "Net Sales", "kpi_module": "FINANCE", "sub_area": "Accounts Receivable (AR)", "is_active": true, "definition": "Total sales revenue net of credit notes", "formula": "SUM(SalesInvoice.tax_base) − SUM(SalesCreditNote.tax_base)", "unit": "IDR", "direction": "Up", "target": "Per target", "frequency": "Monthly", "owner_role": "CFO", "source_doctypes": "SalesInvoice, SalesCreditNote", "key_fields": "tax_base", "platform_equivalent": "NetSuite / SAP / Workday", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_015", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(COALESCE((SELECT SUM(total * exchange_rate) FROM reporting.sales_invoice WHERE docstatus = 1 AND posting_date BETWEEN @Start AND @End), 0) - COALESCE((SELECT SUM(total * exchange_rate) FROM reporting.sales_credit_note WHERE docstatus = 1 AND posting_date BETWEEN @Start AND @End), 0), 0) AS value"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-016', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-016", "kpi_name": "Top 10 AR Concentration", "kpi_module": "FINANCE", "sub_area": "Accounts Receivable (AR)", "is_active": true, "definition": "Share of outstanding receivables held by the top 10 customers", "formula": "SUM(outstanding top 10 customers) / Total AR x100", "unit": "%", "direction": "Down", "target": "≤ 50%", "frequency": "Quarterly", "owner_role": "CFO", "source_doctypes": "SalesInvoice", "key_fields": "customer, outstanding_amount", "platform_equivalent": "NetSuite", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_016", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "WITH c AS (SELECT customer, SUM(outstanding_amount * exchange_rate) AS ar FROM reporting.sales_invoice WHERE docstatus = 1 AND outstanding_amount > 0 GROUP BY customer) SELECT ROUND(100.0 * (SELECT SUM(ar) FROM (SELECT ar FROM c ORDER BY ar DESC LIMIT 10) t) / NULLIF((SELECT SUM(ar) FROM c), 0), 2) AS value"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-017', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-017", "kpi_name": "Bad Debt Write-off Ratio", "kpi_module": "FINANCE", "sub_area": "Accounts Receivable (AR)", "is_active": true, "definition": "Uncollectible receivables written off compared to sales", "formula": "SUM(JournalEntry write-offs to bad debt accounts) / Sales x100", "unit": "%", "direction": "Down", "target": "≤ 0,5%", "frequency": "Quarterly", "owner_role": "Controller", "source_doctypes": "JournalEntry, JournalEntryLine", "key_fields": "account, debit", "platform_equivalent": "SAP / NetSuite", "implementation": "Built-in report", "builtin_report": "ProfitAndLossReport", "implementation_note": "Requires general ledger data (frogframe_gl_entries), which is not included in the reporting schema and cannot be used by widgets. Use the built-in ProfitAndLossReport."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-018', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-018", "kpi_name": "Invoices With Milestone Terms", "kpi_module": "FINANCE", "sub_area": "Accounts Receivable (AR)", "is_active": true, "definition": "Percentage of invoices utilizing payment schedules", "formula": "COUNT(payment_schedule >= 2 lines) / COUNT(SalesInvoice) x100", "unit": "%", "direction": "Range", "target": "—", "frequency": "Quarterly", "owner_role": "AR Lead", "source_doctypes": "SalesInvoice, InvoicePaymentSchedule", "key_fields": "payment_schedule", "platform_equivalent": "NetSuite Installments", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_018", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE (SELECT COUNT(*) FROM reporting.sales_invoice_payment_schedule s WHERE s.parent = si.name) >= 2)) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.sales_invoice si WHERE si.docstatus = 1 AND si.posting_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-019', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-019", "kpi_name": "Total Outstanding Payables", "kpi_module": "FINANCE", "sub_area": "Accounts Payable (AP)", "is_active": true, "definition": "Outstanding balance of unpaid purchase invoices", "formula": "SUM(PurchaseInvoice.outstanding_amount, docstatus=1) − SUM(PurchaseDebitNote.outstanding_amount)", "unit": "IDR", "direction": "Range", "target": "—", "frequency": "Daily", "owner_role": "AP Lead", "source_doctypes": "PurchaseInvoice, PurchaseDebitNote", "key_fields": "outstanding_amount", "platform_equivalent": "NetSuite A/P Aging; SAP FI-AP (FBL1N); Workday Supplier Accounts", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_019", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT (SELECT COALESCE(SUM(outstanding_amount * exchange_rate), 0) FROM reporting.purchase_invoice WHERE docstatus = 1) - (SELECT COALESCE(SUM(outstanding_amount * exchange_rate), 0) FROM reporting.purchase_debit_note WHERE docstatus = 1) AS value"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-020', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-020", "kpi_name": "DPO (Days Payable Outstanding)", "kpi_module": "FINANCE", "sub_area": "Accounts Payable (AP)", "is_active": true, "definition": "Average time taken to pay vendor bills in days", "formula": "(Outstanding payables / Purchases in period) × days in period", "unit": "Days", "direction": "Range", "target": "Per payment term (e.g. 30–60)", "frequency": "Monthly", "owner_role": "CFO", "source_doctypes": "PurchaseInvoice", "key_fields": "outstanding_amount, base_grand_total", "platform_equivalent": "NetSuite; SAP Fiori DPO", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_020", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND((SELECT COALESCE(SUM(outstanding_amount * exchange_rate), 0) FROM reporting.purchase_invoice WHERE docstatus = 1) / NULLIF((SELECT SUM(base_grand_total) FROM reporting.purchase_invoice WHERE docstatus = 1 AND posting_date BETWEEN @Start AND @End), 0) * (@End::date - @Start::date + 1), 1) AS value"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-021', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-021", "kpi_name": "On-time Payment Rate", "kpi_module": "FINANCE", "sub_area": "Accounts Payable (AP)", "is_active": true, "definition": "Vendor payments executed on or before invoice due date", "formula": "COUNT(PaymentEntryReference allocated <= due_date) / COUNT x100", "unit": "%", "direction": "Up", "target": "≥ 95%", "frequency": "Monthly", "owner_role": "AP Lead", "source_doctypes": "PaymentEntry, PaymentEntryReference", "key_fields": "posting_date, due_date", "platform_equivalent": "SAP / NetSuite / Workday", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_021", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE pe.posting_date <= COALESCE(r.due_date, pi.due_date))) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.payment_entry_references r JOIN reporting.payment_entry pe ON pe.name = r.parent JOIN reporting.purchase_invoice pi ON pi.name = r.reference_name WHERE r.reference_doctype = ''PurchaseInvoice'' AND pe.docstatus = 1 AND pe.payment_type = ''Pay'' AND pe.posting_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-022', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-022", "kpi_name": "Late Payment Amount", "kpi_module": "FINANCE", "sub_area": "Accounts Payable (AP)", "is_active": true, "definition": "Total monetary value of overdue vendor payables not on hold", "formula": "SUM(outstanding WHERE due_date < CURRENT_DATE AND on_hold=0)", "unit": "IDR", "direction": "Down", "target": "0", "frequency": "Weekly", "owner_role": "AP Lead", "source_doctypes": "PurchaseInvoice", "key_fields": "outstanding_amount, due_date, on_hold", "platform_equivalent": "SAP Fiori Overdue Payables", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_022", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT ROUND(COALESCE(SUM(outstanding_amount * exchange_rate), 0), 0) AS value FROM reporting.purchase_invoice WHERE docstatus = 1 AND outstanding_amount > 0 AND due_date < CURRENT_DATE AND NOT COALESCE(on_hold, false)"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-023', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-023", "kpi_name": "Invoices On Hold", "kpi_module": "FINANCE", "sub_area": "Accounts Payable (AP)", "is_active": true, "definition": "Vendor invoices with payment withheld on hold", "formula": "COUNT / SUM(outstanding WHERE on_hold=1)", "unit": "Invoices / IDR", "direction": "Down", "target": "—", "frequency": "Weekly", "owner_role": "AP Lead", "source_doctypes": "PurchaseInvoice", "key_fields": "on_hold", "platform_equivalent": "NetSuite Payment Hold; SAP Payment Block", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_023", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT ROUND(COALESCE(SUM(outstanding_amount * exchange_rate), 0), 0) AS value FROM reporting.purchase_invoice WHERE docstatus = 1 AND outstanding_amount > 0 AND on_hold"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-024', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-024", "kpi_name": "Invoice Processing Time", "kpi_module": "FINANCE", "sub_area": "Accounts Payable (AP)", "is_active": true, "definition": "Days from vendor bill date to invoice submission in system", "formula": "AVG(posting_date − bill_date)", "unit": "Days", "direction": "Down", "target": "≤ 3 days", "frequency": "Monthly", "owner_role": "AP Lead", "source_doctypes": "PurchaseInvoice", "key_fields": "bill_date, posting_date", "platform_equivalent": "NetSuite Bill Capture; SAP VIM", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_024", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(AVG(posting_date - bill_date), 1) AS value FROM reporting.purchase_invoice WHERE docstatus = 1 AND bill_date IS NOT NULL AND posting_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-025', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-025", "kpi_name": "PO-backed Invoice Rate", "kpi_module": "FINANCE", "sub_area": "Accounts Payable (AP)", "is_active": true, "definition": "Purchase invoices originating from purchase orders", "formula": "COUNT(purchase_order filled) / COUNT(PurchaseInvoice) x100", "unit": "%", "direction": "Up", "target": "≥ 90%", "frequency": "Monthly", "owner_role": "Procurement + AP", "source_doctypes": "PurchaseInvoice", "key_fields": "purchase_order", "platform_equivalent": "SAP; NetSuite", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_025", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE purchase_order IS NOT NULL)) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.purchase_invoice WHERE docstatus = 1 AND posting_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-026', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-026", "kpi_name": "3-Way Match Exception Rate", "kpi_module": "FINANCE", "sub_area": "Accounts Payable (AP)", "is_active": true, "definition": "Invoices with PO/GR/Invoice price or quantity discrepancies", "formula": "COUNT(invoices with qty/rate variance vs GoodsReceiptItem/PurchaseOrderItem) / COUNT x100", "unit": "%", "direction": "Down", "target": "≤ 5%", "frequency": "Monthly", "owner_role": "AP Lead", "source_doctypes": "PurchaseInvoice, PurchaseOrder, GoodsReceipt, FinanceSettings", "key_fields": "three_way_match, received_qty, rate", "platform_equivalent": "SAP MIRO; NetSuite 3-way match", "implementation": "Not available", "implementation_note": "Requires matching invoice lines to PO/GR lines, while PurchaseInvoiceItem does not store PO line references."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-027', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-027", "kpi_name": "Duplicate Bill Numbers", "kpi_module": "FINANCE", "sub_area": "Accounts Payable (AP)", "is_active": true, "definition": "Vendor invoices sharing duplicate external bill numbers", "formula": "COUNT(GROUP BY vendor, bill_no HAVING COUNT(*) > 1)", "unit": "Cases", "direction": "Down", "target": "0", "frequency": "Weekly", "owner_role": "AP Lead", "source_doctypes": "PurchaseInvoice, FinanceSettings", "key_fields": "bill_no, vendor, unique_bill_no_per_vendor", "platform_equivalent": "NetSuite Duplicate Detection; SAP", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_027", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT COUNT(*) AS value FROM (SELECT vendor, bill_no FROM reporting.purchase_invoice WHERE docstatus = 1 AND COALESCE(bill_no, '''') <> '''' GROUP BY 1, 2 HAVING COUNT(*) > 1) d"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-028', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-028", "kpi_name": "Debit Note Ratio", "kpi_module": "FINANCE", "sub_area": "Accounts Payable (AP)", "is_active": true, "definition": "Purchase debit notes issued compared to gross purchases", "formula": "SUM(PurchaseDebitNote.grand_total) / SUM(PurchaseInvoice.grand_total) x100", "unit": "%", "direction": "Range", "target": "—", "frequency": "Monthly", "owner_role": "Procurement", "source_doctypes": "PurchaseDebitNote, PurchaseInvoice", "key_fields": "grand_total, reason", "platform_equivalent": "SAP", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_028", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (SELECT SUM(base_grand_total) FROM reporting.purchase_debit_note WHERE docstatus = 1 AND posting_date BETWEEN @Start AND @End) / NULLIF((SELECT SUM(base_grand_total) FROM reporting.purchase_invoice WHERE docstatus = 1 AND posting_date BETWEEN @Start AND @End), 0), 2) AS value"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-029', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-029", "kpi_name": "Unapplied Vendor Payments", "kpi_module": "FINANCE", "sub_area": "Accounts Payable (AP)", "is_active": true, "definition": "Disbursements to vendors not yet allocated to invoices", "formula": "SUM(PaymentEntry.unallocated_amount WHERE payment_type=''Pay'')", "unit": "IDR", "direction": "Down", "target": "0", "frequency": "Weekly", "owner_role": "AP Lead", "source_doctypes": "PaymentEntry", "key_fields": "unallocated_amount", "platform_equivalent": "NetSuite Vendor Prepayment", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_029", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT ROUND(COALESCE(SUM(unallocated_amount * exchange_rate), 0), 0) AS value FROM reporting.payment_entry WHERE docstatus = 1 AND payment_type = ''Pay'' AND unallocated_amount > 0"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-030', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-030", "kpi_name": "Early Payment Discount Captured", "kpi_module": "FINANCE", "sub_area": "Accounts Payable (AP)", "is_active": true, "definition": "Early settlement supplier discounts realized vs available", "formula": "SUM(discounts captured) / SUM(discounts available per PaymentTermDetail) x100", "unit": "%", "direction": "Up", "target": "≥ 80%", "frequency": "Monthly", "owner_role": "Treasury", "source_doctypes": "PaymentEntryDeduction, PaymentTermDetail", "key_fields": "discount_percent, discount_days, amount", "platform_equivalent": "SAP; NetSuite", "implementation": "Not available", "implementation_note": "Requires calculating early payment discount windows per term (PaymentTermDetail) against payment dates; recommended to build as a custom report."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-031', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-031", "kpi_name": "Purchase Invoices Without Attachment", "kpi_module": "FINANCE", "sub_area": "Accounts Payable (AP)", "is_active": true, "definition": "Vendor bills missing digital scan or attachment", "formula": "COUNT(attachment IS NULL) / COUNT x100", "unit": "%", "direction": "Down", "target": "0%", "frequency": "Monthly", "owner_role": "AP Lead", "source_doctypes": "PurchaseInvoice", "key_fields": "attachment", "platform_equivalent": "SAP / NetSuite", "implementation": "Not available", "implementation_note": "Source fields are restricted in reporting schema (permLevel 1 or attachment), so it cannot be computed by a widget."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-032', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-032", "kpi_name": "Cash & Bank Balance", "kpi_module": "FINANCE", "sub_area": "Cash & Bank", "is_active": true, "definition": "Total book balance across all operational bank accounts", "formula": "SUM(GL balance of BankAccount.gl_account)", "unit": "IDR", "direction": "Range", "target": "≥ operational requirements", "frequency": "Daily", "owner_role": "Treasury", "source_doctypes": "BankAccount, GL entries", "key_fields": "gl_account", "platform_equivalent": "NetSuite Cash; SAP Cash Mgmt; Workday Banking", "implementation": "Built-in report", "builtin_report": "BalanceSheetReport", "implementation_note": "Requires general ledger data (frogframe_gl_entries), which is not included in the reporting schema and cannot be used by widgets. Use the built-in BalanceSheetReport."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-033', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-033", "kpi_name": "Cash Runway", "kpi_module": "FINANCE", "sub_area": "Cash & Bank", "is_active": true, "definition": "Estimated operational months remaining based on average burn", "formula": "Cash balance / Average monthly cash disbursements (PaymentEntry Pay)", "unit": "Months", "direction": "Up", "target": "≥ 6 months", "frequency": "Monthly", "owner_role": "CFO", "source_doctypes": "BankAccount, PaymentEntry", "key_fields": "paid_amount, payment_type", "platform_equivalent": "Workday Adaptive; NetSuite", "implementation": "Built-in report", "builtin_report": "BalanceSheetReport", "implementation_note": "Requires general ledger data (frogframe_gl_entries), which is not included in the reporting schema and cannot be used by widgets. Use the built-in BalanceSheetReport."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-034', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-034", "kpi_name": "Net Cash Flow", "kpi_module": "FINANCE", "sub_area": "Cash & Bank", "is_active": true, "definition": "Cash receipts minus cash disbursements across all payment entries", "formula": "SUM(paid_amount Receive) − SUM(paid_amount Pay)", "unit": "IDR", "direction": "Up", "target": "Positive", "frequency": "Monthly", "owner_role": "Treasury", "source_doctypes": "PaymentEntry", "key_fields": "payment_type, base_paid_amount", "platform_equivalent": "NetSuite / SAP", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_034", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT COALESCE(SUM(base_paid_amount) FILTER (WHERE payment_type = ''Receive''), 0) - COALESCE(SUM(base_paid_amount) FILTER (WHERE payment_type = ''Pay''), 0) AS value FROM reporting.payment_entry WHERE docstatus = 1 AND posting_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-035', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-035", "kpi_name": "Bank Reconciliation Timeliness", "kpi_module": "FINANCE", "sub_area": "Cash & Bank", "is_active": true, "definition": "Bank reconciliations completed within 3 working days post month-end", "formula": "COUNT(BankReconciliation docstatus=1 within 3 working days of period_end) / COUNT(Active BankAccounts) x100", "unit": "%", "direction": "Up", "target": "100%", "frequency": "Monthly", "owner_role": "Treasury", "source_doctypes": "BankReconciliation, BankAccount", "key_fields": "period_end, creation", "platform_equivalent": "SAP Bank Rec; NetSuite Bank Rec", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_035", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE EXISTS (SELECT 1 FROM reporting.bank_reconciliation r WHERE r.bank_account = b.name AND r.docstatus = 1 AND r.period_end = (date_trunc(''month'', CURRENT_DATE) - interval ''1 day'')::date AND r.created::date <= (date_trunc(''month'', CURRENT_DATE) - interval ''1 day'')::date + 5))) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.bank_account b WHERE b.is_active"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-036', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-036", "kpi_name": "Bank Reconciliation Difference", "kpi_module": "FINANCE", "sub_area": "Cash & Bank", "is_active": true, "definition": "Total unexplained bank reconciliation variance", "formula": "SUM(ABS(difference))", "unit": "IDR", "direction": "Down", "target": "0", "frequency": "Monthly", "owner_role": "Treasury", "source_doctypes": "BankReconciliation", "key_fields": "difference", "platform_equivalent": "SAP / NetSuite", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_036", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT COALESCE(SUM(ABS(difference)), 0) AS value FROM reporting.bank_reconciliation WHERE docstatus = 1 AND period_end BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-037', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-037", "kpi_name": "Uncleared Items", "kpi_module": "FINANCE", "sub_area": "Cash & Bank", "is_active": true, "definition": "Book transactions not yet cleared on bank statements", "formula": "SUM(total_uncleared); COUNT(BankReconciliationItem is_cleared=0)", "unit": "IDR / item", "direction": "Down", "target": "—", "frequency": "Monthly", "owner_role": "Treasury", "source_doctypes": "BankReconciliation, BankReconciliationItem", "key_fields": "total_uncleared, is_cleared", "platform_equivalent": "SAP", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_037", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT COALESCE(SUM(i.uncleared_amount), 0) AS value FROM reporting.bank_reconciliation_items i JOIN reporting.bank_reconciliation r ON r.name = i.parent WHERE r.docstatus = 1 AND NOT COALESCE(i.is_cleared, false) AND r.period_end = (SELECT MAX(period_end) FROM reporting.bank_reconciliation WHERE docstatus = 1)"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-038', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-038", "kpi_name": "Aged Uncleared Items > 30 Days", "kpi_module": "FINANCE", "sub_area": "Cash & Bank", "is_active": true, "definition": "Uncleared bank reconciliation items outstanding > 30 days", "formula": "COUNT(is_cleared=0 AND period_end − posting_date > 30)", "unit": "Items", "direction": "Down", "target": "0", "frequency": "Monthly", "owner_role": "Treasury", "source_doctypes": "BankReconciliationItem", "key_fields": "posting_date, is_cleared", "platform_equivalent": "SAP", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_038", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT COUNT(*) AS value FROM reporting.bank_reconciliation_items i JOIN reporting.bank_reconciliation r ON r.name = i.parent WHERE r.docstatus = 1 AND NOT COALESCE(i.is_cleared, false) AND r.period_end - i.posting_date > 30 AND r.period_end = (SELECT MAX(period_end) FROM reporting.bank_reconciliation WHERE docstatus = 1)"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-039', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-039", "kpi_name": "Bank Statement Auto-match Rate", "kpi_module": "FINANCE", "sub_area": "Cash & Bank", "is_active": true, "definition": "Bank statement lines matched automatically by reconciliation rules", "formula": "COUNT(BankStatementLine match_status=''Matched'') / COUNT(lines excluding ''Ignored'') x100", "unit": "%", "direction": "Up", "target": "≥ 85%", "frequency": "Monthly", "owner_role": "Treasury", "source_doctypes": "BankStatementLine", "key_fields": "match_status", "platform_equivalent": "NetSuite Auto-match; SAP Intelligent Cash Application", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_039", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE l.match_status = ''Matched'')) / NULLIF(COUNT(*) FILTER (WHERE l.match_status <> ''Ignored''), 0), 2) AS value FROM reporting.bank_statement_lines l JOIN reporting.bank_statement s ON s.name = l.parent WHERE s.docstatus IN (0, 1) AND l.transaction_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-040', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-040", "kpi_name": "Unmatched Bank Lines", "kpi_module": "FINANCE", "sub_area": "Cash & Bank", "is_active": true, "definition": "Bank statement transaction lines pending manual reconciliation", "formula": "COUNT(match_status=''Unmatched'')", "unit": "Lines", "direction": "Down", "target": "0 at close", "frequency": "Weekly", "owner_role": "Treasury", "source_doctypes": "BankStatementLine", "key_fields": "match_status", "platform_equivalent": "NetSuite / SAP", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_040", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT COUNT(*) AS value FROM reporting.bank_statement_lines l JOIN reporting.bank_statement s ON s.name = l.parent WHERE s.docstatus IN (0, 1) AND l.match_status = ''Unmatched''"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-041', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-041", "kpi_name": "Statement Balance Integrity Check", "kpi_module": "FINANCE", "sub_area": "Cash & Bank", "is_active": true, "definition": "Bank statements where calculated closing does not match stated closing", "formula": "COUNT(BankStatement computed_closing != closing_balance)", "unit": "Statements", "direction": "Down", "target": "0", "frequency": "Monthly", "owner_role": "Treasury", "source_doctypes": "BankStatement", "key_fields": "computed_closing, closing_balance", "platform_equivalent": "SAP", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_041", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT COUNT(*) AS value FROM reporting.bank_statement WHERE docstatus IN (0, 1) AND ABS(COALESCE(computed_closing, 0) - COALESCE(closing_balance, 0)) > 0.005"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-042', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-042", "kpi_name": "Payment Run Efficiency", "kpi_module": "FINANCE", "sub_area": "Cash & Bank", "is_active": true, "definition": "Number of payment entries processed per batch payment run", "formula": "SUM(payments_created) / COUNT(PaymentRun)", "unit": "Payments", "direction": "Up", "target": "—", "frequency": "Monthly", "owner_role": "Treasury", "source_doctypes": "PaymentRun", "key_fields": "payments_created, party_count", "platform_equivalent": "SAP F110; NetSuite Bill Payment Batch", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_042", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(AVG(payments_created), 1) AS value FROM reporting.payment_run WHERE docstatus = 1 AND posting_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-043', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-043", "kpi_name": "Payment Run Coverage", "kpi_module": "FINANCE", "sub_area": "Cash & Bank", "is_active": true, "definition": "Due supplier payables successfully included in payment runs", "formula": "SUM(PaymentRun.total_amount) / SUM(due payables <= due_until) x100", "unit": "%", "direction": "Up", "target": "≥ 95%", "frequency": "Weekly", "owner_role": "Treasury", "source_doctypes": "PaymentRun, PaymentRunItem, PurchaseInvoice", "key_fields": "total_amount, due_until", "platform_equivalent": "SAP F110", "implementation": "Built-in report", "builtin_report": "PayableAgingReport", "implementation_note": "Requires a list of due bills at the time of payment run creation (snapshot). Use the built-in PayableAgingReport."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-044', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-044", "kpi_name": "Vendors Without Bank Account", "kpi_module": "FINANCE", "sub_area": "Cash & Bank", "is_active": true, "definition": "Active suppliers lacking electronic banking payment details", "formula": "COUNT(Vendor is_active=1 AND bank_accounts is empty)", "unit": "Vendors", "direction": "Down", "target": "0", "frequency": "Monthly", "owner_role": "AP Lead", "source_doctypes": "Vendor, PartyBankAccount", "key_fields": "bank_accounts", "platform_equivalent": "SAP Vendor Master; NetSuite", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_044", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT COUNT(*) AS value FROM reporting.vendor v WHERE v.is_active AND NOT EXISTS (SELECT 1 FROM reporting.vendor_bank_accounts b WHERE b.parent = v.name)"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-045', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-045", "kpi_name": "FX Exposure", "kpi_module": "FINANCE", "sub_area": "Cash & Bank", "is_active": true, "definition": "Total outstanding foreign currency receivable and payable exposure", "formula": "SUM(outstanding_amount × exchange_rate WHERE currency != base_currency)", "unit": "IDR", "direction": "Range", "target": "Per hedging policy", "frequency": "Monthly", "owner_role": "Treasury", "source_doctypes": "SalesInvoice, PurchaseInvoice, Company", "key_fields": "currency, exchange_rate", "platform_equivalent": "NetSuite Multi-currency; SAP", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_045", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT ROUND(COALESCE((SELECT SUM(si.outstanding_amount * si.exchange_rate) FROM reporting.sales_invoice si JOIN reporting.company c ON c.name = si.company WHERE si.docstatus = 1 AND si.currency <> c.base_currency), 0) + COALESCE((SELECT SUM(pi.outstanding_amount * pi.exchange_rate) FROM reporting.purchase_invoice pi JOIN reporting.company c ON c.name = pi.company WHERE pi.docstatus = 1 AND pi.currency <> c.base_currency), 0), 0) AS value"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-046', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-046", "kpi_name": "Missing Daily Exchange Rates", "kpi_module": "FINANCE", "sub_area": "Cash & Bank", "is_active": true, "definition": "Active currency pairs missing foreign exchange rate for today", "formula": "COUNT(active currency pairs without CurrencyExchangeRate rate_date=CURRENT_DATE)", "unit": "Pairs", "direction": "Down", "target": "0", "frequency": "Daily", "owner_role": "Treasury", "source_doctypes": "CurrencyExchangeRate", "key_fields": "rate_date, from_currency, to_currency", "platform_equivalent": "SAP Exchange Rate (OB08); NetSuite FX Rates", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_046", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT COUNT(*) AS value FROM reporting.currency cur WHERE cur.is_active AND cur.name NOT IN (SELECT base_currency FROM reporting.company WHERE base_currency IS NOT NULL) AND NOT EXISTS (SELECT 1 FROM reporting.currency_exchange_rate r WHERE r.from_currency = cur.name AND r.rate_date = CURRENT_DATE)"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-047', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-047", "kpi_name": "Total Expense Claims", "kpi_module": "FINANCE", "sub_area": "Expense & Advance", "is_active": true, "definition": "Total employee business expense reimbursements claimed", "formula": "SUM(ExpenseClaim.total_claimed, approved)", "unit": "IDR", "direction": "Range", "target": "Within budget", "frequency": "Monthly", "owner_role": "Finance Operations", "source_doctypes": "ExpenseClaim", "key_fields": "total_claimed", "platform_equivalent": "Workday Expenses; SAP Concur; NetSuite Expense Reports", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_047", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT COALESCE(SUM(c.total_claimed), 0) AS value FROM reporting.expense_claim c WHERE c.workflow_state = ''Approved'' AND c.posting_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-048', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-048", "kpi_name": "Expense Claim per Employee", "kpi_module": "FINANCE", "sub_area": "Expense & Advance", "is_active": true, "definition": "Average business reimbursement expense claimed per employee", "formula": "SUM(total_claimed) / headcount", "unit": "IDR", "direction": "Range", "target": "—", "frequency": "Monthly", "owner_role": "Finance Operations", "source_doctypes": "ExpenseClaim, Employee", "key_fields": "total_claimed", "platform_equivalent": "Concur / Workday", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_048", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND((SELECT SUM(c.total_claimed) FROM reporting.expense_claim c WHERE c.workflow_state = ''Approved'' AND c.posting_date BETWEEN @Start AND @End) / NULLIF((SELECT COUNT(*) FROM reporting.employee WHERE status = ''Active''), 0), 0) AS value"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-049', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-049", "kpi_name": "Expense Claim Cycle Time", "kpi_module": "FINANCE", "sub_area": "Expense & Advance", "is_active": true, "definition": "Average days from claim submission date to payment disbursement", "formula": "AVG(PaymentEntry.posting_date − ExpenseClaim.posting_date)", "unit": "Days", "direction": "Down", "target": "≤ 7 days", "frequency": "Monthly", "owner_role": "Finance Operations", "source_doctypes": "ExpenseClaim, PaymentEntry", "key_fields": "posting_date, payment_status", "platform_equivalent": "Concur / Workday", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_049", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(AVG(pe.posting_date - c.posting_date), 1) AS value FROM reporting.payment_entry_references r JOIN reporting.payment_entry pe ON pe.name = r.parent JOIN reporting.expense_claim c ON c.name = r.reference_name WHERE r.reference_doctype = ''ExpenseClaim'' AND pe.docstatus = 1 AND pe.posting_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-050', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-050", "kpi_name": "Expense Approval Turnaround", "kpi_module": "FINANCE", "sub_area": "Expense & Advance", "is_active": true, "definition": "Average workflow approval turnaround time for expense claims", "formula": "AVG(workflow transition hours to Approved)", "unit": "Hours", "direction": "Down", "target": "≤ 48 hours", "frequency": "Monthly", "owner_role": "Expense Approver", "source_doctypes": "ExpenseClaim", "key_fields": "workflow_state", "platform_equivalent": "Workday BP; Concur", "implementation": "Not available", "implementation_note": "Requires workflow transition timestamps per document (version/audit trail), which are not yet exposed to the reporting schema."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-051', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-051", "kpi_name": "Expense Rejection Rate", "kpi_module": "FINANCE", "sub_area": "Expense & Advance", "is_active": true, "definition": "Percentage of employee expense claims rejected", "formula": "COUNT(state=''Rejected'') / COUNT(Submitted) x100", "unit": "%", "direction": "Down", "target": "≤ 5%", "frequency": "Monthly", "owner_role": "Finance Operations", "source_doctypes": "ExpenseClaim", "key_fields": "workflow_state", "platform_equivalent": "Concur", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_051", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE workflow_state = ''Rejected'')) / NULLIF(COUNT(*) FILTER (WHERE workflow_state IN (''Approved'',''Rejected'')), 0), 2) AS value FROM reporting.expense_claim WHERE posting_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-052', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-052", "kpi_name": "Receipt Compliance", "kpi_module": "FINANCE", "sub_area": "Expense & Advance", "is_active": true, "definition": "Percentage of mandatory-receipt expense lines with receipts attached", "formula": "COUNT(ExpenseClaimItem receipt attached WHERE type.requires_receipt=1) / COUNT(Mandatory) x100", "unit": "%", "direction": "Up", "target": "100%", "frequency": "Monthly", "owner_role": "Finance Operations", "source_doctypes": "ExpenseClaimItem, ExpenseClaimType", "key_fields": "receipt, requires_receipt", "platform_equivalent": "Concur Receipt Audit", "implementation": "Not available", "implementation_note": "Source fields are restricted in reporting schema (permLevel 1 or attachment), so it cannot be computed by a widget."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-053', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-053", "kpi_name": "Policy Breach (Over Limit)", "kpi_module": "FINANCE", "sub_area": "Expense & Advance", "is_active": true, "definition": "Claim items submitted exceeding maximum policy allowance", "formula": "COUNT(amount > ExpenseClaimType.max_amount_per_item)", "unit": "Items", "direction": "Down", "target": "0", "frequency": "Monthly", "owner_role": "Finance Operations", "source_doctypes": "ExpenseClaimItem, ExpenseClaimType", "key_fields": "amount, max_amount_per_item", "platform_equivalent": "Concur Audit Rules", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_053", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT COUNT(*) AS value FROM reporting.expense_claim_items i JOIN reporting.expense_claim c ON c.name = i.parent JOIN reporting.expense_claim_type t ON t.name = i.expense_type WHERE c.workflow_state NOT IN (''Draft'',''Cancelled'') AND COALESCE(t.max_amount_per_item, 0) > 0 AND i.amount > t.max_amount_per_item AND c.posting_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-054', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-054", "kpi_name": "Entertainment Expense Spend", "kpi_module": "FINANCE", "sub_area": "Expense & Advance", "is_active": true, "definition": "Total entertainment claims incurred requiring fiscal nominative reporting", "formula": "SUM(amount WHERE type.is_entertainment=1)", "unit": "IDR", "direction": "Down", "target": "Within budget", "frequency": "Monthly", "owner_role": "Tax", "source_doctypes": "ExpenseClaimItem, ExpenseClaimType", "key_fields": "is_entertainment", "platform_equivalent": "Concur", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_054", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT COALESCE(SUM(i.amount), 0) AS value FROM reporting.expense_claim_items i JOIN reporting.expense_claim c ON c.name = i.parent JOIN reporting.expense_claim_type t ON t.name = i.expense_type WHERE c.workflow_state = ''Approved'' AND t.is_entertainment AND c.posting_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-055', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-055", "kpi_name": "Expenses by Project", "kpi_module": "FINANCE", "sub_area": "Expense & Advance", "is_active": true, "definition": "Employee reimbursement costs allocated to specific projects", "formula": "SUM(total_claimed) GROUP BY project", "unit": "IDR", "direction": "Range", "target": "Per project estimate", "frequency": "Monthly", "owner_role": "Project Controller", "source_doctypes": "ExpenseClaim", "key_fields": "project", "platform_equivalent": "NetSuite Projects; SAP PS", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_055", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT COALESCE(c.project, ''(no project)'') AS label, SUM(c.total_claimed) AS value FROM reporting.expense_claim c WHERE c.workflow_state = ''Approved'' AND c.posting_date BETWEEN @Start AND @End GROUP BY 1 ORDER BY 2 DESC LIMIT 15"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-056', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-056", "kpi_name": "Outstanding Employee Advances", "kpi_module": "FINANCE", "sub_area": "Expense & Advance", "is_active": true, "definition": "Total employee advances outstanding pending settlement", "formula": "SUM(paid_amount − settled_amount − returned_amount) WHERE advance_status != ''Completed''", "unit": "IDR", "direction": "Down", "target": "—", "frequency": "Weekly", "owner_role": "Finance Operations", "source_doctypes": "EmployeeAdvance", "key_fields": "paid_amount, settled_amount, returned_amount", "platform_equivalent": "SAP Travel; NetSuite", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_056", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT COALESCE(SUM(COALESCE(paid_amount, 0) - COALESCE(settled_amount, 0) - COALESCE(returned_amount, 0)), 0) AS value FROM reporting.employee_advance WHERE docstatus = 1 AND advance_status <> ''Completed''"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-057', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-057", "kpi_name": "Overdue Advance Settlements", "kpi_module": "FINANCE", "sub_area": "Expense & Advance", "is_active": true, "definition": "Employee advances past settlement due date not yet resolved", "formula": "COUNT(settle_by_date < CURRENT_DATE AND advance_status IN (''Paid'',''Partly Settled''))", "unit": "Advances", "direction": "Down", "target": "0", "frequency": "Weekly", "owner_role": "Finance Operations", "source_doctypes": "EmployeeAdvance", "key_fields": "settle_by_date, advance_status", "platform_equivalent": "SAP", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_057", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT COUNT(*) AS value FROM reporting.employee_advance WHERE docstatus = 1 AND advance_status IN (''Paid'',''Partly Settled'') AND settle_by_date < CURRENT_DATE"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-058', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-058", "kpi_name": "Advance Settlement Ratio", "kpi_module": "FINANCE", "sub_area": "Expense & Advance", "is_active": true, "definition": "Proportion of employee advances settled via expense claims", "formula": "SUM(settled_amount) / SUM(paid_amount) x100", "unit": "%", "direction": "Up", "target": "≥ 90%", "frequency": "Monthly", "owner_role": "Finance Operations", "source_doctypes": "EmployeeAdvance", "key_fields": "settled_amount, paid_amount", "platform_equivalent": "SAP", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_058", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (SUM(COALESCE(settled_amount, 0) + COALESCE(returned_amount, 0))) / NULLIF(SUM(paid_amount), 0), 2) AS value FROM reporting.employee_advance WHERE docstatus = 1 AND paid_amount > 0 AND posting_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-059', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-059", "kpi_name": "Unpaid Approved Claims", "kpi_module": "FINANCE", "sub_area": "Expense & Advance", "is_active": true, "definition": "Approved expense reimbursements awaiting payment disbursement", "formula": "SUM(net_payable WHERE payment_status IN (''Unpaid'',''Partly Paid''))", "unit": "IDR", "direction": "Down", "target": "0 > 7 days", "frequency": "Weekly", "owner_role": "Treasury", "source_doctypes": "ExpenseClaim", "key_fields": "net_payable, payment_status", "platform_equivalent": "Concur / Workday", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_059", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT COALESCE(SUM(net_payable), 0) AS value FROM reporting.expense_claim WHERE workflow_state = ''Approved'' AND payment_status IN (''Unpaid'',''Partly Paid'')"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-060', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-060", "kpi_name": "Output VAT (PPN Keluaran)", "kpi_module": "FINANCE", "sub_area": "Tax", "is_active": true, "definition": "Total output value-added tax collected on sales", "formula": "SUM(SalesInvoice.vat_amount) − SUM(SalesCreditNote.vat_amount)", "unit": "IDR", "direction": "Range", "target": "—", "frequency": "Monthly", "owner_role": "Tax", "source_doctypes": "SalesInvoice, SalesCreditNote, TaxInvoice", "key_fields": "vat_amount", "platform_equivalent": "SAP Tax Reporting; NetSuite SuiteTax", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_060", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT COALESCE(SUM(vat_amount), 0) AS value FROM reporting.tax_invoice WHERE docstatus = 1 AND status NOT IN (''Cancelled'',''Replaced'') AND tax_invoice_date BETWEEN @Start AND @End AND direction = ''Output''"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-061', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-061", "kpi_name": "Input VAT (PPN Masukan)", "kpi_module": "FINANCE", "sub_area": "Tax", "is_active": true, "definition": "Total creditable input value-added tax paid on purchases", "formula": "SUM(PurchaseInvoice.vat_amount) − SUM(PurchaseDebitNote.vat_amount)", "unit": "IDR", "direction": "Range", "target": "—", "frequency": "Monthly", "owner_role": "Tax", "source_doctypes": "PurchaseInvoice, PurchaseDebitNote, TaxInvoice", "key_fields": "vat_amount, credited_period", "platform_equivalent": "SAP / NetSuite", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_061", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT COALESCE(SUM(vat_amount), 0) AS value FROM reporting.tax_invoice WHERE docstatus = 1 AND status NOT IN (''Cancelled'',''Replaced'') AND tax_invoice_date BETWEEN @Start AND @End AND direction = ''Input''"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-062', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-062", "kpi_name": "VAT Payable / Overpaid", "kpi_module": "FINANCE", "sub_area": "Tax", "is_active": true, "definition": "Net VAT balance payable to tax authority or refundable", "formula": "Output VAT − Credited Input VAT", "unit": "IDR", "direction": "Range", "target": "—", "frequency": "Monthly", "owner_role": "Tax", "source_doctypes": "TaxInvoice (VatRegisterReport)", "key_fields": "direction, vat_amount", "platform_equivalent": "SAP / NetSuite", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_062", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT COALESCE(SUM(vat_amount) FILTER (WHERE direction = ''Output''), 0) - COALESCE(SUM(vat_amount) FILTER (WHERE direction = ''Input''), 0) AS value FROM reporting.tax_invoice WHERE docstatus = 1 AND status NOT IN (''Cancelled'',''Replaced'') AND tax_invoice_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-063', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-063", "kpi_name": "Tax Invoice Approval Rate", "kpi_module": "FINANCE", "sub_area": "Tax", "is_active": true, "definition": "Tax invoices officially validated and approved by tax authority (DJP)", "formula": "COUNT(TaxInvoice status=''Approved'') / COUNT(status != ''Cancelled'') x100", "unit": "%", "direction": "Up", "target": "100%", "frequency": "Monthly", "owner_role": "Tax", "source_doctypes": "TaxInvoice", "key_fields": "status", "platform_equivalent": "e-Faktur/Coretax integration", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_063", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE status = ''Approved'')) / NULLIF(COUNT(*) FILTER (WHERE status <> ''Cancelled''), 0), 2) AS value FROM reporting.tax_invoice WHERE docstatus IN (0, 1) AND direction = ''Output'' AND tax_invoice_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-064', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-064", "kpi_name": "Tax Invoices Pending Upload", "kpi_module": "FINANCE", "sub_area": "Tax", "is_active": true, "definition": "Draft tax invoices pending submission or export to e-Faktur", "formula": "COUNT(TaxInvoice status=''Draft'')", "unit": "Tax invoices", "direction": "Down", "target": "0 before filing deadline", "frequency": "Weekly", "owner_role": "Tax", "source_doctypes": "TaxInvoice", "key_fields": "status", "platform_equivalent": "—", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_064", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT COUNT(*) AS value FROM reporting.tax_invoice WHERE docstatus IN (0, 1) AND direction = ''Output'' AND status = ''Draft''"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-065', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-065", "kpi_name": "Replacement Tax Invoice Rate", "kpi_module": "FINANCE", "sub_area": "Tax", "is_active": true, "definition": "Percentage of tax invoices requiring replacement (e-Faktur pengganti)", "formula": "COUNT(status=''Replaced'') / COUNT(TaxInvoice) x100", "unit": "%", "direction": "Down", "target": "≤ 1%", "frequency": "Monthly", "owner_role": "Tax", "source_doctypes": "TaxInvoice", "key_fields": "status, replaces", "platform_equivalent": "—", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_065", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE replaces IS NOT NULL)) / NULLIF(COUNT(*) FILTER (WHERE status <> ''Cancelled''), 0), 2) AS value FROM reporting.tax_invoice WHERE docstatus IN (0, 1) AND direction = ''Output'' AND tax_invoice_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-066', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-066", "kpi_name": "Uncredited Input Tax Invoices", "kpi_module": "FINANCE", "sub_area": "Tax", "is_active": true, "definition": "Input tax invoices not yet claimed in a VAT tax return period", "formula": "COUNT(direction=''Input'' AND credited_period IS NULL)", "unit": "Tax invoices", "direction": "Down", "target": "0 within 3 months", "frequency": "Monthly", "owner_role": "Tax", "source_doctypes": "TaxInvoice", "key_fields": "direction, credited_period", "platform_equivalent": "—", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_066", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT COUNT(*) AS value FROM reporting.tax_invoice WHERE docstatus = 1 AND direction = ''Input'' AND status NOT IN (''Cancelled'',''Replaced'') AND COALESCE(credited_period, '''') = ''''"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-067', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-067", "kpi_name": "Withholding Tax (PPh 23) Payable", "kpi_module": "FINANCE", "sub_area": "Tax", "is_active": true, "definition": "Total income tax withheld from vendor payments (PPh 23/4(2))", "formula": "SUM(PurchaseInvoice.wht_amount)", "unit": "IDR", "direction": "Range", "target": "—", "frequency": "Monthly", "owner_role": "Tax", "source_doctypes": "PurchaseInvoice, WithholdingCertificate", "key_fields": "wht_amount", "platform_equivalent": "SAP Extended WHT; NetSuite", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_067", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(COALESCE(SUM(wht_amount * exchange_rate), 0), 0) AS value FROM reporting.purchase_invoice WHERE docstatus = 1 AND posting_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-068', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-068", "kpi_name": "Withholding Certificates Issued", "kpi_module": "FINANCE", "sub_area": "Tax", "is_active": true, "definition": "Purchase invoices with tax withholding where tax certificate was issued", "formula": "COUNT(WithholdingCertificate direction=''We withhold'') / COUNT(PurchaseInvoice wht_amount > 0) x100", "unit": "%", "direction": "Up", "target": "100%", "frequency": "Monthly", "owner_role": "Tax", "source_doctypes": "WithholdingCertificate, PurchaseInvoice", "key_fields": "direction, reference_name", "platform_equivalent": "SAP", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_068", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE EXISTS (SELECT 1 FROM reporting.withholding_certificate w WHERE w.direction = ''We withhold'' AND w.reference_doctype = ''PurchaseInvoice'' AND w.reference_name = pi.name AND w.docstatus = 1))) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.purchase_invoice pi WHERE pi.docstatus = 1 AND pi.wht_amount > 0 AND pi.posting_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-069', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-069", "kpi_name": "Customer Withholding Certificates Received", "kpi_module": "FINANCE", "sub_area": "Tax", "is_active": true, "definition": "Deductions withheld by customers with verified certificates collected", "formula": "COUNT(WithholdingCertificate direction=''Withheld by counterparty'') / COUNT(PaymentEntryDeduction WHT) x100", "unit": "%", "direction": "Up", "target": "100%", "frequency": "Monthly", "owner_role": "Tax", "source_doctypes": "WithholdingCertificate, PaymentEntryDeduction", "key_fields": "direction, deduction_type", "platform_equivalent": "SAP", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_069", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE EXISTS (SELECT 1 FROM reporting.withholding_certificate w WHERE w.direction = ''Withheld by counterparty'' AND w.party = pe.party AND w.docstatus = 1 AND w.reference_name IN (SELECT r.reference_name FROM reporting.payment_entry_references r WHERE r.parent = pe.name)))) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.payment_entry pe WHERE pe.docstatus = 1 AND pe.payment_type = ''Receive'' AND pe.posting_date BETWEEN @Start AND @End AND EXISTS (SELECT 1 FROM reporting.payment_entry_deductions d WHERE d.parent = pe.name AND d.deduction_type = ''Tax withheld by counterparty'')"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-070', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-070", "kpi_name": "Effective Tax Rate", "kpi_module": "FINANCE", "sub_area": "Tax", "is_active": true, "definition": "Corporate income tax expense compared to pre-tax accounting profit", "formula": "Corporate income tax expense / Profit before tax x100 (ProfitAndLossReport)", "unit": "%", "direction": "Range", "target": "≈ Corporate tax rate", "frequency": "Annual", "owner_role": "Tax", "source_doctypes": "JournalEntry, Account", "key_fields": "account, tax_report_code", "platform_equivalent": "SAP / NetSuite", "implementation": "Built-in report", "builtin_report": "ProfitAndLossReport", "implementation_note": "Requires general ledger data (frogframe_gl_entries), which is not included in the reporting schema and cannot be used by widgets. Use the built-in ProfitAndLossReport."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-071', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-071", "kpi_name": "Taxable Counterparties Without Tax ID", "kpi_module": "FINANCE", "sub_area": "Tax", "is_active": true, "definition": "Taxable vendor or customer master records missing valid tax ID (NPWP)", "formula": "COUNT(is_pkp=1 AND tax_id IS NULL)", "unit": "Records", "direction": "Down", "target": "0", "frequency": "Monthly", "owner_role": "Tax", "source_doctypes": "Customer, Vendor", "key_fields": "is_pkp, tax_id, nitku", "platform_equivalent": "SAP BP; NetSuite", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_071", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT (SELECT COUNT(*) FROM reporting.customer WHERE is_active AND is_pkp AND COALESCE(tax_id, '''') = '''') + (SELECT COUNT(*) FROM reporting.vendor WHERE is_active AND is_pkp AND COALESCE(tax_id, '''') = '''') AS value"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-072', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-072", "kpi_name": "Fixed Assets Net Book Value", "kpi_module": "FINANCE", "sub_area": "Fixed Assets", "is_active": true, "definition": "Gross asset acquisition cost minus cumulative depreciation", "formula": "SUM(gross_purchase_amount − opening_accumulated_depreciation − SUM(posted depreciation))", "unit": "IDR", "direction": "Range", "target": "—", "frequency": "Monthly", "owner_role": "Asset Accountant", "source_doctypes": "Asset, AssetDepreciationSchedule", "key_fields": "gross_purchase_amount, accumulated_depreciation", "platform_equivalent": "SAP FI-AA; NetSuite Fixed Assets; Workday Assets", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_072", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT COALESCE(SUM(a.gross_purchase_amount - COALESCE(a.opening_accumulated_depreciation, 0) - COALESCE((SELECT SUM(s.depreciation_amount) FROM reporting.asset_schedule s WHERE s.parent = a.name AND s.is_posted), 0)), 0) AS value FROM reporting.asset a WHERE a.docstatus = 1 AND a.status IN (''Active'',''Fully Depreciated'')"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-073', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-073", "kpi_name": "Period Depreciation Expense", "kpi_module": "FINANCE", "sub_area": "Fixed Assets", "is_active": true, "definition": "Total depreciation posted to general ledger for the period", "formula": "SUM(DepreciationRun.total_depreciation)", "unit": "IDR", "direction": "Range", "target": "On schedule", "frequency": "Monthly", "owner_role": "Asset Accountant", "source_doctypes": "DepreciationRun", "key_fields": "total_depreciation, accounting_period", "platform_equivalent": "SAP AFAB; NetSuite", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_073", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT COALESCE(SUM(total_depreciation), 0) AS value FROM reporting.depreciation_run WHERE docstatus = 1 AND posting_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-074', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-074", "kpi_name": "Depreciation Run Completion", "kpi_module": "FINANCE", "sub_area": "Fixed Assets", "is_active": true, "definition": "Percentage of accounting periods with completed monthly depreciation runs", "formula": "COUNT(DepreciationRun per accounting_period) / COUNT(AccountingPeriod) x100", "unit": "%", "direction": "Up", "target": "100% before close", "frequency": "Monthly", "owner_role": "Asset Accountant", "source_doctypes": "DepreciationRun, AccountingPeriod", "key_fields": "accounting_period", "platform_equivalent": "SAP AFAB", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_074", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE EXISTS (SELECT 1 FROM reporting.depreciation_run d WHERE d.accounting_period = p.name AND d.docstatus = 1))) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.accounting_period p WHERE p.end_date BETWEEN @Start AND LEAST(@End, CURRENT_DATE)"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-075', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-075", "kpi_name": "Unposted Depreciation Schedules", "kpi_module": "FINANCE", "sub_area": "Fixed Assets", "is_active": true, "definition": "Asset depreciation schedule rows past due date not yet posted", "formula": "COUNT(AssetDepreciationSchedule schedule_date <= CURRENT_DATE AND is_posted=0)", "unit": "Lines", "direction": "Down", "target": "0", "frequency": "Monthly", "owner_role": "Asset Accountant", "source_doctypes": "AssetDepreciationSchedule", "key_fields": "schedule_date, is_posted", "platform_equivalent": "SAP", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_075", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT COUNT(*) AS value FROM reporting.asset_schedule s JOIN reporting.asset a ON a.name = s.parent WHERE a.docstatus = 1 AND a.status = ''Active'' AND s.schedule_date <= CURRENT_DATE AND NOT COALESCE(s.is_posted, false)"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-076', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-076", "kpi_name": "Average Asset Depreciated %", "kpi_module": "FINANCE", "sub_area": "Fixed Assets", "is_active": true, "definition": "Cumulative depreciation compared to gross acquisition cost", "formula": "SUM(Accumulated depreciation) / SUM(gross_purchase_amount) x100", "unit": "%", "direction": "Range", "target": "< 70% (assets not obsolete)", "frequency": "Annual", "owner_role": "CFO", "source_doctypes": "Asset", "key_fields": "gross_purchase_amount, accumulated_depreciation", "platform_equivalent": "SAP", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_076", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT ROUND(100.0 * SUM(COALESCE(a.opening_accumulated_depreciation, 0) + COALESCE((SELECT SUM(s.depreciation_amount) FROM reporting.asset_schedule s WHERE s.parent = a.name AND s.is_posted), 0)) / NULLIF(SUM(a.gross_purchase_amount), 0), 2) AS value FROM reporting.asset a WHERE a.docstatus = 1 AND a.status IN (''Active'',''Fully Depreciated'')"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-077', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-077", "kpi_name": "Fully Depreciated Assets In Use", "kpi_module": "FINANCE", "sub_area": "Fixed Assets", "is_active": true, "definition": "Assets completely written off but still actively in service", "formula": "COUNT(status=''Fully Depreciated'')", "unit": "Assets", "direction": "Range", "target": "Evaluated for replacement", "frequency": "Annual", "owner_role": "Asset Accountant", "source_doctypes": "Asset", "key_fields": "status", "platform_equivalent": "SAP", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_077", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT COUNT(*) AS value FROM reporting.asset WHERE docstatus = 1 AND status = ''Fully Depreciated''"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-078', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-078", "kpi_name": "Disposal Gain / Loss", "kpi_module": "FINANCE", "sub_area": "Fixed Assets", "is_active": true, "definition": "Net gain or loss realized on fixed asset retirements and disposals", "formula": "SUM(AssetDisposal.gain_loss)", "unit": "IDR", "direction": "Range", "target": "—", "frequency": "Quarterly", "owner_role": "Asset Accountant", "source_doctypes": "AssetDisposal", "key_fields": "gain_loss, disposal_type", "platform_equivalent": "SAP ABAVN/F-92", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_078", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT COALESCE(SUM(gain_loss), 0) AS value FROM reporting.asset_disposal WHERE docstatus = 1 AND disposal_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-079', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-079", "kpi_name": "Write-offs & Lost Assets", "kpi_module": "FINANCE", "sub_area": "Fixed Assets", "is_active": true, "definition": "Net book value of assets scrapped, lost, or written off", "formula": "COUNT / SUM(book_value WHERE disposal_type IN (''Write-off'',''Lost/Damaged''))", "unit": "IDR", "direction": "Down", "target": "Minimal", "frequency": "Annual", "owner_role": "Asset Accountant", "source_doctypes": "AssetDisposal", "key_fields": "disposal_type, book_value", "platform_equivalent": "SAP", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_079", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT COALESCE(SUM(book_value), 0) AS value FROM reporting.asset_disposal WHERE docstatus = 1 AND disposal_type IN (''Write-off'',''Lost/Damaged'') AND disposal_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-080', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-080", "kpi_name": "Assets Without Custodian", "kpi_module": "FINANCE", "sub_area": "Fixed Assets", "is_active": true, "definition": "Active fixed assets missing an assigned custodian or owner", "formula": "COUNT(Asset status=''Active'' AND custodian IS NULL)", "unit": "Assets", "direction": "Down", "target": "0", "frequency": "Quarterly", "owner_role": "Asset Accountant", "source_doctypes": "Asset", "key_fields": "custodian", "platform_equivalent": "SAP / NetSuite", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_080", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT COUNT(*) AS value FROM reporting.asset WHERE docstatus = 1 AND status = ''Active'' AND custodian IS NULL"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-081', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-081", "kpi_name": "Assets Without Location / Cost Center", "kpi_module": "FINANCE", "sub_area": "Fixed Assets", "is_active": true, "definition": "Active fixed assets lacking an assigned physical location or cost center", "formula": "COUNT(location IS NULL OR cost_center IS NULL)", "unit": "Assets", "direction": "Down", "target": "0", "frequency": "Quarterly", "owner_role": "Asset Accountant", "source_doctypes": "Asset", "key_fields": "location, cost_center", "platform_equivalent": "SAP", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_081", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT COUNT(*) AS value FROM reporting.asset WHERE docstatus = 1 AND status = ''Active'' AND (location IS NULL OR cost_center IS NULL)"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-082', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-082", "kpi_name": "Period Capex", "kpi_module": "FINANCE", "sub_area": "Fixed Assets", "is_active": true, "definition": "Total capital expenditures invested in new fixed assets during period", "formula": "SUM(gross_purchase_amount WHERE purchase_date in period)", "unit": "IDR", "direction": "Range", "target": "Within capex budget", "frequency": "Quarterly", "owner_role": "CFO", "source_doctypes": "Asset, PurchaseInvoiceItem", "key_fields": "gross_purchase_amount, asset_category", "platform_equivalent": "SAP / NetSuite / Workday", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_082", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT COALESCE(SUM(gross_purchase_amount), 0) AS value FROM reporting.asset WHERE docstatus = 1 AND NOT COALESCE(is_existing_asset, false) AND purchase_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-083', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-083", "kpi_name": "Draft Assets Not Activated", "kpi_module": "FINANCE", "sub_area": "Fixed Assets", "is_active": true, "definition": "Capital assets purchased over 30 days ago remaining in Draft state", "formula": "COUNT(status=''Draft'' AND purchase_date < CURRENT_DATE − 30)", "unit": "Assets", "direction": "Down", "target": "0", "frequency": "Monthly", "owner_role": "Asset Accountant", "source_doctypes": "Asset", "key_fields": "status, purchase_date", "platform_equivalent": "SAP AuC", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_083", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT COUNT(*) AS value FROM reporting.asset WHERE docstatus = 0 AND purchase_date < CURRENT_DATE - 30"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'FIN-084', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "FIN-084", "kpi_name": "Capex to Depreciation Ratio", "kpi_module": "FINANCE", "sub_area": "Fixed Assets", "is_active": true, "definition": "Capital expenditure investment compared to periodic depreciation charge", "formula": "Capex / Depreciation expense", "unit": "Ratio", "direction": "Range", "target": "≥ 1 (business growing)", "frequency": "Annual", "owner_role": "CFO", "source_doctypes": "Asset, DepreciationRun", "key_fields": "gross_purchase_amount, total_depreciation", "platform_equivalent": "SAP", "implementation": "Dashboard widget", "widget_id": "w_kpi_fin_084", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND((SELECT SUM(gross_purchase_amount) FROM reporting.asset WHERE docstatus = 1 AND NOT COALESCE(is_existing_asset, false) AND purchase_date BETWEEN @Start AND @End) / NULLIF((SELECT SUM(total_depreciation) FROM reporting.depreciation_run WHERE docstatus = 1 AND posting_date BETWEEN @Start AND @End), 0), 2) AS value"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'ACC-001', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "ACC-001", "kpi_name": "Manual Journal Count", "kpi_module": "ACCOUNTING", "sub_area": "General Ledger", "is_active": true, "definition": "Number of manual journal entries posted per period", "formula": "COUNT(JournalEntry docstatus=1 in period)", "unit": "Journals", "direction": "Down", "target": "Decrease with automation", "frequency": "Monthly", "owner_role": "Chief Accountant", "source_doctypes": "JournalEntry", "key_fields": "voucher_type, posting_date", "platform_equivalent": "SAP FB50; NetSuite Journal; Workday Journal", "implementation": "Dashboard widget", "widget_id": "w_kpi_acc_001", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT COUNT(*) AS value FROM reporting.journal_entry WHERE docstatus = 1 AND posting_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'ACC-002', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "ACC-002", "kpi_name": "Manual Journal Ratio", "kpi_module": "ACCOUNTING", "sub_area": "General Ledger", "is_active": true, "definition": "Manual journals compared to total general ledger transactions", "formula": "COUNT(JournalEntry) / COUNT(all GL vouchers) x100", "unit": "%", "direction": "Down", "target": "≤ 10%", "frequency": "Monthly", "owner_role": "Chief Accountant", "source_doctypes": "JournalEntry, GL entries", "key_fields": "voucher_type", "platform_equivalent": "SAP / NetSuite", "implementation": "Dashboard widget", "widget_id": "w_kpi_acc_002", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "WITH v AS (SELECT ''JE'' AS t FROM reporting.journal_entry WHERE docstatus = 1 AND posting_date BETWEEN @Start AND @End UNION ALL SELECT ''X'' FROM reporting.sales_invoice WHERE docstatus = 1 AND posting_date BETWEEN @Start AND @End UNION ALL SELECT ''X'' FROM reporting.purchase_invoice WHERE docstatus = 1 AND posting_date BETWEEN @Start AND @End UNION ALL SELECT ''X'' FROM reporting.payment_entry WHERE docstatus = 1 AND posting_date BETWEEN @Start AND @End UNION ALL SELECT ''X'' FROM reporting.sales_credit_note WHERE docstatus = 1 AND posting_date BETWEEN @Start AND @End UNION ALL SELECT ''X'' FROM reporting.purchase_debit_note WHERE docstatus = 1 AND posting_date BETWEEN @Start AND @End UNION ALL SELECT ''X'' FROM reporting.stock_entry WHERE docstatus = 1 AND posting_date BETWEEN @Start AND @End) SELECT ROUND(100.0 * COUNT(*) FILTER (WHERE t = ''JE'') / NULLIF(COUNT(*), 0), 2) AS value FROM v"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'ACC-003', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "ACC-003", "kpi_name": "Journals Without Supporting Document", "kpi_module": "ACCOUNTING", "sub_area": "General Ledger", "is_active": true, "definition": "Manual journal entries posted without attached supporting documentation", "formula": "COUNT(supporting_document IS NULL) / COUNT(JournalEntry) x100", "unit": "%", "direction": "Down", "target": "0%", "frequency": "Monthly", "owner_role": "Internal Audit", "source_doctypes": "JournalEntry", "key_fields": "supporting_document", "platform_equivalent": "SAP / NetSuite", "implementation": "Not available", "implementation_note": "Source fields are restricted in reporting schema (permLevel 1 or attachment), so it cannot be computed by a widget."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'ACC-004', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "ACC-004", "kpi_name": "Rejected Unbalanced Journals", "kpi_module": "ACCOUNTING", "sub_area": "General Ledger", "is_active": true, "definition": "Journal entries created with debit/credit difference not equal to zero", "formula": "COUNT(difference != 0 AND docstatus=0)", "unit": "Journals", "direction": "Down", "target": "0", "frequency": "Weekly", "owner_role": "Chief Accountant", "source_doctypes": "JournalEntry", "key_fields": "difference, total_debit, total_credit", "platform_equivalent": "SAP", "implementation": "Dashboard widget", "widget_id": "w_kpi_acc_004", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT COUNT(*) AS value FROM reporting.journal_entry WHERE docstatus = 0 AND ABS(COALESCE(difference, 0)) > 0.005"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'ACC-005', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "ACC-005", "kpi_name": "Auto-reversal Compliance", "kpi_module": "ACCOUNTING", "sub_area": "General Ledger", "is_active": true, "definition": "Accrual journals marked for auto-reversal that have been reversed", "formula": "COUNT(auto_reverse=1 AND has reversal_of) / COUNT(auto_reverse=1 AND reversal_date <= CURRENT_DATE) x100", "unit": "%", "direction": "Up", "target": "100%", "frequency": "Monthly", "owner_role": "Chief Accountant", "source_doctypes": "JournalEntry", "key_fields": "auto_reverse, reversal_date, reversal_of", "platform_equivalent": "SAP F.81; NetSuite Reversing JE", "implementation": "Dashboard widget", "widget_id": "w_kpi_acc_005", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE EXISTS (SELECT 1 FROM reporting.journal_entry r WHERE r.reversal_of = j.name AND r.docstatus = 1))) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.journal_entry j WHERE j.docstatus = 1 AND j.auto_reverse AND j.reversal_date <= CURRENT_DATE AND j.posting_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'ACC-006', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "ACC-006", "kpi_name": "Cancelled / Amended Journals", "kpi_module": "ACCOUNTING", "sub_area": "General Ledger", "is_active": true, "definition": "Percentage of journal entries cancelled or amended post-submission", "formula": "COUNT(docstatus=2) / COUNT(JournalEntry) x100", "unit": "%", "direction": "Down", "target": "≤ 2%", "frequency": "Monthly", "owner_role": "Chief Accountant", "source_doctypes": "JournalEntry", "key_fields": "docstatus", "platform_equivalent": "SAP", "implementation": "Dashboard widget", "widget_id": "w_kpi_acc_006", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE docstatus = 2)) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.journal_entry WHERE docstatus IN (1, 2) AND posting_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'ACC-007', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "ACC-007", "kpi_name": "Backdated Postings", "kpi_module": "ACCOUNTING", "sub_area": "General Ledger", "is_active": true, "definition": "Transactions posted with effective dates preceding system entry by threshold", "formula": "COUNT(creation − posting_date > AccountingSettings.backdate_limit_days)", "unit": "Vouchers", "direction": "Down", "target": "0", "frequency": "Monthly", "owner_role": "Internal Audit", "source_doctypes": "JournalEntry, SalesInvoice, PurchaseInvoice, AccountingSettings", "key_fields": "posting_date, creation, backdate_limit_days", "platform_equivalent": "SAP / NetSuite", "implementation": "Dashboard widget", "widget_id": "w_kpi_acc_007", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT COUNT(*) AS value FROM (SELECT posting_date, created FROM reporting.journal_entry WHERE docstatus = 1 UNION ALL SELECT posting_date, created FROM reporting.sales_invoice WHERE docstatus = 1 UNION ALL SELECT posting_date, created FROM reporting.purchase_invoice WHERE docstatus = 1 UNION ALL SELECT posting_date, created FROM reporting.payment_entry WHERE docstatus = 1) v WHERE v.created::date BETWEEN @Start AND @End AND v.created::date - v.posting_date > COALESCE((SELECT MAX(backdate_limit_days) FROM reporting.accounting_settings), 7)"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'ACC-008', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "ACC-008", "kpi_name": "Future-dated Postings", "kpi_module": "ACCOUNTING", "sub_area": "General Ledger", "is_active": true, "definition": "Transactions entered with posting dates set in future periods", "formula": "COUNT(posting_date > creation date)", "unit": "Vouchers", "direction": "Down", "target": "0 (unless authorized)", "frequency": "Monthly", "owner_role": "Internal Audit", "source_doctypes": "JournalEntry, AccountingSettings", "key_fields": "posting_date, allow_future_posting", "platform_equivalent": "SAP", "implementation": "Dashboard widget", "widget_id": "w_kpi_acc_008", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT COUNT(*) AS value FROM (SELECT posting_date, created FROM reporting.journal_entry WHERE docstatus = 1 UNION ALL SELECT posting_date, created FROM reporting.sales_invoice WHERE docstatus = 1 UNION ALL SELECT posting_date, created FROM reporting.purchase_invoice WHERE docstatus = 1 UNION ALL SELECT posting_date, created FROM reporting.payment_entry WHERE docstatus = 1) v WHERE v.created::date BETWEEN @Start AND @End AND v.posting_date > v.created::date"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'ACC-009', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "ACC-009", "kpi_name": "P&L Lines Without Cost Center", "kpi_module": "ACCOUNTING", "sub_area": "General Ledger", "is_active": true, "definition": "Profit and loss journal entry lines missing an assigned cost center", "formula": "COUNT(JournalEntryLine account.report_type=''Profit and Loss'' AND cost_center IS NULL)", "unit": "Lines", "direction": "Down", "target": "0", "frequency": "Monthly", "owner_role": "Controller", "source_doctypes": "JournalEntryLine, Account, AccountingSettings", "key_fields": "cost_center, report_type, enforce_cost_center_on_pl", "platform_equivalent": "SAP CO; NetSuite Department/Class", "implementation": "Dashboard widget", "widget_id": "w_kpi_acc_009", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT COUNT(*) AS value FROM reporting.journal_entry_accounts l JOIN reporting.journal_entry j ON j.name = l.parent JOIN reporting.account a ON a.name = l.account WHERE j.docstatus = 1 AND j.posting_date BETWEEN @Start AND @End AND a.report_type = ''Profit and Loss'' AND l.cost_center IS NULL"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'ACC-010', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "ACC-010", "kpi_name": "Direct Postings to Control Accounts", "kpi_module": "ACCOUNTING", "sub_area": "General Ledger", "is_active": true, "definition": "Manual journal lines posting directly to AR/AP control accounts without subledger party", "formula": "COUNT(JournalEntryLine account.is_control_account=1 AND party IS NULL)", "unit": "Lines", "direction": "Down", "target": "0", "frequency": "Monthly", "owner_role": "Internal Audit", "source_doctypes": "JournalEntryLine, Account", "key_fields": "is_control_account, party", "platform_equivalent": "SAP Reconciliation Account", "implementation": "Dashboard widget", "widget_id": "w_kpi_acc_010", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT COUNT(*) AS value FROM reporting.journal_entry_accounts l JOIN reporting.journal_entry j ON j.name = l.parent JOIN reporting.account a ON a.name = l.account WHERE j.docstatus = 1 AND j.posting_date BETWEEN @Start AND @End AND a.is_control_account AND l.party IS NULL"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'ACC-011', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "ACC-011", "kpi_name": "Postings to Frozen / Inactive Accounts", "kpi_module": "ACCOUNTING", "sub_area": "General Ledger", "is_active": true, "definition": "Attempted postings to frozen accounts or deactivated accounts", "formula": "COUNT(postings to Account is_frozen=1 OR is_active=0)", "unit": "Occurrences", "direction": "Down", "target": "0", "frequency": "Monthly", "owner_role": "Chief Accountant", "source_doctypes": "JournalEntryLine, Account", "key_fields": "is_frozen, is_active", "platform_equivalent": "SAP", "implementation": "Dashboard widget", "widget_id": "w_kpi_acc_011", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT COUNT(*) AS value FROM reporting.journal_entry_accounts l JOIN reporting.journal_entry j ON j.name = l.parent JOIN reporting.account a ON a.name = l.account WHERE j.docstatus = 1 AND j.posting_date BETWEEN @Start AND @End AND (a.is_frozen OR NOT a.is_active)"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'ACC-012', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "ACC-012", "kpi_name": "Realized FX Gain / Loss", "kpi_module": "ACCOUNTING", "sub_area": "General Ledger", "is_active": true, "definition": "Net realized foreign exchange gain or loss posted to general ledger", "formula": "SUM(GL balance of Company.exchange_gain_loss_account)", "unit": "IDR", "direction": "Range", "target": "—", "frequency": "Monthly", "owner_role": "Treasury", "source_doctypes": "GL entries, Company", "key_fields": "exchange_gain_loss_account", "platform_equivalent": "SAP / NetSuite Revaluation", "implementation": "Built-in report", "builtin_report": "ProfitAndLossReport", "implementation_note": "Requires general ledger data (frogframe_gl_entries), which is not included in the reporting schema and cannot be used by widgets. Use the built-in ProfitAndLossReport."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'ACC-013', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "ACC-013", "kpi_name": "Round-off Difference", "kpi_module": "ACCOUNTING", "sub_area": "General Ledger", "is_active": true, "definition": "Total monetary adjustments absorbed by rounding difference accounts", "formula": "SUM(ABS(GL round_off_account))", "unit": "IDR", "direction": "Down", "target": "Near 0", "frequency": "Monthly", "owner_role": "Chief Accountant", "source_doctypes": "GL entries, Company", "key_fields": "round_off_account", "platform_equivalent": "SAP", "implementation": "Built-in report", "builtin_report": "TrialBalanceReport", "implementation_note": "Requires general ledger data (frogframe_gl_entries), which is not included in the reporting schema and cannot be used by widgets. Use the built-in TrialBalanceReport."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'ACC-014', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "ACC-014", "kpi_name": "Trial Balance Integrity Check", "kpi_module": "ACCOUNTING", "sub_area": "General Ledger", "is_active": true, "definition": "Variance between total debits and total credits on trial balance", "formula": "SUM(debit) − SUM(credit) (TrialBalanceReport)", "unit": "IDR", "direction": "Down", "target": "0", "frequency": "Monthly", "owner_role": "Chief Accountant", "source_doctypes": "GL entries (TrialBalanceReport)", "key_fields": "debit, credit", "platform_equivalent": "SAP / NetSuite / Workday", "implementation": "Built-in report", "builtin_report": "TrialBalanceReport", "implementation_note": "Requires general ledger data (frogframe_gl_entries), which is not included in the reporting schema and cannot be used by widgets. Use the built-in TrialBalanceReport."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'ACC-015', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "ACC-015", "kpi_name": "Suspense / Clearing Account Balance", "kpi_module": "ACCOUNTING", "sub_area": "General Ledger", "is_active": true, "definition": "Ending balance in clearing accounts (GRNI, unallocated suspense)", "formula": "SUM(GL StockSettings.grni_account + suspense accounts)", "unit": "IDR", "direction": "Down", "target": "Near 0 / fully explained", "frequency": "Monthly", "owner_role": "Chief Accountant", "source_doctypes": "GL entries, StockSettings", "key_fields": "grni_account", "platform_equivalent": "SAP GR/IR (F.13); NetSuite Accrued Purchases", "implementation": "Built-in report", "builtin_report": "TrialBalanceReport", "implementation_note": "Requires general ledger data (frogframe_gl_entries), which is not included in the reporting schema and cannot be used by widgets. Use the built-in TrialBalanceReport."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'ACC-016', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "ACC-016", "kpi_name": "Days to Close", "kpi_module": "ACCOUNTING", "sub_area": "Period Close", "is_active": true, "definition": "Working days from fiscal month end to official accounting period closure", "formula": "AVG(closed_on − end_date) working days", "unit": "Working days", "direction": "Down", "target": "≤ 5 working days", "frequency": "Monthly", "owner_role": "Controller", "source_doctypes": "AccountingPeriod", "key_fields": "end_date, closed_on, status", "platform_equivalent": "NetSuite Period Close Checklist; SAP Financial Closing Cockpit; Workday Close", "implementation": "Dashboard widget", "widget_id": "w_kpi_acc_016", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(AVG(closed_on::date - end_date), 1) AS value FROM reporting.accounting_period WHERE status = ''Closed'' AND closed_on IS NOT NULL AND end_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'ACC-017', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "ACC-017", "kpi_name": "Overdue Open Fiscal Periods", "kpi_module": "ACCOUNTING", "sub_area": "Period Close", "is_active": true, "definition": "Fiscal periods remaining open more than 10 days past end date", "formula": "COUNT(status=''Open'' AND end_date < CURRENT_DATE − 10)", "unit": "Periods", "direction": "Down", "target": "0", "frequency": "Monthly", "owner_role": "Controller", "source_doctypes": "AccountingPeriod", "key_fields": "status, end_date", "platform_equivalent": "SAP OB52; NetSuite", "implementation": "Dashboard widget", "widget_id": "w_kpi_acc_017", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT COUNT(*) AS value FROM reporting.accounting_period WHERE status = ''Open'' AND end_date < CURRENT_DATE - 10"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'ACC-018', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "ACC-018", "kpi_name": "Sub-ledger Lock Compliance", "kpi_module": "ACCOUNTING", "sub_area": "Period Close", "is_active": true, "definition": "Closed periods where AR, AP, Fixed Asset, and Payroll subledgers are locked", "formula": "COUNT(lock_receivable AND lock_payable AND lock_fixed_asset AND lock_payroll) / COUNT(Closed) x100", "unit": "%", "direction": "Up", "target": "100%", "frequency": "Monthly", "owner_role": "Controller", "source_doctypes": "AccountingPeriod", "key_fields": "lock_receivable, lock_payable, lock_fixed_asset, lock_payroll", "platform_equivalent": "SAP posting periods per account type; NetSuite AP/AR lock", "implementation": "Dashboard widget", "widget_id": "w_kpi_acc_018", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE lock_receivable AND lock_payable AND lock_fixed_asset AND lock_payroll)) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.accounting_period WHERE status = ''Closed'' AND end_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'ACC-019', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "ACC-019", "kpi_name": "Post-close Adjustments", "kpi_module": "ACCOUNTING", "sub_area": "Period Close", "is_active": true, "definition": "Transactions posted into previously closed fiscal periods via reopen", "formula": "COUNT(voucher posting_date <= period.end_date AND creation > closed_on)", "unit": "Vouchers", "direction": "Down", "target": "0", "frequency": "Monthly", "owner_role": "Controller", "source_doctypes": "AccountingPeriod, JournalEntry", "key_fields": "closed_on, posting_date, creation", "platform_equivalent": "SAP / NetSuite", "implementation": "Dashboard widget", "widget_id": "w_kpi_acc_019", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT COUNT(*) AS value FROM (SELECT posting_date, created FROM reporting.journal_entry WHERE docstatus = 1 UNION ALL SELECT posting_date, created FROM reporting.sales_invoice WHERE docstatus = 1 UNION ALL SELECT posting_date, created FROM reporting.purchase_invoice WHERE docstatus = 1 UNION ALL SELECT posting_date, created FROM reporting.payment_entry WHERE docstatus = 1) v JOIN reporting.accounting_period p ON v.posting_date BETWEEN p.start_date AND p.end_date WHERE p.status = ''Closed'' AND p.closed_on IS NOT NULL AND v.created > p.closed_on AND p.end_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'ACC-020', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "ACC-020", "kpi_name": "Books Frozen Lag", "kpi_module": "ACCOUNTING", "sub_area": "Period Close", "is_active": true, "definition": "Days elapsed between prior month end and current books_frozen_until cutoff", "formula": "Prior month end − AccountingSettings.books_frozen_until", "unit": "Days", "direction": "Down", "target": "≤ 10 days", "frequency": "Monthly", "owner_role": "Controller", "source_doctypes": "AccountingSettings", "key_fields": "books_frozen_until", "platform_equivalent": "SAP", "implementation": "Dashboard widget", "widget_id": "w_kpi_acc_020", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT ((date_trunc(''month'', CURRENT_DATE) - interval ''1 day'')::date - MAX(books_frozen_until)) AS value FROM reporting.accounting_settings"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'ACC-021', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "ACC-021", "kpi_name": "Year-end Closing Completed", "kpi_module": "ACCOUNTING", "sub_area": "Period Close", "is_active": true, "definition": "Fiscal years closed with submitted Period Closing Vouchers", "formula": "COUNT(PeriodClosingVoucher docstatus=1 per fiscal_year)", "unit": "Yes/No", "direction": "Up", "target": "Completed ≤ 60 days post year-end", "frequency": "Annual", "owner_role": "Controller", "source_doctypes": "PeriodClosingVoucher, FiscalYear", "key_fields": "fiscal_year, status", "platform_equivalent": "SAP FAGLGVTR; NetSuite Year-end Close", "implementation": "Dashboard widget", "widget_id": "w_kpi_acc_021", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT COUNT(*) AS value FROM reporting.fiscal_year f WHERE f.end_date < CURRENT_DATE AND NOT EXISTS (SELECT 1 FROM reporting.period_closing_voucher v WHERE v.fiscal_year = f.name AND v.docstatus = 1)"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'ACC-022', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "ACC-022", "kpi_name": "Intercompany Balance Mismatch", "kpi_module": "ACCOUNTING", "sub_area": "Period Close", "is_active": true, "definition": "Reconciliation imbalance between internal customer AR and internal vendor AP", "formula": "SUM(Internal customer AR) − SUM(Internal vendor AP)", "unit": "IDR", "direction": "Down", "target": "0", "frequency": "Monthly", "owner_role": "Group Controller", "source_doctypes": "SalesInvoice, PurchaseInvoice, Customer, Vendor", "key_fields": "is_internal_customer, is_internal_vendor, represents_company", "platform_equivalent": "NetSuite OneWorld IC; SAP ICR", "implementation": "Dashboard widget", "widget_id": "w_kpi_acc_022", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT COALESCE((SELECT SUM(si.outstanding_amount * si.exchange_rate) FROM reporting.sales_invoice si JOIN reporting.customer c ON c.name = si.customer WHERE si.docstatus = 1 AND c.is_internal_customer), 0) - COALESCE((SELECT SUM(pi.outstanding_amount * pi.exchange_rate) FROM reporting.purchase_invoice pi JOIN reporting.vendor v ON v.name = pi.vendor WHERE pi.docstatus = 1 AND v.is_internal_vendor), 0) AS value"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'ACC-023', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "ACC-023", "kpi_name": "Exchange Rate Coverage at Close", "kpi_module": "ACCOUNTING", "sub_area": "Period Close", "is_active": true, "definition": "Active foreign currencies with verified period-end revaluation rates", "formula": "COUNT(CurrencyExchangeRate rate_date=period end) / COUNT(Active foreign currencies)", "unit": "%", "direction": "Up", "target": "100%", "frequency": "Monthly", "owner_role": "Treasury", "source_doctypes": "CurrencyExchangeRate, Currency", "key_fields": "rate_date, rate_type", "platform_equivalent": "SAP FAGL_FCV; NetSuite Revaluation", "implementation": "Dashboard widget", "widget_id": "w_kpi_acc_023", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE EXISTS (SELECT 1 FROM reporting.currency_exchange_rate r WHERE r.from_currency = cur.name AND r.rate_date = (date_trunc(''month'', CURRENT_DATE) - interval ''1 day'')::date))) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.currency cur WHERE cur.is_active AND cur.name NOT IN (SELECT base_currency FROM reporting.company WHERE base_currency IS NOT NULL)"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'ACC-024', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "ACC-024", "kpi_name": "Total Revenue", "kpi_module": "ACCOUNTING", "sub_area": "Financial Statements", "is_active": true, "definition": "Net operating revenue reported on the profit and loss statement", "formula": "SUM(GL accounts where root_type=''Income'')", "unit": "IDR", "direction": "Up", "target": "Per target", "frequency": "Monthly", "owner_role": "CFO", "source_doctypes": "Account, GL entries (ProfitAndLossReport)", "key_fields": "root_type", "platform_equivalent": "Semua platform", "implementation": "Built-in report", "builtin_report": "ProfitAndLossReport", "implementation_note": "Requires general ledger data (frogframe_gl_entries), which is not included in the reporting schema and cannot be used by widgets. Use the built-in ProfitAndLossReport."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'ACC-025', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "ACC-025", "kpi_name": "Gross Profit Margin", "kpi_module": "ACCOUNTING", "sub_area": "Financial Statements", "is_active": true, "definition": "Gross profit margin percentage (Revenue minus COGS over Revenue)", "formula": "(Income − COGS (StockSettings.cogs_account)) / Income x100", "unit": "%", "direction": "Up", "target": "Industry standard", "frequency": "Monthly", "owner_role": "CFO", "source_doctypes": "GL entries, StockSettings", "key_fields": "cogs_account, root_type", "platform_equivalent": "NetSuite KPI; SAP Fiori; Workday", "implementation": "Built-in report", "builtin_report": "ProfitAndLossReport", "implementation_note": "Requires general ledger data (frogframe_gl_entries), which is not included in the reporting schema and cannot be used by widgets. Use the built-in ProfitAndLossReport."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'ACC-026', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "ACC-026", "kpi_name": "Operating Expense Ratio", "kpi_module": "ACCOUNTING", "sub_area": "Financial Statements", "is_active": true, "definition": "Operating expenses (SG&A) compared to net revenue", "formula": "SUM(Operating expenses excluding COGS) / Income x100", "unit": "%", "direction": "Down", "target": "—", "frequency": "Monthly", "owner_role": "CFO", "source_doctypes": "GL entries, Account", "key_fields": "root_type, account_type", "platform_equivalent": "Semua platform", "implementation": "Built-in report", "builtin_report": "ProfitAndLossReport", "implementation_note": "Requires general ledger data (frogframe_gl_entries), which is not included in the reporting schema and cannot be used by widgets. Use the built-in ProfitAndLossReport."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'ACC-027', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "ACC-027", "kpi_name": "EBITDA Margin", "kpi_module": "ACCOUNTING", "sub_area": "Financial Statements", "is_active": true, "definition": "Operating earnings before interest, taxes, depreciation, and amortization margin", "formula": "(Operating profit + depreciation) / Income x100", "unit": "%", "direction": "Up", "target": "—", "frequency": "Monthly", "owner_role": "CFO", "source_doctypes": "GL entries, DepreciationRun", "key_fields": "depreciation_expense_account", "platform_equivalent": "Semua platform", "implementation": "Built-in report", "builtin_report": "ProfitAndLossReport", "implementation_note": "Requires general ledger data (frogframe_gl_entries), which is not included in the reporting schema and cannot be used by widgets. Use the built-in ProfitAndLossReport."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'ACC-028', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "ACC-028", "kpi_name": "Net Profit Margin", "kpi_module": "ACCOUNTING", "sub_area": "Financial Statements", "is_active": true, "definition": "Net profit after taxes compared to net revenue", "formula": "PeriodClosingVoucher.net_profit or (Income − Expense) / Income x100", "unit": "%", "direction": "Up", "target": "—", "frequency": "Monthly", "owner_role": "CFO", "source_doctypes": "GL entries, PeriodClosingVoucher", "key_fields": "net_profit", "platform_equivalent": "Semua platform", "implementation": "Built-in report", "builtin_report": "ProfitAndLossReport", "implementation_note": "Requires general ledger data (frogframe_gl_entries), which is not included in the reporting schema and cannot be used by widgets. Use the built-in ProfitAndLossReport."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'ACC-029', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "ACC-029", "kpi_name": "Current Ratio", "kpi_module": "ACCOUNTING", "sub_area": "Financial Statements", "is_active": true, "definition": "Short-term liquidity ratio of current assets to current liabilities", "formula": "SUM(Current assets) / SUM(Current liabilities) (BalanceSheetReport)", "unit": "Ratio", "direction": "Range", "target": "1,5–3", "frequency": "Monthly", "owner_role": "CFO", "source_doctypes": "Account, GL entries", "key_fields": "root_type, account_type", "platform_equivalent": "Semua platform", "implementation": "Built-in report", "builtin_report": "BalanceSheetReport", "implementation_note": "Requires general ledger data (frogframe_gl_entries), which is not included in the reporting schema and cannot be used by widgets. Use the built-in BalanceSheetReport."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'ACC-030', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "ACC-030", "kpi_name": "Quick Ratio", "kpi_module": "ACCOUNTING", "sub_area": "Financial Statements", "is_active": true, "definition": "Acid-test liquidity ratio of cash and receivables to current liabilities", "formula": "(Cash + AR) / Current liabilities", "unit": "Ratio", "direction": "Up", "target": "≥ 1", "frequency": "Monthly", "owner_role": "CFO", "source_doctypes": "Account, GL entries", "key_fields": "account_type", "platform_equivalent": "Semua platform", "implementation": "Built-in report", "builtin_report": "BalanceSheetReport", "implementation_note": "Requires general ledger data (frogframe_gl_entries), which is not included in the reporting schema and cannot be used by widgets. Use the built-in BalanceSheetReport."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'ACC-031', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "ACC-031", "kpi_name": "Debt to Equity Ratio", "kpi_module": "ACCOUNTING", "sub_area": "Financial Statements", "is_active": true, "definition": "Financial leverage ratio of total liabilities to shareholders'' equity", "formula": "SUM(root_type=''Liability'') / SUM(root_type=''Equity'')", "unit": "Ratio", "direction": "Range", "target": "≤ 1,5", "frequency": "Quarterly", "owner_role": "CFO", "source_doctypes": "Account, GL entries", "key_fields": "root_type", "platform_equivalent": "Semua platform", "implementation": "Built-in report", "builtin_report": "BalanceSheetReport", "implementation_note": "Requires general ledger data (frogframe_gl_entries), which is not included in the reporting schema and cannot be used by widgets. Use the built-in BalanceSheetReport."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'ACC-032', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "ACC-032", "kpi_name": "Working Capital", "kpi_module": "ACCOUNTING", "sub_area": "Financial Statements", "is_active": true, "definition": "Operational net liquidity (current assets minus current liabilities)", "formula": "Current assets − Current liabilities", "unit": "IDR", "direction": "Up", "target": "Positive", "frequency": "Monthly", "owner_role": "CFO", "source_doctypes": "Account, GL entries", "key_fields": "account_type", "platform_equivalent": "Semua platform", "implementation": "Built-in report", "builtin_report": "BalanceSheetReport", "implementation_note": "Requires general ledger data (frogframe_gl_entries), which is not included in the reporting schema and cannot be used by widgets. Use the built-in BalanceSheetReport."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'ACC-033', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "ACC-033", "kpi_name": "Cash Conversion Cycle", "kpi_module": "ACCOUNTING", "sub_area": "Financial Statements", "is_active": true, "definition": "Operating cycle duration in days (DIO + DSO − DPO)", "formula": "DIO + DSO − DPO", "unit": "Days", "direction": "Down", "target": "Decrease QoQ", "frequency": "Monthly", "owner_role": "CFO", "source_doctypes": "SalesInvoice, PurchaseInvoice, StockEntry", "key_fields": "—", "platform_equivalent": "NetSuite / SAP", "implementation": "Built-in report", "builtin_report": "BalanceSheetReport", "implementation_note": "Requires general ledger data (frogframe_gl_entries), which is not included in the reporting schema and cannot be used by widgets. DIO requires inventory value and COGS. Use the built-in BalanceSheetReport."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'ACC-034', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "ACC-034", "kpi_name": "Return on Assets (ROA)", "kpi_module": "ACCOUNTING", "sub_area": "Financial Statements", "is_active": true, "definition": "Net income generated per unit of total assets", "formula": "Net profit / SUM(root_type=''Asset'') x100", "unit": "%", "direction": "Up", "target": "—", "frequency": "Quarterly", "owner_role": "CFO", "source_doctypes": "GL entries", "key_fields": "root_type", "platform_equivalent": "Semua platform", "implementation": "Built-in report", "builtin_report": "ProfitAndLossReport", "implementation_note": "Requires general ledger data (frogframe_gl_entries), which is not included in the reporting schema and cannot be used by widgets. Use the built-in ProfitAndLossReport."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'ACC-035', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "ACC-035", "kpi_name": "Return on Equity (ROE)", "kpi_module": "ACCOUNTING", "sub_area": "Financial Statements", "is_active": true, "definition": "Net income generated per unit of shareholders'' equity", "formula": "Net profit / SUM(root_type=''Equity'') x100", "unit": "%", "direction": "Up", "target": "—", "frequency": "Quarterly", "owner_role": "CFO", "source_doctypes": "GL entries", "key_fields": "root_type", "platform_equivalent": "Semua platform", "implementation": "Built-in report", "builtin_report": "ProfitAndLossReport", "implementation_note": "Requires general ledger data (frogframe_gl_entries), which is not included in the reporting schema and cannot be used by widgets. Use the built-in ProfitAndLossReport."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'ACC-036', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "ACC-036", "kpi_name": "Profit by Cost Center", "kpi_module": "ACCOUNTING", "sub_area": "Financial Statements", "is_active": true, "definition": "Net contribution profit generated by individual cost centers", "formula": "SUM(Income − Expense) GROUP BY cost_center", "unit": "IDR", "direction": "Up", "target": "—", "frequency": "Monthly", "owner_role": "Controller", "source_doctypes": "GL entries, CostCenter", "key_fields": "cost_center", "platform_equivalent": "SAP CO-PCA; NetSuite Department P&L", "implementation": "Built-in report", "builtin_report": "ProfitAndLossReport", "implementation_note": "Requires general ledger data (frogframe_gl_entries), which is not included in the reporting schema and cannot be used by widgets. Use the built-in ProfitAndLossReport."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'ACC-037', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "ACC-037", "kpi_name": "Profit by Accounting Dimension", "kpi_module": "ACCOUNTING", "sub_area": "Financial Statements", "is_active": true, "definition": "Net profit analyzed across custom accounting dimensions (location, project)", "formula": "SUM(Income − Expense) GROUP BY dimension", "unit": "IDR", "direction": "Up", "target": "—", "frequency": "Monthly", "owner_role": "Controller", "source_doctypes": "GL entries, AccountingDimension", "key_fields": "dimension_code", "platform_equivalent": "NetSuite Class/Location; SAP Segment", "implementation": "Built-in report", "builtin_report": "ProfitAndLossReport", "implementation_note": "Requires general ledger data (frogframe_gl_entries), which is not included in the reporting schema and cannot be used by widgets. Use the built-in ProfitAndLossReport."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'ACC-038', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "ACC-038", "kpi_name": "Budget vs Actual Variance", "kpi_module": "ACCOUNTING", "sub_area": "Budget", "is_active": true, "definition": "Percentage variance between actual expenditures and planned budget", "formula": "(Actual − Budget) / Budget x100 (BudgetVsActualReport)", "unit": "%", "direction": "Range", "target": "± 5%", "frequency": "Monthly", "owner_role": "FP&A", "source_doctypes": "Budget, BudgetAccount, GL entries", "key_fields": "annual_amount, account, cost_center", "platform_equivalent": "Workday Adaptive Planning; SAP BPC/SAC; NetSuite Budget vs Actual", "implementation": "Built-in report", "builtin_report": "BudgetVsActualReport", "implementation_note": "Requires general ledger data (frogframe_gl_entries), which is not included in the reporting schema and cannot be used by widgets. Use the built-in BudgetVsActualReport."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'ACC-039', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "ACC-039", "kpi_name": "Budget Utilization", "kpi_module": "ACCOUNTING", "sub_area": "Budget", "is_active": true, "definition": "Year-to-date actual expenditure compared to annualized budget", "formula": "Actual YTD / total_budget x100", "unit": "%", "direction": "Range", "target": "Pro-rated across time", "frequency": "Monthly", "owner_role": "FP&A", "source_doctypes": "Budget, GL entries", "key_fields": "total_budget", "platform_equivalent": "Semua platform", "implementation": "Built-in report", "builtin_report": "BudgetVsActualReport", "implementation_note": "Requires general ledger data (frogframe_gl_entries), which is not included in the reporting schema and cannot be used by widgets. Use the built-in BudgetVsActualReport."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'ACC-040', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "ACC-040", "kpi_name": "Accounts Exceeding Budget", "kpi_module": "ACCOUNTING", "sub_area": "Budget", "is_active": true, "definition": "Number of GL accounts or cost centers where actual spend exceeds budget", "formula": "COUNT(BudgetAccount actual > annual_amount)", "unit": "Accounts", "direction": "Down", "target": "0", "frequency": "Monthly", "owner_role": "FP&A", "source_doctypes": "BudgetAccount, GL entries", "key_fields": "annual_amount", "platform_equivalent": "SAP Availability Control; NetSuite", "implementation": "Built-in report", "builtin_report": "BudgetVsActualReport", "implementation_note": "Requires general ledger data (frogframe_gl_entries), which is not included in the reporting schema and cannot be used by widgets. Use the built-in BudgetVsActualReport."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'ACC-041', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "ACC-041", "kpi_name": "Budget Overrun Events", "kpi_module": "ACCOUNTING", "sub_area": "Budget", "is_active": true, "definition": "Transactions triggering budget overrun warning or blocking actions", "formula": "COUNT(budget Stop/Warn trigger events)", "unit": "Occurrences", "direction": "Down", "target": "—", "frequency": "Monthly", "owner_role": "FP&A", "source_doctypes": "Budget", "key_fields": "action_if_exceeded, control_basis", "platform_equivalent": "SAP FM AVC", "implementation": "Built-in report", "builtin_report": "BudgetVsActualReport", "implementation_note": "Budget blocking or warning events are not stored as documents. Use the built-in BudgetVsActualReport."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'ACC-042', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "ACC-042", "kpi_name": "Cost Centers Without Budget", "kpi_module": "ACCOUNTING", "sub_area": "Budget", "is_active": true, "definition": "Active operational cost centers lacking an active annual budget allocation", "formula": "COUNT(CostCenter is_active=1 AND is_group=0 without active annual Budget)", "unit": "Cost centers", "direction": "Down", "target": "0", "frequency": "Annual", "owner_role": "FP&A", "source_doctypes": "CostCenter, Budget", "key_fields": "cost_center, fiscal_year", "platform_equivalent": "SAP / Workday Adaptive", "implementation": "Dashboard widget", "widget_id": "w_kpi_acc_042", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT COUNT(*) AS value FROM reporting.cost_center cc WHERE cc.is_active AND NOT cc.is_group AND NOT EXISTS (SELECT 1 FROM reporting.budget b JOIN reporting.fiscal_year f ON f.name = b.fiscal_year WHERE b.cost_center = cc.name AND b.docstatus = 1 AND CURRENT_DATE BETWEEN f.start_date AND f.end_date)"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'ACC-043', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "ACC-043", "kpi_name": "Forecast Accuracy", "kpi_module": "ACCOUNTING", "sub_area": "Budget", "is_active": true, "definition": "Financial forecasting precision compared to realized accounting actuals", "formula": "1 − |Actual − Forecast| / Actual x100", "unit": "%", "direction": "Up", "target": "≥ 90%", "frequency": "Quarterly", "owner_role": "FP&A", "source_doctypes": "Budget, GL entries", "key_fields": "—", "platform_equivalent": "Workday Adaptive; SAP SAC", "implementation": "Built-in report", "builtin_report": "BudgetVsActualReport", "implementation_note": "Requires general ledger data (frogframe_gl_entries), which is not included in the reporting schema and cannot be used by widgets. Use the built-in BudgetVsActualReport."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'ACC-044', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "ACC-044", "kpi_name": "Project Profit Margin", "kpi_module": "ACCOUNTING", "sub_area": "Project", "is_active": true, "definition": "Net project profitability (contract value minus actual project costs)", "formula": "(contract_value − SUM(GL project expenses)) / contract_value x100", "unit": "%", "direction": "Up", "target": "≥ planned margin", "frequency": "Monthly", "owner_role": "Project Controller", "source_doctypes": "Project, JournalEntryLine, PurchaseInvoiceItem, ExpenseClaim", "key_fields": "contract_value, project", "platform_equivalent": "NetSuite SuiteProjects; SAP PS; Workday Projects", "implementation": "Built-in report", "builtin_report": "ProfitAndLossReport", "implementation_note": "Requires general ledger data (frogframe_gl_entries), which is not included in the reporting schema and cannot be used by widgets. Project costs are derived from the project dimension in the general ledger. Use the built-in ProfitAndLossReport."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'ACC-045', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "ACC-045", "kpi_name": "Project Cost vs Estimate", "kpi_module": "ACCOUNTING", "sub_area": "Project", "is_active": true, "definition": "Actual project expenditure compared to initial engineering cost estimate", "formula": "SUM(Project costs) / estimated_cost x100", "unit": "%", "direction": "Down", "target": "≤ 100%", "frequency": "Monthly", "owner_role": "Project Controller", "source_doctypes": "Project", "key_fields": "estimated_cost", "platform_equivalent": "SAP PS; NetSuite", "implementation": "Built-in report", "builtin_report": "ProfitAndLossReport", "implementation_note": "Requires general ledger data (frogframe_gl_entries), which is not included in the reporting schema and cannot be used by widgets. Use the built-in ProfitAndLossReport."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'ACC-046', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "ACC-046", "kpi_name": "Project Billing Progress", "kpi_module": "ACCOUNTING", "sub_area": "Project", "is_active": true, "definition": "Invoices billed to date compared to total contracted project value", "formula": "SUM(SalesInvoice.tax_base WHERE project) / contract_value x100", "unit": "%", "direction": "Up", "target": "Per project progress", "frequency": "Monthly", "owner_role": "Project Controller", "source_doctypes": "Project, SalesInvoice", "key_fields": "project, contract_value", "platform_equivalent": "NetSuite Project Billing", "implementation": "Dashboard widget", "widget_id": "w_kpi_acc_046", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT ROUND(100.0 * (SUM(COALESCE((SELECT SUM(si.total * si.exchange_rate) FROM reporting.sales_invoice si WHERE si.project = p.name AND si.docstatus = 1), 0))) / NULLIF(SUM(p.contract_value), 0), 2) AS value FROM reporting.project p WHERE p.status IN (''In Progress'',''Completed'') AND p.contract_value > 0"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'ACC-047', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "ACC-047", "kpi_name": "Over-schedule Projects", "kpi_module": "ACCOUNTING", "sub_area": "Project", "is_active": true, "definition": "In-progress customer projects where scheduled end date has passed", "formula": "COUNT(status=''In Progress'' AND end_date < CURRENT_DATE)", "unit": "Projects", "direction": "Down", "target": "0", "frequency": "Weekly", "owner_role": "PMO", "source_doctypes": "Project", "key_fields": "status, end_date", "platform_equivalent": "SAP PS; Workday", "implementation": "Dashboard widget", "widget_id": "w_kpi_acc_047", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT COUNT(*) AS value FROM reporting.project WHERE status = ''In Progress'' AND end_date < CURRENT_DATE"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'ACC-048', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "ACC-048", "kpi_name": "On-hold Projects", "kpi_module": "ACCOUNTING", "sub_area": "Project", "is_active": true, "definition": "Projects currently suspended in On Hold status", "formula": "COUNT(status=''On Hold'')", "unit": "Projects", "direction": "Down", "target": "—", "frequency": "Monthly", "owner_role": "PMO", "source_doctypes": "Project", "key_fields": "status", "platform_equivalent": "SAP PS", "implementation": "Dashboard widget", "widget_id": "w_kpi_acc_048", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT COUNT(*) AS value FROM reporting.project WHERE status = ''On Hold''"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'PRC-001', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "PRC-001", "kpi_name": "PR Approval Cycle Time", "kpi_module": "PROCUREMENT", "sub_area": "Purchase Request", "is_active": true, "definition": "Average duration from purchase request submission to final approval", "formula": "AVG(approval transition duration: Approved − Pending)", "unit": "Days", "direction": "Down", "target": "≤ 2 days", "frequency": "Monthly", "owner_role": "Procurement Manager", "source_doctypes": "PurchaseRequest", "key_fields": "workflow_state", "platform_equivalent": "SAP ME51N/Flexible Workflow; NetSuite Purchase Requisition; Workday Requisition", "implementation": "Not available", "implementation_note": "Requires workflow transition timestamps per document (version/audit trail), which are not yet exposed to the reporting schema."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'PRC-002', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "PRC-002", "kpi_name": "PR to PO Cycle Time", "kpi_module": "PROCUREMENT", "sub_area": "Purchase Request", "is_active": true, "definition": "Days from purchase request approval to purchase order issuance", "formula": "AVG(PurchaseOrder.order_date − PR approval date)", "unit": "Days", "direction": "Down", "target": "≤ 5 days", "frequency": "Monthly", "owner_role": "Procurement Manager", "source_doctypes": "PurchaseRequest, PurchaseOrder", "key_fields": "purchase_request, order_date", "platform_equivalent": "SAP / NetSuite / Workday", "implementation": "Dashboard widget", "widget_id": "w_kpi_prc_002", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(AVG(po.order_date - pr.created::date), 1) AS value FROM reporting.purchase_order po JOIN reporting.purchase_request pr ON pr.name = po.purchase_request WHERE po.docstatus = 1 AND po.order_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'PRC-003', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "PRC-003", "kpi_name": "PR Conversion Rate", "kpi_module": "PROCUREMENT", "sub_area": "Purchase Request", "is_active": true, "definition": "Percentage of approved purchase requests converted into purchase orders", "formula": "COUNT(order_status=''Ordered'') / COUNT(Approved PRs) x100", "unit": "%", "direction": "Up", "target": "≥ 90%", "frequency": "Monthly", "owner_role": "Procurement Manager", "source_doctypes": "PurchaseRequest", "key_fields": "order_status", "platform_equivalent": "SAP", "implementation": "Dashboard widget", "widget_id": "w_kpi_prc_003", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE order_status = ''Ordered'')) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.purchase_request WHERE workflow_state = ''Approved'' AND created::date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'PRC-004', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "PRC-004", "kpi_name": "PR Rejection Rate", "kpi_module": "PROCUREMENT", "sub_area": "Purchase Request", "is_active": true, "definition": "Percentage of submitted purchase requests rejected during workflow", "formula": "COUNT(state=''Rejected'') / COUNT(Submitted PRs) x100", "unit": "%", "direction": "Down", "target": "≤ 10%", "frequency": "Monthly", "owner_role": "Procurement Manager", "source_doctypes": "PurchaseRequest", "key_fields": "workflow_state", "platform_equivalent": "Workday", "implementation": "Dashboard widget", "widget_id": "w_kpi_prc_004", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE workflow_state = ''Rejected'')) / NULLIF(COUNT(*) FILTER (WHERE workflow_state IN (''Approved'',''Rejected'')), 0), 2) AS value FROM reporting.purchase_request WHERE created::date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'PRC-005', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "PRC-005", "kpi_name": "Overdue Purchase Requests", "kpi_module": "PROCUREMENT", "sub_area": "Purchase Request", "is_active": true, "definition": "Unordered purchase requests where the required-by date has passed", "formula": "COUNT(order_status != ''Ordered'' AND required_by < CURRENT_DATE)", "unit": "PRs", "direction": "Down", "target": "0", "frequency": "Weekly", "owner_role": "Buyer", "source_doctypes": "PurchaseRequest", "key_fields": "required_by, order_status", "platform_equivalent": "SAP", "implementation": "Dashboard widget", "widget_id": "w_kpi_prc_005", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT COUNT(*) AS value FROM reporting.purchase_request WHERE workflow_state = ''Approved'' AND order_status <> ''Ordered'' AND required_by < CURRENT_DATE"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'PRC-006', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "PRC-006", "kpi_name": "Total Spend (PO)", "kpi_module": "PROCUREMENT", "sub_area": "Purchase Order", "is_active": true, "definition": "Total monetary value of purchase orders issued and submitted", "formula": "SUM(PurchaseOrder.grand_total, docstatus=1)", "unit": "IDR", "direction": "Range", "target": "Within budget", "frequency": "Monthly", "owner_role": "Procurement Manager", "source_doctypes": "PurchaseOrder", "key_fields": "grand_total", "platform_equivalent": "SAP Ariba Spend; NetSuite; Workday Spend", "implementation": "Dashboard widget", "widget_id": "w_kpi_prc_006", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(COALESCE(SUM(total), 0), 0) AS value FROM reporting.purchase_order WHERE docstatus = 1 AND order_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'PRC-007', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "PRC-007", "kpi_name": "Spend Under Management", "kpi_module": "PROCUREMENT", "sub_area": "Purchase Order", "is_active": true, "definition": "Proportion of total procurement spend routed through formal purchase orders", "formula": "SUM(PI with purchase_order) / SUM(PurchaseInvoice) x100", "unit": "%", "direction": "Up", "target": "≥ 85%", "frequency": "Quarterly", "owner_role": "CPO", "source_doctypes": "PurchaseInvoice, PurchaseOrder", "key_fields": "purchase_order", "platform_equivalent": "SAP Ariba; Workday Strategic Sourcing", "implementation": "Dashboard widget", "widget_id": "w_kpi_prc_007", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (SUM(base_grand_total) FILTER (WHERE purchase_order IS NOT NULL)) / NULLIF(SUM(base_grand_total), 0), 2) AS value FROM reporting.purchase_invoice WHERE docstatus = 1 AND posting_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'PRC-008', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "PRC-008", "kpi_name": "Price Variance PR vs PO", "kpi_module": "PROCUREMENT", "sub_area": "Purchase Order", "is_active": true, "definition": "Percentage price variance between estimated PR cost and negotiated PO price", "formula": "(SUM(PO amount) − SUM(PR amount)) / SUM(PR amount) x100", "unit": "%", "direction": "Down", "target": "≤ 0% (favorable/savings)", "frequency": "Monthly", "owner_role": "Procurement Manager", "source_doctypes": "PurchaseRequestItem, PurchaseOrderItem", "key_fields": "estimated_rate, rate", "platform_equivalent": "SAP", "implementation": "Dashboard widget", "widget_id": "w_kpi_prc_008", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (SUM(po.total) - SUM(pr.total_estimate)) / NULLIF(SUM(pr.total_estimate), 0), 2) AS value FROM reporting.purchase_order po JOIN reporting.purchase_request pr ON pr.name = po.purchase_request WHERE po.docstatus = 1 AND po.order_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'PRC-009', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "PRC-009", "kpi_name": "Procurement Cost Savings", "kpi_module": "PROCUREMENT", "sub_area": "Purchase Order", "is_active": true, "definition": "Direct monetary savings achieved through supplier negotiation below estimates", "formula": "SUM(PR.total_estimate − PO.total) WHERE PO < PR", "unit": "IDR", "direction": "Up", "target": "≥ 3% spend", "frequency": "Quarterly", "owner_role": "CPO", "source_doctypes": "PurchaseRequest, PurchaseOrder", "key_fields": "total_estimate, total", "platform_equivalent": "SAP Ariba Savings", "implementation": "Dashboard widget", "widget_id": "w_kpi_prc_009", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(COALESCE(SUM(GREATEST(pr.total_estimate - po.total, 0)), 0), 0) AS value FROM reporting.purchase_order po JOIN reporting.purchase_request pr ON pr.name = po.purchase_request WHERE po.docstatus = 1 AND po.order_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'PRC-010', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "PRC-010", "kpi_name": "Open PO Value", "kpi_module": "PROCUREMENT", "sub_area": "Purchase Order", "is_active": true, "definition": "Monetary value of committed purchase orders awaiting receipt", "formula": "SUM(grand_total − received_amount) WHERE receipt_status != ''Fully received''", "unit": "IDR", "direction": "Range", "target": "—", "frequency": "Weekly", "owner_role": "Buyer", "source_doctypes": "PurchaseOrder", "key_fields": "received_amount, receipt_status", "platform_equivalent": "SAP ME2N; NetSuite Open PO", "implementation": "Dashboard widget", "widget_id": "w_kpi_prc_010", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT ROUND(COALESCE(SUM(grand_total - COALESCE(received_amount, 0)), 0), 0) AS value FROM reporting.purchase_order WHERE docstatus = 1 AND receipt_status <> ''Fully received''"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'PRC-011', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "PRC-011", "kpi_name": "Unbilled Receipts (GRNI)", "kpi_module": "PROCUREMENT", "sub_area": "Purchase Order", "is_active": true, "definition": "Goods and services received from suppliers awaiting invoice billing", "formula": "SUM(received_amount − billed_amount)", "unit": "IDR", "direction": "Down", "target": "—", "frequency": "Monthly", "owner_role": "AP Lead", "source_doctypes": "PurchaseOrder", "key_fields": "received_amount, billed_amount, billing_status", "platform_equivalent": "SAP GR/IR; NetSuite Accrued Purchases", "implementation": "Dashboard widget", "widget_id": "w_kpi_prc_011", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT ROUND(COALESCE(SUM(GREATEST(COALESCE(received_amount, 0) - COALESCE(billed_amount, 0), 0)), 0), 0) AS value FROM reporting.purchase_order WHERE docstatus = 1"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'PRC-012', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "PRC-012", "kpi_name": "Top 10 Vendor Spend Concentration", "kpi_module": "PROCUREMENT", "sub_area": "Purchase Order", "is_active": true, "definition": "Share of total procurement spend concentrated among the top 10 suppliers", "formula": "SUM(Top 10 vendors) / Total spend x100", "unit": "%", "direction": "Range", "target": "—", "frequency": "Quarterly", "owner_role": "CPO", "source_doctypes": "PurchaseOrder", "key_fields": "vendor, grand_total", "platform_equivalent": "SAP Ariba", "implementation": "Dashboard widget", "widget_id": "w_kpi_prc_012", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "WITH v AS (SELECT vendor, SUM(total) AS s FROM reporting.purchase_order WHERE docstatus = 1 AND order_date BETWEEN @Start AND @End GROUP BY vendor) SELECT ROUND(100.0 * (SELECT SUM(s) FROM (SELECT s FROM v ORDER BY s DESC LIMIT 10) t) / NULLIF((SELECT SUM(s) FROM v), 0), 2) AS value"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'PRC-013', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "PRC-013", "kpi_name": "Spend by Item Group", "kpi_module": "PROCUREMENT", "sub_area": "Purchase Order", "is_active": true, "definition": "Distribution of purchasing spend across item groups and categories", "formula": "SUM(PurchaseOrderItem.amount) GROUP BY Item.item_group", "unit": "IDR", "direction": "Range", "target": "—", "frequency": "Quarterly", "owner_role": "CPO", "source_doctypes": "PurchaseOrderItem, Item, ItemGroup", "key_fields": "item_group", "platform_equivalent": "SAP / Workday", "implementation": "Dashboard widget", "widget_id": "w_kpi_prc_013", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT COALESCE(it.item_group, ''(no group)'') AS label, SUM(i.amount) AS value FROM reporting.purchase_order_items i JOIN reporting.purchase_order po ON po.name = i.parent LEFT JOIN reporting.item it ON it.name = i.item WHERE po.docstatus = 1 AND po.order_date BETWEEN @Start AND @End GROUP BY 1 ORDER BY 2 DESC LIMIT 15"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'PRC-014', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "PRC-014", "kpi_name": "Vendor On-time Delivery Rate", "kpi_module": "PROCUREMENT", "sub_area": "Goods Receipt", "is_active": true, "definition": "Percentage of goods receipts delivered on or before promised PO delivery date", "formula": "COUNT(GoodsReceipt.receipt_date <= PO.delivery_date) / COUNT(GR) x100", "unit": "%", "direction": "Up", "target": "≥ 95%", "frequency": "Monthly", "owner_role": "Procurement Manager", "source_doctypes": "GoodsReceipt, PurchaseOrder", "key_fields": "receipt_date, delivery_date", "platform_equivalent": "SAP Vendor Evaluation; NetSuite", "implementation": "Dashboard widget", "widget_id": "w_kpi_prc_014", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE g.receipt_date <= po.delivery_date)) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.goods_receipt g JOIN reporting.purchase_order po ON po.name = g.purchase_order WHERE g.docstatus = 1 AND g.receipt_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'PRC-015', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "PRC-015", "kpi_name": "Vendor In-full Delivery Rate", "kpi_module": "PROCUREMENT", "sub_area": "Goods Receipt", "is_active": true, "definition": "Percentage of goods receipts meeting full ordered line quantity", "formula": "COUNT(received_qty >= ordered_qty) / COUNT(GR lines) x100", "unit": "%", "direction": "Up", "target": "≥ 98%", "frequency": "Monthly", "owner_role": "Procurement Manager", "source_doctypes": "GoodsReceiptItem", "key_fields": "ordered_qty, received_qty", "platform_equivalent": "SAP", "implementation": "Dashboard widget", "widget_id": "w_kpi_prc_015", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE i.received_qty >= COALESCE(i.pending_qty, i.ordered_qty))) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.goods_receipt_items i JOIN reporting.goods_receipt g ON g.name = i.parent WHERE g.docstatus = 1 AND g.receipt_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'PRC-016', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "PRC-016", "kpi_name": "Vendor OTIF (On-Time In-Full)", "kpi_module": "PROCUREMENT", "sub_area": "Goods Receipt", "is_active": true, "definition": "Supplier deliveries fulfilled completely and strictly on time", "formula": "COUNT(on time AND in full) / COUNT(GR lines) x100", "unit": "%", "direction": "Up", "target": "≥ 92%", "frequency": "Monthly", "owner_role": "Procurement Manager", "source_doctypes": "GoodsReceipt, GoodsReceiptItem, PurchaseOrder", "key_fields": "receipt_date, received_qty", "platform_equivalent": "SAP Supplier Evaluation", "implementation": "Dashboard widget", "widget_id": "w_kpi_prc_016", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE g.receipt_date <= po.delivery_date AND NOT EXISTS (SELECT 1 FROM reporting.goods_receipt_items i WHERE i.parent = g.name AND i.received_qty < COALESCE(i.pending_qty, i.ordered_qty)))) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.goods_receipt g JOIN reporting.purchase_order po ON po.name = g.purchase_order WHERE g.docstatus = 1 AND g.receipt_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'PRC-017', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "PRC-017", "kpi_name": "Quality Rejection Rate", "kpi_module": "PROCUREMENT", "sub_area": "Goods Receipt", "is_active": true, "definition": "Proportion of received goods rejected due to quality inspection failure", "formula": "SUM(rejected_qty) / SUM(received_qty + rejected_qty) x100", "unit": "%", "direction": "Down", "target": "≤ 1%", "frequency": "Monthly", "owner_role": "QC / Procurement", "source_doctypes": "GoodsReceiptItem", "key_fields": "rejected_qty, received_qty", "platform_equivalent": "SAP QM", "implementation": "Dashboard widget", "widget_id": "w_kpi_prc_017", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (SUM(COALESCE(i.rejected_qty, 0))) / NULLIF(SUM(COALESCE(i.received_qty, 0) + COALESCE(i.rejected_qty, 0)), 0), 2) AS value FROM reporting.goods_receipt_items i JOIN reporting.goods_receipt g ON g.name = i.parent WHERE g.docstatus = 1 AND g.receipt_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'PRC-018', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "PRC-018", "kpi_name": "PO Lead Time", "kpi_module": "PROCUREMENT", "sub_area": "Goods Receipt", "is_active": true, "definition": "Average supplier fulfillment lead time in days from order to delivery", "formula": "AVG(receipt_date − order_date)", "unit": "Days", "direction": "Down", "target": "—", "frequency": "Monthly", "owner_role": "Buyer", "source_doctypes": "GoodsReceipt, PurchaseOrder", "key_fields": "order_date, receipt_date", "platform_equivalent": "SAP / NetSuite", "implementation": "Dashboard widget", "widget_id": "w_kpi_prc_018", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(AVG(g.receipt_date - po.order_date), 1) AS value FROM reporting.goods_receipt g JOIN reporting.purchase_order po ON po.name = g.purchase_order WHERE g.docstatus = 1 AND g.receipt_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'PRC-019', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "PRC-019", "kpi_name": "Receipts Without Delivery Note", "kpi_module": "PROCUREMENT", "sub_area": "Goods Receipt", "is_active": true, "definition": "Goods receipts submitted without supplier delivery note number or attachment", "formula": "COUNT(delivery_note_no IS NULL OR document IS NULL) / COUNT(GR) x100", "unit": "%", "direction": "Down", "target": "0%", "frequency": "Monthly", "owner_role": "Warehouse", "source_doctypes": "GoodsReceipt", "key_fields": "delivery_note_no, document", "platform_equivalent": "SAP", "implementation": "Dashboard widget", "widget_id": "w_kpi_prc_019", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE COALESCE(delivery_note_no, '''') = '''')) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.goods_receipt WHERE docstatus = 1 AND receipt_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'PRC-020', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "PRC-020", "kpi_name": "Active Vendors", "kpi_module": "PROCUREMENT", "sub_area": "Vendor", "is_active": true, "definition": "Number of unique vendors with PO transactions in the last 12 months", "formula": "COUNT(DISTINCT vendor POs in last 12 months)", "unit": "Vendors", "direction": "Range", "target": "—", "frequency": "Quarterly", "owner_role": "CPO", "source_doctypes": "Vendor, PurchaseOrder", "key_fields": "is_active", "platform_equivalent": "SAP / NetSuite", "implementation": "Dashboard widget", "widget_id": "w_kpi_prc_020", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT COUNT(DISTINCT vendor) AS value FROM reporting.purchase_order WHERE docstatus = 1 AND order_date > CURRENT_DATE - 365"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'PRC-021', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "PRC-021", "kpi_name": "Vendors On Hold", "kpi_module": "PROCUREMENT", "sub_area": "Vendor", "is_active": true, "definition": "Number of vendor master records blocked from purchasing transactions", "formula": "COUNT(Vendor on_hold=1)", "unit": "Vendors", "direction": "Range", "target": "—", "frequency": "Monthly", "owner_role": "CPO", "source_doctypes": "Vendor", "key_fields": "on_hold", "platform_equivalent": "SAP Vendor Block", "implementation": "Dashboard widget", "widget_id": "w_kpi_prc_021", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT COUNT(*) AS value FROM reporting.vendor WHERE is_active AND on_hold"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'STK-001', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "STK-001", "kpi_name": "Total Inventory Valuation", "kpi_module": "STOCK", "sub_area": "Inventory", "is_active": true, "definition": "Total monetary value of inventory on hand (StockBalanceReport)", "formula": "SUM(qty × valuation_rate) per warehouse", "unit": "IDR", "direction": "Range", "target": "Per company policy", "frequency": "Monthly", "owner_role": "Inventory Controller", "source_doctypes": "StockEntry, GoodsReceiptItem, StockReconciliation (stock ledger)", "key_fields": "valuation_rate", "platform_equivalent": "SAP MB52; NetSuite Inventory Valuation", "implementation": "Built-in report", "builtin_report": "StockBalanceReport", "implementation_note": "Requires stock balance per item (stock ledger), which is not yet exposed to the reporting schema. Use the built-in StockBalanceReport."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'STK-002', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "STK-002", "kpi_name": "Inventory Turnover Ratio", "kpi_module": "STOCK", "sub_area": "Inventory", "is_active": true, "definition": "Cost of goods sold divided by average inventory investment", "formula": "COGS / AVG(Inventory value)", "unit": "Times", "direction": "Up", "target": "≥ 6x/year", "frequency": "Monthly", "owner_role": "Inventory Controller", "source_doctypes": "GL entries, StockSettings", "key_fields": "cogs_account, inventory_account", "platform_equivalent": "SAP / NetSuite", "implementation": "Built-in report", "builtin_report": "StockBalanceReport", "implementation_note": "Requires general ledger data (frogframe_gl_entries), which is not included in the reporting schema and cannot be used by widgets. Use the built-in StockBalanceReport."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'STK-003', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "STK-003", "kpi_name": "DIO (Days Inventory Outstanding)", "kpi_module": "STOCK", "sub_area": "Inventory", "is_active": true, "definition": "Average number of days inventory remains held in stock", "formula": "(Inventory value / COGS) × days in period", "unit": "Days", "direction": "Down", "target": "≤ 60 days", "frequency": "Monthly", "owner_role": "Inventory Controller", "source_doctypes": "GL entries", "key_fields": "inventory_account, cogs_account", "platform_equivalent": "SAP / NetSuite", "implementation": "Built-in report", "builtin_report": "StockBalanceReport", "implementation_note": "Requires general ledger data (frogframe_gl_entries), which is not included in the reporting schema and cannot be used by widgets. Use the built-in StockBalanceReport."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'STK-004', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "STK-004", "kpi_name": "Stock Count Accuracy", "kpi_module": "STOCK", "sub_area": "Inventory", "is_active": true, "definition": "Percentage of stock items with zero physical count discrepancy", "formula": "COUNT(StockReconciliationItem qty_difference=0) / COUNT(Items counted) x100", "unit": "%", "direction": "Up", "target": "≥ 98%", "frequency": "Monthly", "owner_role": "Warehouse", "source_doctypes": "StockReconciliationItem", "key_fields": "qty_difference", "platform_equivalent": "SAP Physical Inventory; NetSuite Count", "implementation": "Dashboard widget", "widget_id": "w_kpi_stk_004", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE COALESCE(i.qty_difference, 0) = 0)) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.stock_reconciliation_items i JOIN reporting.stock_reconciliation r ON r.name = i.parent WHERE r.docstatus = 1 AND r.posting_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'STK-005', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "STK-005", "kpi_name": "Stock Take Variance Value", "kpi_module": "STOCK", "sub_area": "Inventory", "is_active": true, "definition": "Absolute monetary value of physical inventory count adjustments", "formula": "SUM(ABS(amount_difference))", "unit": "IDR", "direction": "Down", "target": "≤ 0.5% stock value", "frequency": "Monthly", "owner_role": "Warehouse", "source_doctypes": "StockReconciliation, StockReconciliationItem", "key_fields": "total_difference, amount_difference", "platform_equivalent": "SAP MI07", "implementation": "Dashboard widget", "widget_id": "w_kpi_stk_005", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT COALESCE(SUM(ABS(i.amount_difference)), 0) AS value FROM reporting.stock_reconciliation_items i JOIN reporting.stock_reconciliation r ON r.name = i.parent WHERE r.docstatus = 1 AND r.posting_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'STK-006', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "STK-006", "kpi_name": "Items Below Reorder Level", "kpi_module": "STOCK", "sub_area": "Inventory", "is_active": true, "definition": "Stock items where available quantity has fallen below reorder point", "formula": "COUNT(Item is_stock_item=1 AND available_qty < reorder_level)", "unit": "Items", "direction": "Down", "target": "0 (PR already exists)", "frequency": "Daily", "owner_role": "Inventory Planner", "source_doctypes": "Item, stock ledger", "key_fields": "reorder_level, reorder_qty", "platform_equivalent": "SAP MRP; NetSuite Reorder Point", "implementation": "Built-in report", "builtin_report": "StockBalanceReport", "implementation_note": "Requires stock balance per item (stock ledger), which is not yet exposed to the reporting schema. Use the built-in StockBalanceReport."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'STK-007', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "STK-007", "kpi_name": "Stock-out Count", "kpi_module": "STOCK", "sub_area": "Inventory", "is_active": true, "definition": "Active stock items completely depleted with zero or negative inventory", "formula": "COUNT(Item is_stock_item=1 AND actual_qty <= 0)", "unit": "Items", "direction": "Down", "target": "0", "frequency": "Daily", "owner_role": "Inventory Planner", "source_doctypes": "Item, stock ledger", "key_fields": "is_stock_item", "platform_equivalent": "SAP / NetSuite", "implementation": "Built-in report", "builtin_report": "StockBalanceReport", "implementation_note": "Requires stock balance per item (stock ledger), which is not yet exposed to the reporting schema. Use the built-in StockBalanceReport."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'STK-008', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "STK-008", "kpi_name": "Negative Stock Incidents", "kpi_module": "STOCK", "sub_area": "Inventory", "is_active": true, "definition": "Stock ledger transaction entries resulting in negative warehouse quantity", "formula": "COUNT(stock ledger balance_qty < 0)", "unit": "Occurrences", "direction": "Down", "target": "0", "frequency": "Daily", "owner_role": "Inventory Controller", "source_doctypes": "StockEntry, StockSettings", "key_fields": "allow_negative_stock", "platform_equivalent": "SAP", "implementation": "Built-in report", "builtin_report": "StockLedgerReport", "implementation_note": "Requires stock balance per item (stock ledger), which is not yet exposed to the reporting schema. Use the built-in StockLedgerReport."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'STK-009', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "STK-009", "kpi_name": "Slow-moving Inventory Value", "kpi_module": "STOCK", "sub_area": "Inventory", "is_active": true, "definition": "Valuation of inventory stock with no turnover movement in over 90 days", "formula": "SUM(value of items without stock movements for > 90 days)", "unit": "IDR", "direction": "Down", "target": "≤ 10% stock value", "frequency": "Monthly", "owner_role": "Inventory Controller", "source_doctypes": "StockEntry, SalesInvoiceItem", "key_fields": "posting_date", "platform_equivalent": "SAP MC46; NetSuite", "implementation": "Built-in report", "builtin_report": "StockLedgerReport", "implementation_note": "Requires stock balance per item (stock ledger), which is not yet exposed to the reporting schema. Use the built-in StockLedgerReport."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'STK-010', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "STK-010", "kpi_name": "Stock Scrappage & Material Issues", "kpi_module": "STOCK", "sub_area": "Inventory", "is_active": true, "definition": "Value of non-sales inventory write-offs and internal consumption issues", "formula": "SUM(StockEntry.total_value WHERE purpose=''Material Issue'')", "unit": "IDR", "direction": "Down", "target": "—", "frequency": "Monthly", "owner_role": "Inventory Controller", "source_doctypes": "StockEntry", "key_fields": "purpose, total_value", "platform_equivalent": "SAP MB1A", "implementation": "Dashboard widget", "widget_id": "w_kpi_stk_010", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT COALESCE(SUM(total_value), 0) AS value FROM reporting.stock_entry WHERE docstatus = 1 AND purpose = ''Material Issue'' AND posting_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'STK-011', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "STK-011", "kpi_name": "Inter-warehouse Transfers", "kpi_module": "STOCK", "sub_area": "Inventory", "is_active": true, "definition": "Value and volume of inventory transferred between internal warehouses", "formula": "COUNT / SUM(total_value WHERE purpose=''Material Transfer'')", "unit": "IDR", "direction": "Range", "target": "—", "frequency": "Monthly", "owner_role": "Warehouse", "source_doctypes": "StockEntry", "key_fields": "purpose, from_warehouse, to_warehouse", "platform_equivalent": "SAP MB1B", "implementation": "Dashboard widget", "widget_id": "w_kpi_stk_011", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT COUNT(*) AS value FROM reporting.stock_entry WHERE docstatus = 1 AND purpose = ''Material Transfer'' AND posting_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'STK-012', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "STK-012", "kpi_name": "Gross Margin by Item", "kpi_module": "STOCK", "sub_area": "Inventory", "is_active": true, "definition": "Gross profit margin percentage achieved per inventory product item", "formula": "SUM(amount − stock_amount) / SUM(amount) x100 per item", "unit": "%", "direction": "Up", "target": "—", "frequency": "Monthly", "owner_role": "Sales Operations", "source_doctypes": "SalesInvoiceItem", "key_fields": "amount, stock_amount, valuation_rate", "platform_equivalent": "NetSuite Item Profitability", "implementation": "Dashboard widget", "widget_id": "w_kpi_stk_012", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT COALESCE(i.item_name, i.item) AS label, ROUND(100.0 * SUM(i.amount - COALESCE(i.stock_amount, 0)) / NULLIF(SUM(i.amount), 0), 2) AS value FROM reporting.sales_invoice_items i JOIN reporting.sales_invoice si ON si.name = i.parent WHERE si.docstatus = 1 AND si.posting_date BETWEEN @Start AND @End AND COALESCE(i.stock_amount, 0) > 0 GROUP BY 1 ORDER BY SUM(i.amount) DESC LIMIT 15"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'CRM-001', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "CRM-001", "kpi_name": "New Lead Volume", "kpi_module": "CRM", "sub_area": "Lead", "is_active": true, "definition": "Total number of new sales leads generated in the period", "formula": "COUNT(Lead created in period)", "unit": "Leads", "direction": "Up", "target": "Per marketing target", "frequency": "Weekly", "owner_role": "Marketing", "source_doctypes": "Lead", "key_fields": "creation, lead_source", "platform_equivalent": "NetSuite CRM; SAP Sales Cloud; M365 Dynamics 365 Sales", "implementation": "Dashboard widget", "widget_id": "w_kpi_crm_001", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT COUNT(*) AS value FROM reporting.lead WHERE created::date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'CRM-002', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "CRM-002", "kpi_name": "Lead Conversion Rate", "kpi_module": "CRM", "sub_area": "Lead", "is_active": true, "definition": "Percentage of leads successfully converted to opportunities or customers", "formula": "COUNT(status=''Converted'') / COUNT(Lead) x100", "unit": "%", "direction": "Up", "target": "≥ 15%", "frequency": "Monthly", "owner_role": "Sales Manager", "source_doctypes": "Lead", "key_fields": "status, converted_on", "platform_equivalent": "Dynamics 365 Sales; SAP Sales Cloud", "implementation": "Dashboard widget", "widget_id": "w_kpi_crm_002", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE status = ''Converted'')) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.lead WHERE created::date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'CRM-003', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "CRM-003", "kpi_name": "Lead Qualification Rate", "kpi_module": "CRM", "sub_area": "Lead", "is_active": true, "definition": "Percentage of leads qualifying as sales-ready (Qualified or Converted)", "formula": "COUNT(status IN (''Qualified'',''Converted'')) / COUNT(Lead) x100", "unit": "%", "direction": "Up", "target": "≥ 30%", "frequency": "Monthly", "owner_role": "Marketing", "source_doctypes": "Lead", "key_fields": "status", "platform_equivalent": "Dynamics 365", "implementation": "Dashboard widget", "widget_id": "w_kpi_crm_003", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE status IN (''Qualified'',''Converted''))) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.lead WHERE created::date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'CRM-004', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "CRM-004", "kpi_name": "Lead Response Time", "kpi_module": "CRM", "sub_area": "Lead", "is_active": true, "definition": "Average hours elapsed from lead creation to initial outreach activity", "formula": "AVG(MIN(Activity.start_at) − Lead.creation)", "unit": "Hours", "direction": "Down", "target": "≤ 24 hours", "frequency": "Weekly", "owner_role": "Sales Manager", "source_doctypes": "Lead, Activity", "key_fields": "reference_name, start_at", "platform_equivalent": "Dynamics 365; NetSuite", "implementation": "Dashboard widget", "widget_id": "w_kpi_crm_004", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(AVG(EXTRACT(EPOCH FROM (f.first_at - l.created)) / 3600.0)::numeric, 1) AS value FROM reporting.lead l JOIN (SELECT reference_name, MIN(start_at) AS first_at FROM reporting.activity WHERE reference_doctype = ''Lead'' AND status <> ''Cancelled'' GROUP BY 1) f ON f.reference_name = l.name WHERE l.created::date BETWEEN @Start AND @End AND f.first_at >= l.created"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'CRM-005', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "CRM-005", "kpi_name": "Time to Convert", "kpi_module": "CRM", "sub_area": "Lead", "is_active": true, "definition": "Average days required from lead generation to formal conversion", "formula": "AVG(converted_on − creation)", "unit": "Days", "direction": "Down", "target": "≤ 30 days", "frequency": "Monthly", "owner_role": "Sales Manager", "source_doctypes": "Lead", "key_fields": "converted_on, creation", "platform_equivalent": "Dynamics 365", "implementation": "Dashboard widget", "widget_id": "w_kpi_crm_005", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(AVG(converted_on - created::date), 1) AS value FROM reporting.lead WHERE status = ''Converted'' AND converted_on BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'CRM-006', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "CRM-006", "kpi_name": "Leads by Source", "kpi_module": "CRM", "sub_area": "Lead", "is_active": true, "definition": "Distribution and conversion efficiency analyzed across lead sources", "formula": "COUNT and conversion rate GROUP BY lead_source", "unit": "%", "direction": "Range", "target": "—", "frequency": "Monthly", "owner_role": "Marketing", "source_doctypes": "Lead, LeadSource", "key_fields": "lead_source", "platform_equivalent": "Dynamics 365 Marketing", "implementation": "Dashboard widget", "widget_id": "w_kpi_crm_006", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT COALESCE(lead_source, ''(blank)'') AS label, COUNT(*) AS value FROM reporting.lead WHERE created::date BETWEEN @Start AND @End GROUP BY 1 ORDER BY 2 DESC"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'CRM-007', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "CRM-007", "kpi_name": "Hot Lead Ratio", "kpi_module": "CRM", "sub_area": "Lead", "is_active": true, "definition": "Percentage of prospective leads categorized with Hot priority rating", "formula": "COUNT(rating=''Hot'') / COUNT(Lead) x100", "unit": "%", "direction": "Up", "target": "—", "frequency": "Monthly", "owner_role": "Marketing", "source_doctypes": "Lead", "key_fields": "rating", "platform_equivalent": "Dynamics 365", "implementation": "Dashboard widget", "widget_id": "w_kpi_crm_007", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE rating = ''Hot'')) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.lead WHERE created::date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'CRM-008', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "CRM-008", "kpi_name": "Unqualified Rate & Reasons", "kpi_module": "CRM", "sub_area": "Lead", "is_active": true, "definition": "Distribution of disqualified leads analyzed by disqualification reason", "formula": "COUNT(status=''Unqualified'') GROUP BY disqualify_reason", "unit": "%", "direction": "Down", "target": "—", "frequency": "Monthly", "owner_role": "Marketing", "source_doctypes": "Lead, LostReason", "key_fields": "disqualify_reason", "platform_equivalent": "Dynamics 365", "implementation": "Dashboard widget", "widget_id": "w_kpi_crm_008", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT COALESCE(disqualify_reason, ''(no reason)'') AS label, COUNT(*) AS value FROM reporting.lead WHERE created::date BETWEEN @Start AND @End AND status = ''Unqualified'' GROUP BY 1 ORDER BY 2 DESC"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'CRM-009', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "CRM-009", "kpi_name": "Unassigned Leads", "kpi_module": "CRM", "sub_area": "Lead", "is_active": true, "definition": "Active prospects without an assigned sales representative owner", "formula": "COUNT(sales_rep IS NULL AND status IN (''New'',''Contacted''))", "unit": "Leads", "direction": "Down", "target": "0", "frequency": "Daily", "owner_role": "Sales Manager", "source_doctypes": "Lead", "key_fields": "sales_rep", "platform_equivalent": "Dynamics 365", "implementation": "Dashboard widget", "widget_id": "w_kpi_crm_009", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT COUNT(*) AS value FROM reporting.lead WHERE sales_rep IS NULL AND status IN (''New'',''Contacted'')"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'CRM-010', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "CRM-010", "kpi_name": "Marketing Campaign ROI", "kpi_module": "CRM", "sub_area": "Campaign", "is_active": true, "definition": "Return on investment achieved from closed-won revenue against campaign cost", "formula": "(won_amount − actual_cost) / actual_cost x100", "unit": "%", "direction": "Up", "target": "≥ 300%", "frequency": "Per campaign", "owner_role": "Marketing", "source_doctypes": "Campaign", "key_fields": "won_amount, actual_cost", "platform_equivalent": "Dynamics 365 Marketing; NetSuite Marketing", "implementation": "Dashboard widget", "widget_id": "w_kpi_crm_010", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (SUM(won_amount) - SUM(actual_cost)) / NULLIF(SUM(actual_cost), 0), 2) AS value FROM reporting.campaign WHERE status <> ''Aborted'' AND start_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'CRM-011', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "CRM-011", "kpi_name": "Cost per Lead (CPL)", "kpi_module": "CRM", "sub_area": "Campaign", "is_active": true, "definition": "Average marketing acquisition cost per generated lead", "formula": "actual_cost / lead_count", "unit": "IDR", "direction": "Down", "target": "—", "frequency": "Per campaign", "owner_role": "Marketing", "source_doctypes": "Campaign", "key_fields": "actual_cost, lead_count", "platform_equivalent": "Dynamics 365", "implementation": "Dashboard widget", "widget_id": "w_kpi_crm_011", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(SUM(actual_cost) / NULLIF(SUM(lead_count), 0), 0) AS value FROM reporting.campaign WHERE status <> ''Aborted'' AND start_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'CRM-012', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "CRM-012", "kpi_name": "Campaign Budget Variance", "kpi_module": "CRM", "sub_area": "Campaign", "is_active": true, "definition": "Percentage variance between actual campaign expenditure and budget", "formula": "(actual_cost − budgeted_cost) / budgeted_cost x100", "unit": "%", "direction": "Range", "target": "± 10%", "frequency": "Per campaign", "owner_role": "Marketing", "source_doctypes": "Campaign", "key_fields": "actual_cost, budgeted_cost", "platform_equivalent": "Dynamics 365", "implementation": "Dashboard widget", "widget_id": "w_kpi_crm_012", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (SUM(actual_cost) - SUM(budgeted_cost)) / NULLIF(SUM(budgeted_cost), 0), 2) AS value FROM reporting.campaign WHERE status <> ''Aborted'' AND start_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'CRM-013', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "CRM-013", "kpi_name": "Campaign Revenue Attainment", "kpi_module": "CRM", "sub_area": "Campaign", "is_active": true, "definition": "Won opportunity revenue realized against initial campaign projection", "formula": "won_amount / expected_revenue x100", "unit": "%", "direction": "Up", "target": "≥ 100%", "frequency": "Per campaign", "owner_role": "Marketing", "source_doctypes": "Campaign", "key_fields": "won_amount, expected_revenue", "platform_equivalent": "Dynamics 365", "implementation": "Dashboard widget", "widget_id": "w_kpi_crm_013", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (SUM(won_amount)) / NULLIF(SUM(expected_revenue), 0), 2) AS value FROM reporting.campaign WHERE status <> ''Aborted'' AND start_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'CRM-014', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "CRM-014", "kpi_name": "Campaign Lead-to-Opportunity Rate", "kpi_module": "CRM", "sub_area": "Campaign", "is_active": true, "definition": "Proportion of campaign leads converted into formal sales opportunities", "formula": "opportunity_count / lead_count x100", "unit": "%", "direction": "Up", "target": "≥ 20%", "frequency": "Per campaign", "owner_role": "Marketing", "source_doctypes": "Campaign", "key_fields": "opportunity_count, lead_count", "platform_equivalent": "Dynamics 365", "implementation": "Dashboard widget", "widget_id": "w_kpi_crm_014", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (SUM(opportunity_count)) / NULLIF(SUM(lead_count), 0), 2) AS value FROM reporting.campaign WHERE status <> ''Aborted'' AND start_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'CRM-015', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "CRM-015", "kpi_name": "Total Pipeline Value", "kpi_module": "CRM", "sub_area": "Opportunity", "is_active": true, "definition": "Total aggregate potential value of open sales opportunities", "formula": "SUM(amount WHERE stage_type=''Open'')", "unit": "IDR", "direction": "Up", "target": "≥ 3x quarterly quota", "frequency": "Weekly", "owner_role": "Sales Director", "source_doctypes": "Opportunity, SalesStage", "key_fields": "amount, stage_type", "platform_equivalent": "Dynamics 365 Sales; SAP Sales Cloud; NetSuite Opportunities", "implementation": "Dashboard widget", "widget_id": "w_kpi_crm_015", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT COALESCE(SUM(amount), 0) AS value FROM reporting.opportunity WHERE stage_type = ''Open''"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'CRM-016', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "CRM-016", "kpi_name": "Weighted Pipeline Value", "kpi_module": "CRM", "sub_area": "Opportunity", "is_active": true, "definition": "Probability-weighted forecast value of open sales pipeline", "formula": "SUM(weighted_amount) WHERE stage_type=''Open''", "unit": "IDR", "direction": "Up", "target": "≥ quarterly quota", "frequency": "Weekly", "owner_role": "Sales Director", "source_doctypes": "Opportunity", "key_fields": "weighted_amount, probability", "platform_equivalent": "Dynamics 365 Forecast", "implementation": "Dashboard widget", "widget_id": "w_kpi_crm_016", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT COALESCE(SUM(weighted_amount), 0) AS value FROM reporting.opportunity WHERE stage_type = ''Open''"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'CRM-017', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "CRM-017", "kpi_name": "Pipeline Coverage Ratio", "kpi_module": "CRM", "sub_area": "Opportunity", "is_active": true, "definition": "Open pipeline revenue multiple relative to periodic sales quota", "formula": "Pipeline value / Quota target for period", "unit": "Ratio", "direction": "Up", "target": "≥ 3x", "frequency": "Monthly", "owner_role": "Sales Director", "source_doctypes": "Opportunity", "key_fields": "amount", "platform_equivalent": "Dynamics 365", "implementation": "Built-in report", "builtin_report": "SalesPipelineReport", "implementation_note": "Requires sales targets per period, for which no DocType currently exists. Use the built-in SalesPipelineReport."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'CRM-018', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "CRM-018", "kpi_name": "Opportunity Win Rate", "kpi_module": "CRM", "sub_area": "Opportunity", "is_active": true, "definition": "Percentage of closed opportunities won by deal count", "formula": "COUNT(stage_type=''Won'') / COUNT(stage_type IN (''Won'',''Lost'')) x100", "unit": "%", "direction": "Up", "target": "≥ 25%", "frequency": "Monthly", "owner_role": "Sales Director", "source_doctypes": "Opportunity", "key_fields": "stage_type", "platform_equivalent": "Dynamics 365; SAP; NetSuite", "implementation": "Dashboard widget", "widget_id": "w_kpi_crm_018", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE stage_type = ''Won'')) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.opportunity WHERE stage_type IN (''Won'',''Lost'') AND closed_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'CRM-019', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "CRM-019", "kpi_name": "Win Rate by Value", "kpi_module": "CRM", "sub_area": "Opportunity", "is_active": true, "definition": "Percentage of closed opportunity value won in currency", "formula": "SUM(amount Won) / SUM(amount Won + Lost) x100", "unit": "%", "direction": "Up", "target": "≥ 25%", "frequency": "Monthly", "owner_role": "Sales Director", "source_doctypes": "Opportunity", "key_fields": "amount, stage_type", "platform_equivalent": "Dynamics 365", "implementation": "Dashboard widget", "widget_id": "w_kpi_crm_019", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (SUM(amount) FILTER (WHERE stage_type = ''Won'')) / NULLIF(SUM(amount), 0), 2) AS value FROM reporting.opportunity WHERE stage_type IN (''Won'',''Lost'') AND closed_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'CRM-020', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "CRM-020", "kpi_name": "Average Deal Size", "kpi_module": "CRM", "sub_area": "Opportunity", "is_active": true, "definition": "Average monetary contract value of closed-won opportunities", "formula": "AVG(amount WHERE stage_type=''Won'')", "unit": "IDR", "direction": "Up", "target": "Increase QoQ", "frequency": "Monthly", "owner_role": "Sales Director", "source_doctypes": "Opportunity", "key_fields": "amount", "platform_equivalent": "Dynamics 365", "implementation": "Dashboard widget", "widget_id": "w_kpi_crm_020", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(AVG(amount), 0) AS value FROM reporting.opportunity WHERE stage_type IN (''Won'',''Lost'') AND closed_date BETWEEN @Start AND @End AND stage_type = ''Won''"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'CRM-021', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "CRM-021", "kpi_name": "Sales Cycle Length", "kpi_module": "CRM", "sub_area": "Opportunity", "is_active": true, "definition": "Average elapsed days from opportunity creation to Won closing date", "formula": "AVG(closed_date − creation)", "unit": "Days", "direction": "Down", "target": "≤ 60 days", "frequency": "Monthly", "owner_role": "Sales Director", "source_doctypes": "Opportunity", "key_fields": "closed_date, creation", "platform_equivalent": "Dynamics 365", "implementation": "Dashboard widget", "widget_id": "w_kpi_crm_021", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(AVG(closed_date - created::date), 1) AS value FROM reporting.opportunity WHERE stage_type IN (''Won'',''Lost'') AND closed_date BETWEEN @Start AND @End AND stage_type = ''Won''"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'CRM-022', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "CRM-022", "kpi_name": "Sales Velocity", "kpi_module": "CRM", "sub_area": "Opportunity", "is_active": true, "definition": "Expected revenue velocity ($/day = Opportunities × Win Rate × Deal Size / Cycle)", "formula": "(# open opportunities × win rate × avg deal size) / avg cycle length", "unit": "IDR/day", "direction": "Up", "target": "Increase QoQ", "frequency": "Monthly", "owner_role": "Sales Director", "source_doctypes": "Opportunity", "key_fields": "—", "platform_equivalent": "Dynamics 365", "implementation": "Dashboard widget", "widget_id": "w_kpi_crm_022", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "WITH c AS (SELECT COUNT(*) FILTER (WHERE stage_type = ''Won'')::numeric / NULLIF(COUNT(*), 0) AS win_rate, AVG(amount) FILTER (WHERE stage_type = ''Won'') AS deal, AVG(closed_date - created::date) FILTER (WHERE stage_type = ''Won'') AS cycle FROM reporting.opportunity WHERE stage_type IN (''Won'',''Lost'') AND closed_date BETWEEN @Start AND @End) SELECT ROUND((SELECT COUNT(*) FROM reporting.opportunity WHERE stage_type = ''Open'') * c.win_rate * c.deal / NULLIF(c.cycle, 0), 0) AS value FROM c"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'CRM-023', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "CRM-023", "kpi_name": "Stale Opportunities", "kpi_module": "CRM", "sub_area": "Opportunity", "is_active": true, "definition": "Open opportunities with no activity or updates beyond configured threshold", "formula": "COUNT(stage_type=''Open'' AND modified < CURRENT_DATE − stale_days)", "unit": "Opportunities", "direction": "Down", "target": "0", "frequency": "Weekly", "owner_role": "Sales Manager", "source_doctypes": "Opportunity, CRMSettings", "key_fields": "modified, stale_opportunity_days", "platform_equivalent": "Dynamics 365", "implementation": "Dashboard widget", "widget_id": "w_kpi_crm_023", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT COUNT(*) AS value FROM reporting.opportunity WHERE stage_type = ''Open'' AND modified < now() - make_interval(days => COALESCE((SELECT MAX(stale_opportunity_days) FROM reporting.crmsettings), 30)::int)"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'CRM-024', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "CRM-024", "kpi_name": "Overdue Close Date Opportunities", "kpi_module": "CRM", "sub_area": "Opportunity", "is_active": true, "definition": "Open sales opportunities where target close date has expired", "formula": "COUNT(stage_type=''Open'' AND expected_close_date < CURRENT_DATE)", "unit": "Opportunities", "direction": "Down", "target": "0", "frequency": "Weekly", "owner_role": "Sales Manager", "source_doctypes": "Opportunity", "key_fields": "expected_close_date", "platform_equivalent": "Dynamics 365", "implementation": "Dashboard widget", "widget_id": "w_kpi_crm_024", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT COUNT(*) AS value FROM reporting.opportunity WHERE stage_type = ''Open'' AND expected_close_date < CURRENT_DATE"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'CRM-025', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "CRM-025", "kpi_name": "Lost Deal Reason Analysis", "kpi_module": "CRM", "sub_area": "Opportunity", "is_active": true, "definition": "Distribution of lost opportunities categorized by primary lost reason", "formula": "COUNT(stage_type=''Lost'') GROUP BY lost_reason", "unit": "%", "direction": "Range", "target": "—", "frequency": "Quarterly", "owner_role": "Sales Director", "source_doctypes": "Opportunity, LostReason", "key_fields": "lost_reason", "platform_equivalent": "Dynamics 365", "implementation": "Dashboard widget", "widget_id": "w_kpi_crm_025", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT COALESCE(lost_reason, ''(no reason)'') AS label, COUNT(*) AS value FROM reporting.opportunity WHERE stage_type IN (''Won'',''Lost'') AND closed_date BETWEEN @Start AND @End AND stage_type = ''Lost'' GROUP BY 1 ORDER BY 2 DESC"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'CRM-026', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "CRM-026", "kpi_name": "Competitive Win Rate", "kpi_module": "CRM", "sub_area": "Opportunity", "is_active": true, "definition": "Win rate achieved on competitive deals with named rivals involved", "formula": "Win rate WHERE competitor IS NOT NULL", "unit": "%", "direction": "Up", "target": "—", "frequency": "Quarterly", "owner_role": "Sales Director", "source_doctypes": "Opportunity", "key_fields": "competitor", "platform_equivalent": "Dynamics 365", "implementation": "Dashboard widget", "widget_id": "w_kpi_crm_026", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE stage_type = ''Won'')) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.opportunity WHERE stage_type IN (''Won'',''Lost'') AND closed_date BETWEEN @Start AND @End AND COALESCE(competitor, '''') <> ''''"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'CRM-027', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "CRM-027", "kpi_name": "Sales Stage Conversion Rate", "kpi_module": "CRM", "sub_area": "Opportunity", "is_active": true, "definition": "Progression conversion rate between sequential pipeline stages", "formula": "COUNT(reached stage n+1) / COUNT(entered stage n)", "unit": "%", "direction": "Up", "target": "—", "frequency": "Monthly", "owner_role": "Sales Manager", "source_doctypes": "Opportunity, SalesStage", "key_fields": "sales_stage, sequence", "platform_equivalent": "Dynamics 365 Funnel", "implementation": "Not available", "implementation_note": "Requires workflow transition timestamps per document (version/audit trail), which are not yet exposed to the reporting schema."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'CRM-028', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "CRM-028", "kpi_name": "Forecast Category Mix", "kpi_module": "CRM", "sub_area": "Opportunity", "is_active": true, "definition": "Pipeline value distribution across forecast tiers (Commit / Best Case / Pipeline)", "formula": "SUM(amount) GROUP BY forecast_category", "unit": "IDR", "direction": "Range", "target": "—", "frequency": "Weekly", "owner_role": "Sales Director", "source_doctypes": "Opportunity", "key_fields": "forecast_category", "platform_equivalent": "Dynamics 365 Forecasting", "implementation": "Dashboard widget", "widget_id": "w_kpi_crm_028", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT COALESCE(forecast_category, ''(blank)'') AS label, SUM(amount) AS value FROM reporting.opportunity WHERE stage_type = ''Open'' GROUP BY 1 ORDER BY 2 DESC"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'CRM-029', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "CRM-029", "kpi_name": "Buying Committee Multithreading", "kpi_module": "CRM", "sub_area": "Opportunity", "is_active": true, "definition": "Percentage of open enterprise deals with two or more stakeholder contact roles", "formula": "COUNT(contact_roles >= 2) / COUNT(open) x100", "unit": "%", "direction": "Up", "target": "≥ 70%", "frequency": "Monthly", "owner_role": "Sales Manager", "source_doctypes": "Opportunity, OpportunityContactRole", "key_fields": "contact_roles, role", "platform_equivalent": "Dynamics 365 / Salesforce-like", "implementation": "Dashboard widget", "widget_id": "w_kpi_crm_029", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE (SELECT COUNT(*) FROM reporting.opportunity_contact_roles r WHERE r.parent = o.name) >= 2)) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.opportunity o WHERE o.stage_type = ''Open''"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'CRM-030', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "CRM-030", "kpi_name": "Quote-to-Order Conversion", "kpi_module": "CRM", "sub_area": "Quotation", "is_active": true, "definition": "Percentage of customer quotations converted into confirmed sales orders", "formula": "COUNT(SalesOrder with quotation) / COUNT(Submitted Quotations) x100", "unit": "%", "direction": "Up", "target": "≥ 40%", "frequency": "Monthly", "owner_role": "Sales Manager", "source_doctypes": "Quotation, SalesOrder", "key_fields": "quotation", "platform_equivalent": "NetSuite Estimate→SO; SAP VA21→VA01", "implementation": "Dashboard widget", "widget_id": "w_kpi_crm_030", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE EXISTS (SELECT 1 FROM reporting.sales_order so WHERE so.quotation = q.name AND so.docstatus = 1))) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.quotation q WHERE q.workflow_state NOT IN (''Draft'',''Cancelled'') AND q.quotation_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'CRM-031', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "CRM-031", "kpi_name": "Expired Quotations", "kpi_module": "CRM", "sub_area": "Quotation", "is_active": true, "definition": "Quotations past valid-until date without customer acceptance or order", "formula": "COUNT(workflow_state=''Expired'' OR (workflow_state=''Sent'' AND valid_until < CURRENT_DATE))", "unit": "Quotations", "direction": "Down", "target": "0", "frequency": "Weekly", "owner_role": "Sales Manager", "source_doctypes": "Quotation", "key_fields": "valid_until, workflow_state", "platform_equivalent": "SAP / NetSuite", "implementation": "Dashboard widget", "widget_id": "w_kpi_crm_031", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT COUNT(*) AS value FROM reporting.quotation WHERE workflow_state = ''Expired'' OR (workflow_state = ''Sent'' AND valid_until < CURRENT_DATE)"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'CRM-032', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "CRM-032", "kpi_name": "Average Quotation Discount", "kpi_module": "CRM", "sub_area": "Quotation", "is_active": true, "definition": "Average percentage discount extended on quotation line items", "formula": "AVG(QuotationItem.discount_percent)", "unit": "%", "direction": "Down", "target": "≤ discount policy", "frequency": "Monthly", "owner_role": "Sales Operations", "source_doctypes": "QuotationItem", "key_fields": "discount_percent", "platform_equivalent": "SAP Pricing; NetSuite", "implementation": "Dashboard widget", "widget_id": "w_kpi_crm_032", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(AVG(COALESCE(i.discount_percent, 0)), 2) AS value FROM reporting.quotation_items i JOIN reporting.quotation q ON q.name = i.parent WHERE q.workflow_state NOT IN (''Draft'',''Cancelled'') AND q.quotation_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'CRM-033', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "CRM-033", "kpi_name": "Quotation Approval Turnaround", "kpi_module": "CRM", "sub_area": "Quotation", "is_active": true, "definition": "Average workflow turnaround duration for quotation approval cycles", "formula": "AVG(Draft to Sent duration in QuotationLifecycle workflow)", "unit": "Hours", "direction": "Down", "target": "≤ 24 hours", "frequency": "Monthly", "owner_role": "Sales Operations", "source_doctypes": "Quotation", "key_fields": "workflow_state", "platform_equivalent": "SAP / Dynamics", "implementation": "Not available", "implementation_note": "Requires workflow transition timestamps per document (version/audit trail), which are not yet exposed to the reporting schema."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'CRM-034', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "CRM-034", "kpi_name": "Time to Quote", "kpi_module": "CRM", "sub_area": "Quotation", "is_active": true, "definition": "Days required from opportunity discovery to initial quote presentation", "formula": "AVG(Quotation.quotation_date − Opportunity.creation)", "unit": "Days", "direction": "Down", "target": "≤ 3 days", "frequency": "Monthly", "owner_role": "Sales Manager", "source_doctypes": "Quotation, Opportunity", "key_fields": "opportunity, quotation_date", "platform_equivalent": "Dynamics 365", "implementation": "Dashboard widget", "widget_id": "w_kpi_crm_034", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(AVG(f.first_q - o.created::date), 1) AS value FROM reporting.opportunity o JOIN (SELECT opportunity, MIN(quotation_date) AS first_q FROM reporting.quotation WHERE workflow_state <> ''Cancelled'' AND opportunity IS NOT NULL GROUP BY 1) f ON f.opportunity = o.name WHERE f.first_q BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'CRM-035', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "CRM-035", "kpi_name": "Bookings (Sales Order Value)", "kpi_module": "CRM", "sub_area": "Sales Order", "is_active": true, "definition": "Total gross monetary bookings confirmed via submitted sales orders", "formula": "SUM(SalesOrder.grand_total, docstatus=1)", "unit": "IDR", "direction": "Up", "target": "Per target", "frequency": "Weekly", "owner_role": "Sales Director", "source_doctypes": "SalesOrder", "key_fields": "grand_total", "platform_equivalent": "NetSuite / SAP / Dynamics", "implementation": "Dashboard widget", "widget_id": "w_kpi_crm_035", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT COALESCE(SUM(total), 0) AS value FROM reporting.sales_order WHERE docstatus = 1 AND order_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'CRM-036', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "CRM-036", "kpi_name": "Sales Order Backlog (Unbilled)", "kpi_module": "CRM", "sub_area": "Sales Order", "is_active": true, "definition": "Confirmed customer order value pending final billing fulfillment", "formula": "SUM(grand_total − billed_amount) WHERE billing_status != ''Fully billed''", "unit": "IDR", "direction": "Range", "target": "—", "frequency": "Weekly", "owner_role": "Sales Operations", "source_doctypes": "SalesOrder", "key_fields": "billed_amount, billing_status", "platform_equivalent": "SAP VA05; NetSuite Sales Orders to Bill", "implementation": "Dashboard widget", "widget_id": "w_kpi_crm_036", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT COALESCE(SUM(grand_total - COALESCE(billed_amount, 0)), 0) AS value FROM reporting.sales_order WHERE docstatus = 1 AND billing_status <> ''Fully billed''"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'CRM-037', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "CRM-037", "kpi_name": "Order-to-Invoice Cycle Time", "kpi_module": "CRM", "sub_area": "Sales Order", "is_active": true, "definition": "Average days between sales order confirmation and primary invoice issuance", "formula": "AVG(SalesInvoice.posting_date − SalesOrder.order_date)", "unit": "Days", "direction": "Down", "target": "≤ 7 days", "frequency": "Monthly", "owner_role": "Sales Operations", "source_doctypes": "SalesOrder, SalesInvoice", "key_fields": "sales_order, order_date", "platform_equivalent": "SAP / NetSuite", "implementation": "Dashboard widget", "widget_id": "w_kpi_crm_037", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(AVG(f.first_inv - so.order_date), 1) AS value FROM reporting.sales_order so JOIN (SELECT sales_order, MIN(posting_date) AS first_inv FROM reporting.sales_invoice WHERE docstatus = 1 AND sales_order IS NOT NULL GROUP BY 1) f ON f.sales_order = so.name WHERE so.docstatus = 1 AND f.first_inv BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'CRM-038', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "CRM-038", "kpi_name": "On-time Delivery to Customer", "kpi_module": "CRM", "sub_area": "Sales Order", "is_active": true, "definition": "Sales orders delivered on or before customer promised delivery date", "formula": "COUNT(delivery <= delivery_date) / COUNT(SalesOrder) x100", "unit": "%", "direction": "Up", "target": "≥ 95%", "frequency": "Monthly", "owner_role": "Operations", "source_doctypes": "SalesOrder, StockEntry", "key_fields": "delivery_date", "platform_equivalent": "SAP / NetSuite", "implementation": "Not available", "implementation_note": "No delivery note document exists recording dispatch dates to customers."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'CRM-039', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "CRM-039", "kpi_name": "Sales Revenue by Representative", "kpi_module": "CRM", "sub_area": "Sales Order", "is_active": true, "definition": "Net invoiced sales volume achieved per individual sales representative", "formula": "SUM(SalesInvoice.tax_base) GROUP BY sales_rep", "unit": "IDR", "direction": "Up", "target": "Per sales quota", "frequency": "Monthly", "owner_role": "Sales Director", "source_doctypes": "SalesInvoice", "key_fields": "sales_rep", "platform_equivalent": "Dynamics 365; NetSuite Sales Rep", "implementation": "Dashboard widget", "widget_id": "w_kpi_crm_039", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT COALESCE(si.sales_rep, ''(no sales)'') AS label, ROUND(SUM(si.total * si.exchange_rate), 0) AS value FROM reporting.sales_invoice si WHERE si.docstatus = 1 AND si.posting_date BETWEEN @Start AND @End GROUP BY 1 ORDER BY 2 DESC LIMIT 15"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'CRM-040', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "CRM-040", "kpi_name": "Sales Revenue by Territory", "kpi_module": "CRM", "sub_area": "Sales Order", "is_active": true, "definition": "Invoiced sales performance distributed across geographic territories", "formula": "SUM(SalesInvoice.tax_base) GROUP BY Customer.territory", "unit": "IDR", "direction": "Up", "target": "—", "frequency": "Monthly", "owner_role": "Sales Director", "source_doctypes": "SalesInvoice, Customer, Territory", "key_fields": "territory", "platform_equivalent": "Dynamics 365; SAP", "implementation": "Dashboard widget", "widget_id": "w_kpi_crm_040", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT COALESCE(c.territory, ''(no territory)'') AS label, ROUND(SUM(si.total * si.exchange_rate), 0) AS value FROM reporting.sales_invoice si LEFT JOIN reporting.customer c ON c.name = si.customer WHERE si.docstatus = 1 AND si.posting_date BETWEEN @Start AND @End GROUP BY 1 ORDER BY 2 DESC"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'CRM-041', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "CRM-041", "kpi_name": "Active Customer Count", "kpi_module": "CRM", "sub_area": "Customer", "is_active": true, "definition": "Number of unique customer accounts with invoice activity in the last 12 months", "formula": "COUNT(DISTINCT customer SalesInvoices in last 12 months)", "unit": "Customers", "direction": "Up", "target": "Increase YoY", "frequency": "Quarterly", "owner_role": "Sales Director", "source_doctypes": "Customer, SalesInvoice", "key_fields": "customer", "platform_equivalent": "Semua platform", "implementation": "Dashboard widget", "widget_id": "w_kpi_crm_041", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT COUNT(DISTINCT customer) AS value FROM reporting.sales_invoice WHERE docstatus = 1 AND posting_date > CURRENT_DATE - 365"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'CRM-042', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "CRM-042", "kpi_name": "New Customer Acquisition", "kpi_module": "CRM", "sub_area": "Customer", "is_active": true, "definition": "First-time purchasing customer logos acquiring their inaugural invoice", "formula": "COUNT(customers with MIN(posting_date) in period)", "unit": "Customers", "direction": "Up", "target": "Per target", "frequency": "Monthly", "owner_role": "Sales Director", "source_doctypes": "Customer, SalesInvoice", "key_fields": "customer, posting_date", "platform_equivalent": "Dynamics 365", "implementation": "Dashboard widget", "widget_id": "w_kpi_crm_042", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT COUNT(*) AS value FROM (SELECT customer, MIN(posting_date) AS first_inv FROM reporting.sales_invoice WHERE docstatus = 1 GROUP BY 1) f WHERE f.first_inv BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'CRM-043', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "CRM-043", "kpi_name": "Customer Retention Rate", "kpi_module": "CRM", "sub_area": "Customer", "is_active": true, "definition": "Percentage of prior-year active customer accounts retained this year", "formula": "COUNT(active customers in current year ∩ prior year) / COUNT(prior year) x100", "unit": "%", "direction": "Up", "target": "≥ 85%", "frequency": "Annual", "owner_role": "Sales Director", "source_doctypes": "SalesInvoice", "key_fields": "customer", "platform_equivalent": "Dynamics 365", "implementation": "Dashboard widget", "widget_id": "w_kpi_crm_043", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE customer IN (SELECT customer FROM reporting.sales_invoice WHERE docstatus = 1 AND posting_date BETWEEN @Start AND @End))) / NULLIF(COUNT(*), 0), 2) AS value FROM (SELECT DISTINCT customer FROM reporting.sales_invoice WHERE docstatus = 1 AND posting_date >= @Start::date - 365 AND posting_date < @Start) prev"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'CRM-044', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "CRM-044", "kpi_name": "Top 10 Customer Revenue Concentration", "kpi_module": "CRM", "sub_area": "Customer", "is_active": true, "definition": "Share of total company revenue contributed by top 10 customer accounts", "formula": "SUM(Top 10 customer revenue) / Total revenue x100", "unit": "%", "direction": "Down", "target": "≤ 40%", "frequency": "Quarterly", "owner_role": "CFO", "source_doctypes": "SalesInvoice", "key_fields": "customer", "platform_equivalent": "NetSuite / SAP", "implementation": "Dashboard widget", "widget_id": "w_kpi_crm_044", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "WITH c AS (SELECT si.customer, SUM(si.total * si.exchange_rate) AS s FROM reporting.sales_invoice si WHERE si.docstatus = 1 AND si.posting_date BETWEEN @Start AND @End GROUP BY 1) SELECT ROUND(100.0 * (SELECT SUM(s) FROM (SELECT s FROM c ORDER BY s DESC LIMIT 10) t) / NULLIF((SELECT SUM(s) FROM c), 0), 2) AS value"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'CRM-045', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "CRM-045", "kpi_name": "Active Contract Value (ACV)", "kpi_module": "CRM", "sub_area": "Contract", "is_active": true, "definition": "Total aggregate annualized monetary value of active customer contracts", "formula": "SUM(contract_value WHERE contract_status=''Active'')", "unit": "IDR", "direction": "Up", "target": "—", "frequency": "Monthly", "owner_role": "Sales Operations", "source_doctypes": "CustomerContract", "key_fields": "contract_value, contract_status", "platform_equivalent": "SAP Contract Mgmt; NetSuite SuiteBilling", "implementation": "Dashboard widget", "widget_id": "w_kpi_crm_045", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT COALESCE(SUM(contract_value), 0) AS value FROM reporting.customer_contract WHERE docstatus = 1 AND contract_status IN (''Active'',''Expiring soon'')"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'CRM-046', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "CRM-046", "kpi_name": "Expiring Customer Contracts", "kpi_module": "CRM", "sub_area": "Contract", "is_active": true, "definition": "Active revenue contracts scheduled to terminate within advance notice window", "formula": "COUNT(contract_status IN (''Active'',''Expiring soon'') AND end_date <= CURRENT_DATE + notice_days)", "unit": "Contracts", "direction": "Range", "target": "All contacted", "frequency": "Weekly", "owner_role": "Account Manager", "source_doctypes": "CustomerContract", "key_fields": "end_date, notice_days", "platform_equivalent": "SAP / NetSuite", "implementation": "Dashboard widget", "widget_id": "w_kpi_crm_046", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT COUNT(*) AS value FROM reporting.customer_contract WHERE docstatus = 1 AND contract_status IN (''Active'',''Expiring soon'') AND end_date BETWEEN CURRENT_DATE AND CURRENT_DATE + COALESCE(notice_days, 30)::int"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'CRM-047', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "CRM-047", "kpi_name": "Customer Contract Renewal Rate", "kpi_module": "CRM", "sub_area": "Contract", "is_active": true, "definition": "Percentage of concluding customer contracts successfully renewed", "formula": "COUNT(contract_status=''Renewed'') / COUNT(status IN (''Renewed'',''Expired'')) x100", "unit": "%", "direction": "Up", "target": "≥ 85%", "frequency": "Quarterly", "owner_role": "Account Manager", "source_doctypes": "CustomerContract", "key_fields": "contract_status, renewal_of", "platform_equivalent": "NetSuite SuiteBilling Renewals", "implementation": "Dashboard widget", "widget_id": "w_kpi_crm_047", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE contract_status = ''Renewed'')) / NULLIF(COUNT(*) FILTER (WHERE contract_status IN (''Renewed'',''Expired'')), 0), 2) AS value FROM reporting.customer_contract WHERE docstatus = 1 AND end_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'CRM-048', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "CRM-048", "kpi_name": "Contract Revenue Churn Rate", "kpi_module": "CRM", "sub_area": "Contract", "is_active": true, "definition": "Annualized recurring contract value lost through expiration or cancellation", "formula": "SUM(contract_value status IN (''Expired'',''Cancelled'')) / baseline contract value x100", "unit": "%", "direction": "Down", "target": "≤ 10%", "frequency": "Quarterly", "owner_role": "Sales Director", "source_doctypes": "CustomerContract", "key_fields": "contract_value, contract_status", "platform_equivalent": "NetSuite / SAP", "implementation": "Dashboard widget", "widget_id": "w_kpi_crm_048", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (SUM(contract_value) FILTER (WHERE contract_status IN (''Expired'',''Cancelled''))) / NULLIF(SUM(contract_value), 0), 2) AS value FROM reporting.customer_contract WHERE docstatus IN (1, 2) AND end_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'CRM-049', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "CRM-049", "kpi_name": "Auto-renewal Contract Ratio", "kpi_module": "CRM", "sub_area": "Contract", "is_active": true, "definition": "Percentage of customer service contracts containing evergreen auto-renewal clauses", "formula": "COUNT(auto_renew=1) / COUNT(Active contracts) x100", "unit": "%", "direction": "Up", "target": "—", "frequency": "Quarterly", "owner_role": "Sales Operations", "source_doctypes": "CustomerContract", "key_fields": "auto_renew", "platform_equivalent": "NetSuite", "implementation": "Dashboard widget", "widget_id": "w_kpi_crm_049", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE auto_renew)) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.customer_contract WHERE docstatus = 1 AND contract_status IN (''Active'',''Expiring soon'')"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'CRM-050', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "CRM-050", "kpi_name": "Activities per Sales Representative", "kpi_module": "CRM", "sub_area": "Activity", "is_active": true, "definition": "Completed customer touchpoints (meetings, calls, tasks) per sales rep", "formula": "COUNT(Activity status=''Completed'') GROUP BY assigned_to", "unit": "Activities", "direction": "Up", "target": "≥ 40/week", "frequency": "Weekly", "owner_role": "Sales Manager", "source_doctypes": "Activity", "key_fields": "status, assigned_to, activity_type", "platform_equivalent": "Dynamics 365; M365 Outlook/Teams", "implementation": "Dashboard widget", "widget_id": "w_kpi_crm_050", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT COALESCE(assigned_to, ''(unassigned)'') AS label, COUNT(*) AS value FROM reporting.activity WHERE status = ''Completed'' AND start_at::date BETWEEN @Start AND @End GROUP BY 1 ORDER BY 2 DESC LIMIT 15"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'CRM-051', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "CRM-051", "kpi_name": "Sales Activity Completion Rate", "kpi_module": "CRM", "sub_area": "Activity", "is_active": true, "definition": "Proportion of scheduled sales activities executed to completion", "formula": "COUNT(status=''Completed'') / COUNT(status IN (''Completed'',''Planned overdue'')) x100", "unit": "%", "direction": "Up", "target": "≥ 90%", "frequency": "Weekly", "owner_role": "Sales Manager", "source_doctypes": "Activity", "key_fields": "status, start_at", "platform_equivalent": "Dynamics 365", "implementation": "Dashboard widget", "widget_id": "w_kpi_crm_051", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE status = ''Completed'')) / NULLIF(COUNT(*) FILTER (WHERE status = ''Completed'' OR (status = ''Planned'' AND COALESCE(end_at, start_at) < now())), 0), 2) AS value FROM reporting.activity WHERE start_at::date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'CRM-052', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "CRM-052", "kpi_name": "Overdue Sales Activities", "kpi_module": "CRM", "sub_area": "Activity", "is_active": true, "definition": "Planned customer engagement activities past scheduled execution deadline", "formula": "COUNT(status=''Planned'' AND end_at < CURRENT_TIMESTAMP)", "unit": "Activities", "direction": "Down", "target": "0", "frequency": "Daily", "owner_role": "Sales Representative", "source_doctypes": "Activity", "key_fields": "status, end_at", "platform_equivalent": "Dynamics 365", "implementation": "Dashboard widget", "widget_id": "w_kpi_crm_052", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT COUNT(*) AS value FROM reporting.activity WHERE status = ''Planned'' AND COALESCE(end_at, start_at) < now()"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'CRM-053', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "CRM-053", "kpi_name": "Total Sales Commission Earned", "kpi_module": "CRM", "sub_area": "Commission", "is_active": true, "definition": "Total sales commission compensation earned across sales teams in period", "formula": "SUM(CommissionStatement.total_commission)", "unit": "IDR", "direction": "Range", "target": "Per plan", "frequency": "Monthly", "owner_role": "Sales Operations", "source_doctypes": "CommissionStatement", "key_fields": "total_commission, period", "platform_equivalent": "NetSuite Incentive Comp; SAP Commissions", "implementation": "Dashboard widget", "widget_id": "w_kpi_crm_053", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT COALESCE(SUM(total_commission), 0) AS value FROM reporting.commission_statement WHERE docstatus = 1 AND posting_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'CRM-054', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "CRM-054", "kpi_name": "Commission as % of Revenue", "kpi_module": "CRM", "sub_area": "Commission", "is_active": true, "definition": "Sales commissions earned compared to qualifying revenue base", "formula": "SUM(total_commission) / SUM(total_base) x100", "unit": "%", "direction": "Range", "target": "Per commission rate plan", "frequency": "Monthly", "owner_role": "Sales Operations", "source_doctypes": "CommissionStatement", "key_fields": "total_commission, total_base", "platform_equivalent": "SAP Commissions", "implementation": "Dashboard widget", "widget_id": "w_kpi_crm_054", "implementation_note": "Period follows dashboard date filter (@Start/@End).", "widget_sql": "SELECT ROUND(100.0 * (SUM(total_commission)) / NULLIF(SUM(total_base), 0), 2) AS value FROM reporting.commission_statement WHERE docstatus = 1 AND posting_date BETWEEN @Start AND @End"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'CRM-055', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "CRM-055", "kpi_name": "Unprocessed Sales Commissions", "kpi_module": "CRM", "sub_area": "Commission", "is_active": true, "definition": "Active sales representatives lacking a generated commission statement for the cycle", "formula": "COUNT(active reps in active plan without CommissionStatement in current cycle)", "unit": "Reps", "direction": "Down", "target": "0", "frequency": "Monthly", "owner_role": "Sales Operations", "source_doctypes": "CommissionPlan, CommissionPlanRep, CommissionStatement", "key_fields": "sales_rep, period", "platform_equivalent": "SAP Commissions", "implementation": "Not available", "implementation_note": "The period field format on CommissionStatement is free-form (Data), so the current period cannot be reliably matched."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'MDM-001', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "MDM-001", "kpi_name": "Customer Master Completeness", "kpi_module": "CORE", "sub_area": "Master Data", "is_active": true, "definition": "Active customer accounts with tax ID, primary address, contact, and payment terms", "formula": "COUNT(tax_id, address, contact, payment_term filled) / COUNT(Active) x100", "unit": "%", "direction": "Up", "target": "≥ 98%", "frequency": "Monthly", "owner_role": "Master Data Management", "source_doctypes": "Customer", "key_fields": "tax_id, primary_address, primary_contact, payment_term", "platform_equivalent": "SAP MDG; NetSuite", "implementation": "Dashboard widget", "widget_id": "w_kpi_mdm_001", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE COALESCE(tax_id, '''') <> '''' AND primary_address IS NOT NULL AND primary_contact IS NOT NULL AND payment_term IS NOT NULL)) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.customer WHERE is_active"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'MDM-002', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "MDM-002", "kpi_name": "Vendor Master Completeness", "kpi_module": "CORE", "sub_area": "Master Data", "is_active": true, "definition": "Active supplier records with tax ID, verified bank details, and payment terms", "formula": "COUNT(tax_id, bank accounts, payment_term filled) / COUNT(Active) x100", "unit": "%", "direction": "Up", "target": "≥ 98%", "frequency": "Monthly", "owner_role": "Master Data Management", "source_doctypes": "Vendor", "key_fields": "tax_id, bank_accounts, payment_term", "platform_equivalent": "SAP MDG", "implementation": "Dashboard widget", "widget_id": "w_kpi_mdm_002", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE COALESCE(tax_id, '''') <> '''' AND payment_term IS NOT NULL AND EXISTS (SELECT 1 FROM reporting.vendor_bank_accounts b WHERE b.parent = v.name))) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.vendor v WHERE v.is_active"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'MDM-003', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "MDM-003", "kpi_name": "Duplicate Customer / Vendor Records", "kpi_module": "CORE", "sub_area": "Master Data", "is_active": true, "definition": "Potential duplicate master records identified by shared tax ID or legal name", "formula": "COUNT(GROUP BY tax_id HAVING COUNT(*) > 1)", "unit": "Records", "direction": "Down", "target": "0", "frequency": "Monthly", "owner_role": "Master Data Management", "source_doctypes": "Customer, Vendor, CRMSettings", "key_fields": "tax_id, duplicate_check", "platform_equivalent": "SAP MDG Duplicate Check", "implementation": "Dashboard widget", "widget_id": "w_kpi_mdm_003", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT (SELECT COUNT(*) FROM (SELECT tax_id FROM reporting.customer WHERE COALESCE(tax_id, '''') <> '''' AND NOT COALESCE(is_internal_customer, false) GROUP BY 1 HAVING COUNT(*) > 1) a) + (SELECT COUNT(*) FROM (SELECT tax_id FROM reporting.vendor WHERE COALESCE(tax_id, '''') <> '''' AND NOT COALESCE(is_internal_vendor, false) GROUP BY 1 HAVING COUNT(*) > 1) b) AS value"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'MDM-004', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "MDM-004", "kpi_name": "Items Without Default Accounting Accounts", "kpi_module": "CORE", "sub_area": "Master Data", "is_active": true, "definition": "Active items missing assigned income or expense accounts on item and group levels", "formula": "COUNT(is_active=1 AND missing income_account or expense_account on item and group)", "unit": "Items", "direction": "Down", "target": "0", "frequency": "Monthly", "owner_role": "Master Data Management", "source_doctypes": "Item, ItemGroup", "key_fields": "income_account, expense_account", "platform_equivalent": "SAP Material Master; NetSuite Item", "implementation": "Dashboard widget", "widget_id": "w_kpi_mdm_004", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT COUNT(*) AS value FROM reporting.item i LEFT JOIN reporting.item_group g ON g.name = i.item_group WHERE i.is_active AND ((i.is_sales_item AND COALESCE(i.income_account, g.income_account) IS NULL) OR (i.is_purchase_item AND COALESCE(i.expense_account, g.expense_account) IS NULL))"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'MDM-005', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "MDM-005", "kpi_name": "Expired Item Price Lists", "kpi_module": "CORE", "sub_area": "Master Data", "is_active": true, "definition": "Active price list rates where valid-to date expired without successor pricing", "formula": "COUNT(ItemPrice valid_to < CURRENT_DATE without current replacement)", "unit": "Prices", "direction": "Down", "target": "0", "frequency": "Monthly", "owner_role": "Sales Operations", "source_doctypes": "ItemPrice, PriceList", "key_fields": "valid_to", "platform_equivalent": "SAP Condition Records", "implementation": "Dashboard widget", "widget_id": "w_kpi_mdm_005", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT COUNT(*) AS value FROM reporting.item_price p WHERE p.valid_to < CURRENT_DATE AND NOT EXISTS (SELECT 1 FROM reporting.item_price n WHERE n.item = p.item AND n.price_list = p.price_list AND COALESCE(n.valid_to, DATE ''9999-12-31'') >= CURRENT_DATE)"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'MDM-006', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "MDM-006", "kpi_name": "Stock Items Without Default Warehouse", "kpi_module": "CORE", "sub_area": "Master Data", "is_active": true, "definition": "Inventory items missing an assigned default operating storage warehouse", "formula": "COUNT(is_stock_item=1 AND default_warehouse IS NULL)", "unit": "Items", "direction": "Down", "target": "0", "frequency": "Monthly", "owner_role": "Master Data Management", "source_doctypes": "Item", "key_fields": "default_warehouse", "platform_equivalent": "SAP", "implementation": "Dashboard widget", "widget_id": "w_kpi_mdm_006", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT COUNT(*) AS value FROM reporting.item WHERE is_active AND is_stock_item AND default_warehouse IS NULL"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'MDM-007', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "MDM-007", "kpi_name": "Incomplete Contact Records", "kpi_module": "CORE", "sub_area": "Master Data", "is_active": true, "definition": "Active business contacts missing both email address and phone number", "formula": "COUNT(is_active=1 AND email IS NULL AND mobile IS NULL)", "unit": "Contacts", "direction": "Down", "target": "0", "frequency": "Monthly", "owner_role": "Master Data Management", "source_doctypes": "Contact", "key_fields": "email, mobile", "platform_equivalent": "Dynamics 365", "implementation": "Dashboard widget", "widget_id": "w_kpi_mdm_007", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT COUNT(*) AS value FROM reporting.contact WHERE is_active AND COALESCE(email, '''') = '''' AND COALESCE(mobile, '''') = ''''"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'MDM-008', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "MDM-008", "kpi_name": "Current Fiscal Year Holiday List", "kpi_module": "CORE", "sub_area": "Master Data", "is_active": true, "definition": "Operational calendar verification confirming holiday list covers current fiscal year", "formula": "COUNT(HolidayList to_date >= end of year)", "unit": "Yes/No", "direction": "Up", "target": "Available before Jan 1", "frequency": "Annual", "owner_role": "HR Administrator", "source_doctypes": "HolidayList, Holiday", "key_fields": "from_date, to_date", "platform_equivalent": "Workday Holiday Calendar; SAP", "implementation": "Dashboard widget", "widget_id": "w_kpi_mdm_008", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT COUNT(*) AS value FROM reporting.holiday_list WHERE from_date <= make_date(EXTRACT(YEAR FROM CURRENT_DATE)::int, 1, 1) AND to_date >= make_date(EXTRACT(YEAR FROM CURRENT_DATE)::int, 12, 31)"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'MDM-009', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "MDM-009", "kpi_name": "Valid Payment Terms Configuration", "kpi_module": "CORE", "sub_area": "Master Data", "is_active": true, "definition": "Active payment terms verified where schedule portions total exactly 100%", "formula": "COUNT(total_portion=100) / COUNT(PaymentTerm) x100", "unit": "%", "direction": "Up", "target": "100%", "frequency": "Quarterly", "owner_role": "Finance Operations", "source_doctypes": "PaymentTerm, PaymentTermDetail", "key_fields": "total_portion", "platform_equivalent": "SAP / NetSuite", "implementation": "Dashboard widget", "widget_id": "w_kpi_mdm_009", "implementation_note": "Current snapshot; not affected by date filters.", "widget_sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE total_portion = 100)) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.payment_term WHERE is_active"}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
INSERT INTO frogframe_documents (tenant_id, doctype, name, owner, docstatus, created, modified, modified_by, version, schema_version, data) VALUES (:'tenant', 'KpiDefinition', 'MDM-010', :'owner', 0, NOW(), NOW(), :'owner', 1, 1, '{"kpi_code": "MDM-010", "kpi_name": "Chart of Accounts Dormancy Hygiene", "kpi_module": "CORE", "sub_area": "Master Data", "is_active": true, "definition": "Active posting leaf accounts with zero transaction activity in the last 12 months", "formula": "COUNT(Account is_group=0 AND is_active=1 without GL in 12 months)", "unit": "Accounts", "direction": "Down", "target": "Evaluated annually", "frequency": "Annual", "owner_role": "Chief Accountant", "source_doctypes": "Account", "key_fields": "is_group, is_active", "platform_equivalent": "SAP / NetSuite", "implementation": "Built-in report", "builtin_report": "TrialBalanceReport", "implementation_note": "Requires general ledger data (frogframe_gl_entries), which is not included in the reporting schema and cannot be used by widgets. Use the built-in TrialBalanceReport."}'::jsonb) ON CONFLICT (tenant_id, doctype, name) DO UPDATE SET data = EXCLUDED.data, modified = NOW(), modified_by = EXCLUDED.modified_by;
